FD.put("works.lod-11",{"works":{"lod.v01.0052":{"title":"Robert Treat Paine's Diary","author_label":"Robert Treat Paine","kind":"diary","date":"1774-09-15","date_label":"September 15, 1774","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 1","source_url":"https://archive.org/details/lettersofdelegat01smit","text_status":"unreviewed_ocr","editorial_source_note":"MS (MHi) .","authors":["robert-treat-paine"],"paras":[["h","Robert Treat Paine's Diary"],["p","[September 15, 1774] Fine day. Dind Mr. Wallace. Wrote to Dr. Cobb 8c Brother Greenleaf by Capt. Goodhue of Salem."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v01.0471":{"title":"Samuel Adams to Joseph Warren","author_label":"Samuel Adams","kind":"letter","date":"1775-06-20","date_label":"June 20, 1775","date_type":"written","recipient":"Joseph Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 1","source_url":"https://archive.org/details/lettersofdelegat01smit","scan_url":"https://archive.org/details/lettersofdelegat01smit/page/519","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi) .","authors":["samuel-adams"],"paras":[["h","Samuel Adams to Joseph Warren"],["p","Dear sir Philada June [20,] 17751"],["p","I have but one Moment to inform you that this Congress having as I before wrote you appointed General Washington to the Command of all the American Forces, and Majors General Ward & Lee, they yesterday proceeded to the Appointment of two more Majors General viz Schuyler and Putnam. General Lee has accepted of his Appointment and will I suppose tomorrow set off with General Washington for Cambridge. The Congress seems determined to support their Army before Boston. They are fully sensible of the Importance of it & have recommended to the Colonies of Connecticutt R Island & N Hampr. to send the Troops they have agreed to raise without Delay to Cambridge, those to remain till further orders (excepting such as were destind to the several Posts in the Colony of N York) . You have doubtless been informed by Mr H[ancock] that you may soon expect ten Companies of Rifle Men to joyn the Army."],["p","I am more & more satisfied in the Appointmt of Genl. Lee. He is certainly an able officer & I think deeply embarkd in the American Cause. The Congress have agreed to indemnify him from any Loss of Property he may sustain by acting as an officer in the Army,2 but this I mention only to you at present & the small Circle. If any should be disaffected to his Appointment pray use your utmost Endeavours to reconcile them to it. I am in great Haste. Your assured friend"],["p","S. Adams"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v02.0005":{"title":"Benjamin Franklin to David Hartley","author_label":"Benjamin Franklin","kind":"letter","date":"1775-09-12","date_label":"September 12, 1775","date_type":"written","recipient":"David Hartley","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 2","source_url":"https://archive.org/details/lettersofdelegat02smit","scan_url":"https://archive.org/details/lettersofdelegat02smit/page/4","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC) . In Franklin's hand, though not signed.","authors":["benjamin-franklin"],"paras":[["h","Benjamin Franklin to David Hartley"],["p","Dear Sir, Philada. Sept. 12. 1775"],["p","I have this Day received your Favours per Capt. Falconer, of which more in my next. With this I send you a number of Newspapers and Pamphlets, by which you will see Things are become serious here. Your Nation must stop short, & change its Measures, or she will lose the Colonies forever. The Burning of Towns, and firing from Men of War on defenceless Cities and Villages filled with Women & Children; The exciting the Indians to fall on our innocent Back Settlers; and our Slaves to murder their Masters; are by no means Acts of a legitimate Government. They are of barbarous Tyranny and dissolve all Allegiance. The Insolence of your Captains of Men of War is intolerable But we suppose they know whom they are to please. I shall endeavour to procure the Petitions so that you may have them against Winter: they cannot be collected suddenly. With the highest Esteem, I am Yours most affectionately."],["p","[P.S.] Pray present my Respects to Mr Burke, to whom, & to you I shall write fully by the first safe hand."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v02.0081":{"title":"Samuel Adams to Elbridge Gerry","author_label":"Samuel Adams","kind":"letter","date":"1775-09-26","date_label":"September 26, 1775","date_type":"written","recipient":"Elbridge Gerry","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 2","source_url":"https://archive.org/details/lettersofdelegat02smit","scan_url":"https://archive.org/details/lettersofdelegat02smit/page/63","text_status":"unreviewed_ocr","editorial_source_note":"RC (NjHi) .","authors":["samuel-adams"],"paras":[["h","Samuel Adams to Elbridge Gerry"],["p","My dear Sir Philada Sept 26 1775"],["p","I arrived in this City on the 12 Instant having rode full three hundred Miles on horseback, an Exercise which I have not used for many years past. I think it has contributed to the Establishment of my Health, for which I am obligd to my Friend Mr John Adams who kindly offered me one of his Horses the day after we set off from Watertown."],["p","I write you this Letter, principally to put you in Mind of the promise you made me to give me Intelligence of what is doing in our Assembly and the Camp. Believe me sir it is of great Importance that we should be informd of every Circumstance of our Affairs. The Eyes of Friends and Foes are attentively fixed on our Province, and if Jealousy or Envy can sully its Reputation, you may depend upon it they will not miss the opportunity. It behoves our Friends therefore to be very circumspect, and in all their publick Conduct to convince the World, that they are influenced not by partial or private Motives but altogether with a View of promoting the publick Welfare."],["p","Some of our Military Gentlemen have, I fear, disgracd us; It is then important that every Anecdote that concerns a Man of real Merit among them (and Such I know there are) be improvd, as far as decency will admit of it, to their Advantage and the Honor of a Colony which for its Zeal in the great Cause as well as its Sufferings, deserve so much of America."],["p","Until I visited head Quarters at Cambridge, I had never heard of the Valor of Prescot on Bunkers Hill, nor the Ingenuity of Knox and Waters in planing the celebrated Works at Roxbury. We were told here that there were none in our Camp who understood this Business of an Engineer, or any thing more than the manual Exercise of the Gun. This wc had from great Authority, and for want of more certain Intelligence were obligd at least to be silent. There are many military Geniuses at present unemployd and overlookd, who I hope, when the"],["p","Army is new modelld, will be sought after and invited into the Service of their Country. They must be sought after, for modest Merit declines pushing it self into publick View. I know your disinterested Zeal and therefore need add no more than to assure you that I am with cordial Esteem Your Friend Saml Adams"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v02.0103":{"title":"John Adams to James Warren","author_label":"John Adams","kind":"letter","date":"1775-09-30","date_label":"September 30, 1775","date_type":"written","recipient":"James Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 2","source_url":"https://archive.org/details/lettersofdelegat02smit","scan_url":"https://archive.org/details/lettersofdelegat02smit/page/80","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi) .","authors":["john-adams"],"paras":[["h","John Adams to James Warren"],["p","Dr sir Philadelphia Septr. 30. 1775"],["p","Mr Lynch, Coll Harrison, and Dr Franklyn are preparing for a Journey to Watertown and Cambridge, one of whom will do me the Favour of taking this Letter."],["p","Mr Lynch, you have seen before. He is an oppulent Planter of great Understanding and Integrity and the best affections to our Country and Cause."],["p","Coll Harrison is of Virginia, and the Friend and Correspondent of the General, but it seems by a certain Letter, under some degree of Prejudice against our dear New Englandmen. These Prejudices however, have arisen from Misrepresentation and may be easily removed."],["p","Dr Franklyn needs nothing to be said. There is no abler or better American, that I know of."],["p","I could wish a particular Attention and Respect to all Three."],["p","I know you will be pleased to be introduced to these Gentlemen, because it will give you an opportunity of serving your Country.1 I am your Friend Jonn Adams"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v02.0143":{"title":"John Hancock to George Washington","author_label":"John Hancock","kind":"letter","date":"1775-10-05","date_label":"October 5, 1775","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 2","source_url":"https://archive.org/details/lettersofdelegat02smit","scan_url":"https://archive.org/details/lettersofdelegat02smit/page/117","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC) .","authors":["john-hancock"],"paras":[["h","John Hancock to George Washington"],["p","Sir Philadelphia Octobr. 5th. 1775"],["p","The Congress having this day Rec'd certain Intelligence of the Sailing of Two North Country built Brigantines, of no Force, from England on the 11th. of August last, loaded with Six Thousand Stand of Arms, a large Quantity of Powder, & other Stores for Quebec, without Convoy, and as it is of great importance if possible to intercept them, I am order'd by the Congress to Give you this information, and to Desire you immediately to Apply to the Council of the Massachusetts Bay for the Two Arm'd Vessells in their Service, and Dispatch the same, with a sufficient Number of people, Stores &c particularly a Number of Oars in order if possible to intercept said Brigantines and their Cargoes, and secure the same for the Use of the Continent. It is also their Desire that you Give orders to the Commanders of the Vessells you Send on this Service to Seize and take any other Transports laden with Ammunition, Cloathing or other Stores for the Use of the Ministerial Army or Navy in America which they may meet with, & Secure them in the most convenient places for the use of the Continent."],["p","That you Give the Commander or Commanders such instructions as are necessary, and also proper incouragements to the Marines and Seamen that shall be Sent on this Enterprize. That the instructions you shall Give be Deliver'd to the Commander or Commanders Sealed up, with Orders not to Open the same untill out of Sight of Land on Accott. of Secrecy. If the Vessells in the Service of Massachusetts Bay can be Readily obtain'd you are to Employ them, and others if you shall think necessary to Effect the purposes aforesaid; if they cannot, then you will Employ such as can be soonest fitted out. At the same time I am directed to inform you that the Rhode Island and Connecticutt Vessells of Force, if possible, will be directly sent after to the Assistance of those you Send out, for which purpose I write by order of Congress to those Governmts. by this Conveyance."],["p","For the Encouragement of the Men employ'd in this Service, I am to inform you that the Congress have Determin'd that on this Occasion, the Master, Officers and Seamen shall be entitled to one half of the Value of the Prizes by them taken, the Wages they Receive from their respective Colonies notwithstanding."],["p","It is further Resolved that the Ships or Vessells of War employ'd in this Service are to be on the Continental Risque and pay during their being thus Employ'd."],["p","For further Intelligence I Refer you to the Inclos'd, which have not Time to Copy, as I am order'd to Dispatch the Express immediately."],["p","I have the honour to be, Sir Your most Obedt hum Sevt."],["p","John Hancock Presidt."],["p","[P.S.] The Inclos'd please to order to be Del[ivere]d to the Council of Massa [chuset] ts Bay."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v02.0194":{"title":"Samuel Adams to James Warren","author_label":"Samuel Adams","kind":"letter","date":"1775-10-13","date_label":"October 13, 1775","date_type":"written","recipient":"James Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 2","source_url":"https://archive.org/details/lettersofdelegat02smit","scan_url":"https://archive.org/details/lettersofdelegat02smit/page/178","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi) .","authors":["samuel-adams"],"paras":[["h","Samuel Adams to James Warren"],["p","My dear sir, Philadelphia Octob. 13th 1775"],["p","It is now more than a Month since we arrivd in this City. I have receivd but one Letter and for that I am much indebted to you. I thought our Assembly had appointed a Committee to transmit Intelligence to us. We hear nothing from them. Have they no Intelligence of Importance to send to us? If so, let them inform us even of that, and we will pay the Postage of their Letter. But surely it is of some Importance that we should know whether C[hurch] is a Traiter or not — that on the one hand we might joyn like disinterrested Patriots in execrating him, or on the other hand, in vindicating the Character of an unfortunate Friend. Our pride is sorely mortified when there are Grounds to suspect that so eminent a Countryman is become a Traiter. The Fool will say in his heart, there is no such thing in the World as publick Spirit — the most virtuous Citizen will be suspected of concealing his dishonest Designs under a Cloak of Zeal for his Country and the brightest Examples will lose their Influence."],["p","I am very sollicitous that our Army, if it be practicable, should make a resolute Attack upon the Rebels before a Reinforcement to them shall arrive, which I think may be depended upon very soon. Genl Gage I understand is already gone for England. This verifies a part of the Intelligence which I gave you in my last Letter. Howe will remain in Command till the Spring when Amherst will come out as"],["p","strong as they can make him. It is said that usd his utmost"],["p","Power of Dissimulation (and he is as great a Master of it as Mansfield or Hutchinson) to prevail on him to undertake the Command. Among the officers of the British Army, the Slavish Maxim \"The Will of the Prince is Law\" too much prevails. They will suffer the arbitrary and cruel Commands of their Sovereign to supercede the Dictates of Honor, Morality and Conscience. I fear there are few, if"],["p","more than one Effingham to he found in Britain. I have thought there was more of the true principle of Honor in the British Army, than among any other puhlick Class. If this be a Truth it is a melancholly one, for it is greatly to be apprehended that there is not Virtue enough in the Nation to save it. We know by long Experience that there is not Virtue enough there to save America. Why then should America expect it from Britain. This fond Hope of a Change from violent to lenient Measures in Britain is the Rock which endangers the Shipwreck of America."],["p","This Instant is arrivd an authentick Account of Dr Churchs Affair and a Copy of the Letter he had intended to send into Boston. To me it appears to be a very unintelligible Letter — I have not indeed thoroughly examind it — I have only heard it read. I do not recollect that it in any measure was calculated to expose the Weakness of our Army, which a Traitor would gladly have seizd the opportunity of doing, especially as he might have done it at that time with great Truth. The Union of Individual Colonies & of the Continental Congress, and their firmness and Resolution are picturd in high Colours; he informs of the Arrival of large Quantities of Gun powder at a time when he knew there was the greatest Scarcity, and was sollicking his Friends here to take every Method for providing as he expressed it that \"unum necessarium.\" Other parts of his Letter wear a different Complection, such as his mentioning the Defeat of our Army at Bunkers Hill as \"lucky,\" his attempting three times in vain to send in his Letter, the messenger in the third Attempt being taken up (which I do not recollect to have heard before) and the Manner in which this Letter was conceald. But I will quit this disagreable Subject and conclude with assuring you that I am very affectionately, yours"],["p","S A"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v02.0278":{"title":"John Adams to Abigail Adams","author_label":"John Adams","kind":"letter","date":"1775-10-29","date_label":"October 29, 1775","date_type":"written","recipient":"Abigail Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 2","source_url":"https://archive.org/details/lettersofdelegat02smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi) . Adams, Family Correspondence (Butterfield) , 1 : 316—17.","authors":["john-adams"],"paras":[["h","John Adams to Abigail Adams"],["p","Octr. 29. 1775"],["p","I cannot exclude from my Mind your melancholly Situation. The Griefs of your Father and Sisters, your Uncles and Aunts, as well as the remoter Connections, often croud in upon me, when my whole Attention ought to be directed to other Subjects."],["p","Your Uncle Quincy, my Friend as well as Uncle, must regret the loss of a beloved Sister, Dr. Tufts my other Friend I know bewails the loss of a Friend, as well as an Aunt and a sister, Mr. Cranch the Friend of my youth as well as of my riper Years, whose tender Heart sympathizes with his fellow Creatures in every Affliction and Distress, in this Case feels the Loss of a Friend, a fellow Christian, and a Mother."],["p","But alas what avail these mournfull Reflections. The best Thing We can do, the greatest Respect We can show to the Memory of our departed Friend, is to copy into Our own Lives, those Virtues which in her Lifetime rendered her the Object of our Esteem, Love and Admiration. I must confess I ever felt a Veneration for her, which seems increased by the News of her Translation."],["p","Above all Things my dear, let us inculcate these great Virtues and bright Excellencies upon our Children.1"],["p","Your Mother had a clear, and penetrating Understanding and a profound Judgment, as well as an honest and a friendly and a charitable Heart."],["p","There is one Thing however, which you will forgive me if I hint to you. Let me ask you rather, if you are not of my opinion? Were not her Talents, and Virtues too much confined, to private, social and domestic Life. My Opinion of the Duties of Religion and Morality, comprehends a very extensive Connection with society at large, and the great Interest of the public. Does not natural Morality, and much more Christian Benevolence, make it our indispensible Duty to lay ourselves out, to serve our fellow Creatures to the Utmost of our Power, in promoting and supporting those great Politicial systems, and general Regulations upon which the Happiness of Multitudes depends. The Benevolence, Charity, Capacity and Industry which ex-"],["p","276 October 29, 177 a"],["p","erted in private Life, would make a family, a Parish or a Town Happy, employed upon a larger Scale, in Support of the great Principles of Virtue and Freedom of political Regulations might secure whole Nations and Generations from Misery, Want and Contempt. Public Virtues, and political Qualities therefore should be incessantly cherished in our Children."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0034":{"title":"John Hancock to George Washington","author_label":"John Hancock","kind":"letter","date":"1776-01-06","date_label":"January 6, 1776","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC). Written by Charles Thomson and signed by Hancock.","authors":["john-hancock"],"paras":[["h","John Hancock to George Washington"],["p","Sir, Philada. Jany. 6. 1776"],["p","I have the honor of enclosing you sundry resolutions passed yesterday respecting Mr Lovell.1"],["p","The Congress are desirous to know your opinion what rank it would be proper the aide de camp of the general Officers ought to hold in the army and on this head I am directed to write to you & request yr. answer.2"],["p","Just after the receipt of your letter Conolly & Cameron were brought to town. By some mismanagement, Smith one of the associates was suffered to escape from Frederic where they were confined. Orders were given to have the saddles examined, but nothing is discovered. There is reason to believe he must have found means to withdraw his"],["p","William Livingston"],["p","papers, as we find by an account from Frederic that his saddle was mended there.3"],["p","The French gentlemen are arrived and referred to the secret committee.4"],["p","The Congress have given orders to general Schuyler 5 immediately to secure and keep in safe and close custody Brigr. general Prescot until further orders.6"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0122":{"title":"John Dickinson's Draft Address to the Inhabitants of America","author_label":"John Dickinson","kind":"draft","date":"1776-01-24","date_label":"January 24, 1776","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","scan_url":"https://archive.org/details/lettersofdelegat03smit/page/139","text_status":"unreviewed_ocr","editorial_source_note":"MS (PHi). In the hand of John Dickinson.","authors":["john-dickinson"],"paras":[["h","John Dickinson's Draft Address to the Inhabitants of America"],["p","[January 24? 1776] » How far We have discharged it with skill, must be determined by You, who are our Principals and Judges, to whom We esteem it our Duty as faithful Servants, to render an Account of our Conduct, our Motives, the situation of our Affairs, and the Ends We have kept and still keep in View.2"],["p","We think it unnecessary to recapitulate all the Circumstances of the present unhappy Controversy with G B, previous to our appointment. They have been so frequently and fully [discussed?] in several Publications, that we shall content ourselves with recommending to your Perusal for particular Information on that subject, the Address made to You by the late Congress."],["p","In brief, the Sentence of universal Slavery has gone forth against You, declaring, \"that his Majesty in Parliament hath a Right to bind You by Statutes & Laws in all Cases whatsoever.\" Your Fortunes, your Liberties, your Lives — every Thing that cm render You or your Posterity happy — all are the Objects of Laws: all must be enjoyed, impaired, or destroyed, as the Laws direct. From this monstrous & detestable position just [. . .] Parliament inferrs, that You are a miserable People, the lowest Class of Wretches in human shape, who have nothing, that of Right You can or ought to call^owr own. All the Bounties of Nature, all the Blessings of Providence, your Health, your Strength, the Fertility of your Country, the Commerce of your ports, the Riches of your Seas & Rivers, the Profits of your Industry, Prudence & Virtue, all these they contend, were not design'd for your own Use, but for the use of those,3 who by some inexplicable Mistery of Politics, in opposition to all Reason, Equity & Humanity, hold an unbounded & superriding Authority over your persons and consequently over every possession You have accustomed to consider as belonging to Your persons. The"],["p","Acts of Parliament for taxing You against your Consent, for shutting up the Port of Boston, indemnifying the \"Murderers'''' of the Inhabitants of the Massachusetts Bay and [altering?] their chartered Constitution of Government, for altering the Government of Quebec, thereby depriving the People of an Assembly, trials by Jury and the English Laws, and extending the Limits of that province so as to comprehend those vast Regions that lye adjoining to the northernly & westernly Boundaries of these Colonies, are all parts of the grand System of Operations lately concerted for carrying that direful Sentence into Execution with full Effect."],["p","Before We assembled in last May, and while You were waiting patiently for the Result of his Majesty's Determinations in Parliament on the humble & dutiful Petition from the late Congress, which one of the principal Secretaries of State told our Agents, \"was a decent one & had been graciously received,\" the answer was unexpectedly written in Letters of Blood at Lexington and Concord by the unprovoked Murder of our brave Fellow Citizens."],["p","War having been thus wantonly and cruelly begun by our Enemies, We met together at Philadelphia."],["p","Immediately taking the State of these Colonies into our most serious Consideration, and having no other Objects in View, than their Defence and Preservation against the Force actually employed for executing the destructive System before mentioned, and the Restoration of the former Harmony with G.B., these Resolutions were formed. (Here insert the Resolutions beginning with these Words, \"Resolved unanimously\" inclusively in pa. 62 to the Words \"the King\" in pa. 64 — inclusively.)"],["p","Knowing, that we represented a People who preferr'd Death to servitude, a People whose Loyalty to their Sovereign and whose Affection to their British Fellow subjects on the other side of the Atlantic, all the Outrages of Administration had not extinguished, We endeavoured to combine their magnanimous and generous Sentiments in our Determinations."],["p","In order to render your Resistance successful as to the objects of the war already pointed out, and also to defend You as much as possible from Suffering in the Course of it, we not only employed a large Army in the Colony of Massachusetts Bay, then actually invaded by your Enemies, and a smaller one in the Colony of New York, which we expected to be soon invaded; but have used our utmost Industry to put the Militia of all the Colonies upon the best footing, to import arms and military Stores from foreign Countries & to promote the Manufactory of those Articles on this Continent. We can with Truth, and with a Pleasure of which every worthy American may be sensible, inform You, that our Counsels have been prosecuted with such spirit & Prudence by all Ranks of People, but more especially by the several Assemblies, Conventions, Councils of Safety & Committees"],["p","of Observation, whose Zeal & Wisdom merit the highest Applauses from all Lovers of their Country, that these Colonies are now put into a respectable State of Defence, which will in a short Time certainly receive great Additions by the Accomplishments of some well founded Measures, of which we have not the least Reason to doubt."],["p","These Efforts were soon attended with such Effect, that the British Army still confined within the Town of Boston & its Environs, and the Fleet sent to cooperate with it, finding the Fruits of their plundering our seacoasts too precarious and dangerous, Ships of war began to seize our vessels, carry them to Boston & take out their Cargos of provisions. It therefore became expedient to make some Regulations to prevent their receiving such supplies, which have been effectual."],["p","The war being thus prosecuted against these Colonies by Sea as well as by Land, Several armed vessels have been fitted out by us, and many considerable Captures have been made of Transports loaded with warlike Stores and Provisions for the army in Boston."],["p","Upon this same Principle of self preservation, founded on the Laws of Nature, and justified by the Laws of Nations, We approved of an Expedition into Canada, against the British Forces in that Province. With such a dangerous Caution did We proceed in this important Measure, that when the proposal was first made in Congress, it was rejected: But sometime after, receiving undoubted Intelligence that Governor Carleton was by every Artifice exciting our fellow subjects in Canada & the Indians to commence Hostilities, and that Administration entertained Designs and Expectations of putting these Colonies between two Fires, and even of carrying on the War by the worst of Assassinations, even those of Women & Children, in letting loose & enflaming the Tribes of Barbarians, with whom Mercy is a Reproach, We judged, that We should be impardonably criminal with Regard to You, who had put your Lives into our Hands, if We hesitated any longer to frustrate as much as We could the cruel Machinations of your Enemies."],["p","We knew Governor Carleton's Forces were not great, but We also knew the Power vested in him by the late act of Parliament for changing the Government of that Province to be so exorbitant, that there was Reason to fear, that, if he was allowed time to strengthen himself in quiet, by using all the advantages his authority or art could give him, he would quickly grow formidable. Besides, We were convinc'd that if he requested Assistance from G.B. it would be sent to him early in the Spring; and that whenever he was fully prepared, the Storm would burst with its greatest Fury by the Way of the Lakes on the Colonies of New York, Connecticut & New Hampshire, and if the first of those Colonies should at the same Time be attacked from the Sea, he might make a very considerable Impression. Influenced by these Reasons, We directed the army in the Colony of New York, where its Reserve was not so immediately necessary, to march into Canada. You are now in Possession"],["p","of the whole Province except Quebec. All the success We could expect has attended your Arms; but great as it has been, We almost regret advantages purchased at so high a Price as the Life of General Montgomery."],["p","Several large Reinforcements are now marching into that Country, and others will soon follow them. The Inhabitants are well affected to your Cause."],["p","The Indians in the northern, middle & southern Departments, have entered into Treaties of Friendship with You."],["p","It seems needless to us, to give a more particular Detail of our Transactions, and the Events that have happened in Consequence of them, because they have been so regularly communicated to You in the public Prints."],["p","Upon the whole, the situation of your Affairs at present appears to us to be so favorable, that We can look in the Face the Trials preparing for Us next spring without Terror. The Justice of your Cause is a perpetual Source of Comfort to us. We humbly hope, that the all wise and all gracious Ruler of the Universe, will bless the Means afforded you by his Goodness, and employed for the purpose of preserving the Innocent from the Fury of their unprovoked Foes. He hath declared, that he \"will be a Refuge for the oppressed in Times of Trouble,\" and We trust in his sacred promise. But, beloved Brethren, We most earnestly beseech You, that You will not confide too much in the Injustice of your Adversaries, for a Recommendation of yourselves to the Divine protection. Let every Individual entering into a strict Examination of himself, & renouncing and repenting of his Offences, cultivate such Affections, and observe such a Tenor of Conduct for the Future, as he knows will be pleasing to the Allmighty, & may thro his infinite Mercys procure Favor to this distressed Land. We entreat You also in your applications to the Throne of Grace, to remember us, on whom You have devolved Duties so important and so difficult, and fervently to pray, that We may be endued with wisdom to conduct your Affairs in the most advantageous Manner amidst the Convulsions that now shake the British Empire to its deepest Foundations."],["p","Upon a Review of our whole Conduct We do not recollect a single Step We have taken that appear'd so likely to draw down upon Us the Censure of our Constituents, as our Petition to the King. After so many Petitions from assemblies had been treated by Administration with such Uniformity of Contempt; after the Petition from the late Congress had been not only treated in the same Manner, but had been immediately succeeded by Fleets & Armies sent to invade Us, by the Slaughter of our Countrymen and by the Burning of Charlestown, petitioning seem'd not only to be useless, but even dangerous, as that Mode of proceeding had so recently produced additional Rage and fresh Violences on the Part of our Enemies."],["p","However, so passionate was our Desire to stop the Effusion of British"],["p","Blood by British Hands, and to bind up the wounds of this unnatural War, that We resolved once more to lay his American People in all Humility at his Majesty's Feet, and to strive, if it were possible, to frame our address in such a manner, as might procure some Degree of Attention to our Supplications. We had been well inform'd that all the Petitions from America for several Years past, had been rejected, because they insisted on Claims said to be derogatory of the Dignity and Authority of the British Crown & Parliament. We therefore determined to make an Attempt hitherto untried on this Continent, and thro the Representatives of so many united Colonies, to use a Language, which no single Colony had ever condescended to employ. Sincerely aiming at Peace & Reconciliation, We avoided every Expression, that might raise any Obstruction to the attainment of those desired Objects, by irritating Minds, however causelessly, which We wish'd to sooth into a Temper equally amicable with our own. Accordingly waving even the slightest mention of every Right & every Grievance, We confined ourselves to the measured, & even in the opinion of our Enemies, respectful Terms, of praying for \"Relief from our Fears & Jealousies,\" and \"that his Majesty would be pleased to direct some Mode, by which the united applications of his faithful Colonists, in Pursuance of their Common Councils, might be improved into a happy & permanent Reconciliation.\""],["p","Thus, the injured made the first Advance for promoting Peace, which perhaps might have been made more consistently with the Character of a magnanimous Nation, by the Aggressors; and in making this proposal, tho a cruel War was then levied against Us in his Majesty's Name, yet we carried our Reverence for the royal Character so far, that sufficiently declaring our Meaning, yet We forbore using the Word Treaty, least the Term should appear too harsh, when offered by subjects to their sovereign. Nor could we devise a more dutiful and unexceptionable Method of conveying our ardent and loyal Wishes to his Majesty, than by relying on his \"wisdom\" for \"the Direction of a Mode\" that might improve the Requests of his American subjects into a perfect accommodation. It appeared to us too, a fortunate Circumstance, that our Petition would be delivered to his Majesty by so respectable a Gentleman as the honorable Richard Penn Esquire late Governor of Pennsylvania, who had taken no Part in the present unhappy Dispute."],["p","Having in this Manner guarded aginst every Objection to the gracious Reception of our Petition, We nattered ourselves that it would produce the desired Effect. The Exception taken by some persons against the Reception of the former Petition, because a Congress is a Body not known to the Constitution, we considered as too frivolous to damp our Expectations. We all individually signed the Petition, \"in behalf of ourselves and the Inhabitants of these Colonies,\" and our President"],["p","signed as a Common Member, without the Addition of his Office. So that tho We mentioned a Matter of Fact, that the Inhabitants of these Colonies had deputed us to represent them \"in general Congress,\" yet that Circumstance could not deprive us of the Right of petitioning, which is so solemnly recognized & established by the Bill of Rights. This Right is the same, whether the Petition be that of one or of many. The very Reason alledged in the Exception, is a Reason for receiving a Petition from a Number of his subjects, even tho they stiled their Meeting a Congress, which indeed is convertible Terms with the other: For if a Congress is a \"Body not known to the Constitution,\" the Reception of a Petition from a Congress, is not an Acknowledgment express or implied, of any Powers, Authority or Priveledges as attended or annexed to such a Body: Whereas, on the other side, if the Framers of a Petition usurp or unjustly assume the Name or Title of a Body known to the Constitution, the general Reception of their Address might involve in it in some Degree an Acknowledgment that the Powers, Authority or Priviledges attach'd by the Constitution to such a Body, were vested in the Petitioners. Let the advocates for the mistaken Dignity of the British Government point out the constitutional Principles that warranted the Assembly of the Barons at Runnamede when Magna Charta was granted, the Convention Parliament, that restored Charles the second, and the Convention of Lords & Commons that placed William on the Throne at the Revolution. When they have done this, We shall perhaps be able to apply their Principles to prove the propriety & Legality of a Congress.4"],["p","As our Enemies well knew, that We were vested with the highest Trust & Power, which the Freemen of their united Colonies could delegate, and acted in pursuance of that Trust & Power for them, We were perswaded administration could not neglect a Petition in every Respect so unexceptionable, and containing such Grounds for an honourable and advantageous Accommodation with G.B. unless they were resolved to reduce Us to the unconditional submission heretofore dictated to Us, by the Edge of the Sword. This Conduct, as We had by the last Measure exhausted all peacable Modes of obtaining Redress, We were assured, would convince every Man of Sense upon the Continent, that these Colonies could only rely, in an humble Dependance on Divine Providence, upon their own virtuous & vigorous Exertions for Relief. Contrary 5"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0217":{"title":"John Hancock to Thomas Cushing","author_label":"John Hancock","kind":"letter","date":"1776-02-13","date_label":"February 13, 1776","date_type":"written","recipient":"Thomas Cushing","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","scan_url":"https://archive.org/details/lettersofdelegat03smit/page/243","text_status":"unreviewed_ocr","editorial_source_note":"MS not found; reprinted from Proceedings of the Massachusetts Historical Society 60 (January 1927): 102-4.","authors":["john-hancock"],"paras":[["h","John Hancock to Thomas Cushing"],["p","My Dear Sir, Philadelphia, 13 Feby., 1776."],["p","Your favor of Jany. 30th I have now before me, am glad to hear the Reception you met with, and have no Doubt but you will ever Acquit your self the honest Man, and be superior to the Arts and Cunning of Designing Men. I am Oblig'd to you for the hints you give respecting"],["p","the Designs of some against me, and wish in your next [you] would be as particular as possible, and let me know every thing passing in your Quarter, by the State of the Elections neither you or I were much Neglected. I am much oblig'd to the Assembly for their Notice of me in the Militia, etc.1 I intended writing you a long Letter by this Opportunity, but I am so engag'd, and indeed I trust the next Post will Reach [Cambridge] as soon as Col. Bull who carries this and has Charge of the Money to the General; that I have only Time to Acquaint you that by Col. Bull I have sent you the Two Drafts for the Ships, and beg the closest Attention may be paid to them, and pray hurry them on as fast as possible, Employ as many persons as possible. I have also sent you by Col. Bull Twenty five Thousand Dollars towards the Expence of the Ship, etc. It is pack'd in a Box directed to you, and you will please to send me a Receipt for it; I will send you some more Money by the Person I desir'd you in my last to send, and by him will write you or sooner, more particularly. Inclos'd you have Dimensions, etc. of the Ships for your Guide. Pray inform me in your next how much Hemp, Cordage, etc. you have or can purchase; as to the Iron you must get it on the best Terms you can, as it will be impossible to get it from hence. As to Cannon more in my next upon that head, the Committee have not yet reported on that matter. Let me know in your next how much Duck you will want and it will be sent from New York. Do engage every Article you can and let me know your Success as soon as possible. Let me know your prospect as to Iron. I beg you will be very particular in your next; pray employ as many hands as can possibly be usefull about the Ships, don't be behind any of the Colonies. I Rely much on your Activity. I will send you as much more Money as I can obtain.2"],["p","The purport of this is only to Inform you of sending the Plans and Money, don't forget to send me a Receipt for the Money, and do let me know how you go on. I have Deliver'd to Col. Bull a Plan for Mr. Langdon of Portsmouth to your Care, do forward it to him. I shall write you more particular by next."],["p","Lord North's Motion of the 20 Novr. bodes no Good, but as you undoubtedly have it, I need not enlarge; the making all our Vessells lawful Prize don't look like a Reconciliation. 3"],["p","Do let me hear from you by all Opportunities. As my next Letter will probably Reach you before this I will not add, save my best Respects to Mrs. Cushing and Family. I hope she has not Taken amiss the Freedoms I used on the Back of your quondam Letters, you know my Disposition and Intentions and you must Reconcile it to her."],["p","I wish you every Blessing and am with solid Friendship, Dear Sir, your's very sincerely"],["p","[P.S.] Col. Dickinson marches in a few days at the head of a Battalion of Philadelphia Associators to join Genl. Lee at New York.4 Mrs. Hancock begs her Regards to you and Mrs. Cushing."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0339":{"title":"Benjamin Franklin to Philip Schuyler","author_label":"Benjamin Franklin","kind":"letter","date":"1776-03-11","date_label":"March 11, 1776","date_type":"written","recipient":"Philip Schuyler","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","scan_url":"https://archive.org/details/lettersofdelegat03smit/page/367","text_status":"unreviewed_ocr","editorial_source_note":"RC (NN).","authors":["benjamin-franklin"],"paras":[["h","Benjamin Franklin to Philip Schuyler"],["p","Sir Philade. March 11. 1776"],["p","The Congress have appointed three Commissioners to go to Canada, of which Number I have the Honour to be one. We purpos' setting out some day this Week. I take the Liberty of mentioning this, as possibly a little previous Notice may enable you more easily to make any Preparation you shall judge necessary to facilitate and expedite our Journey, which I am Sure you will be kindly dispos'd to do for us. A Friend with us will make our Company Four, besides our Servants. We shall either come in Carriages directly to Albany, or by Water, if the River is open, from N York."],["p","Hoping Soon for the Pleasure of seeing you I now only add, that I am, with the sincerest Esteem and Respect, Sir, Your most obedt, humble Servant, B Franklin"],["p","P.S. The Bearer M. Le Jennesse has been considered by the Congress as a Friend to the American Cause, and he is recommended to your Protection in his Return to Canada.1"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0405":{"title":"Benjamin Franklin to James Bowdoin","author_label":"Benjamin Franklin","kind":"letter","date":"1776-03-24","date_label":"March 24, 1776","date_type":"written","recipient":"James Bowdoin","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","scan_url":"https://archive.org/details/lettersofdelegat03smit/page/435","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi).","authors":["benjamin-franklin"],"paras":[["h","Benjamin Franklin to James Bowdoin"],["p","My dear Friend, Philada. Mar. 24. 1776"],["p","Inclos'd is an Answer to the Request from the Inhabitants of Dartmouth. I have comply'd with it upon your Recommendation, and ordered a Post accordingly.1"],["p","I have put into Mr Adam's Hands directed for you, the new Edition of Vattel. When you have perus'd it, please to place it in your College Library.2"],["p","I am just setting out for Canada, and have only time to add my best Wishes of Health & Happiness to you & all yours. Permit me to say my Love to Mrs Bowdoin, & believe me ever, with sincere & great Esteem, Yours most affectionately B Franklin"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0453":{"title":"John Hancock to the Commanding Officer","author_label":"John Hancock","kind":"letter","date":"1776-04-03","date_label":"April 3, 1776","date_type":"written","recipient":"the Commanding Officer","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","scan_url":"https://archive.org/details/lettersofdelegat03smit/page/483","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 12A). Addressed: \"To the officer commanding the Continental Troops or the officer commanding where this Letter shall be produced.\"","authors":["john-hancock"],"paras":[["h","John Hancock to the Commanding Officer"],["p","Sir, Philadelphia April 3d. 1776."],["p","I have it in Command from Congress to direct, that upon the Application of Silas Deane Esqr you furnish him with a Guard of twenty Men under a proper Officer, to proceed with him to the Capes, from thence to be returned.1 You will therefore comply with this Requisition, immediately on his Application.2"],["p","I am, Sir, your most obed Sevt. J. H. Prst."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0462":{"title":"William Whipple to Josiah Bartlett","author_label":"William Whipple","kind":"letter","date":"1776-04-05","date_label":"April 5, 1776","date_type":"written","recipient":"Josiah Bartlett","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","scan_url":"https://archive.org/details/lettersofdelegat03smit/page/491","text_status":"unreviewed_ocr","editorial_source_note":"RC (NhD).","authors":["william-whipple"],"paras":[["h","William Whipple to Josiah Bartlett"],["p","My Dear Sir Philadelphia 5th Apl 1776"],["p","I hope this days post will advise me of your arrival 'tho I don't fully depend on it but shall the next.1 By the time this reaches you I hope You'll be preparing to set out. Have not yet got the New Hampshire matters pass'd in Congress. Have been ever since your departure on the Privateering business, & Regulation of Trade. The latter was finish'd Yesterday.2 Shall send them to you next post. I have given over all thots. of hearing from any body concerned in the Legislature of New Hampshire. I have been now near two months from thence & have not received a single line 'tho the Genl. Court has been seting almost a month. A schooner arrived this week from Guardalupe with 1200 cask Powder but they are small the whole containing no more than 7 or 8 Tons. The Wasp arrived the 3d inst. She parted from the fleet about 12 days ago off Bermudas where they had been cruising for the transports from the West Indies. They have on board 90 or 100 Cannon from 18 to 42 pounders, a large Quantity of shot & one Ton Powder taken from New Providence. Have also Brot off the Gov., Lieut Gov. & an officer belonging to Pensacola.3 The Capt of the Wasp says the fleet are bound to New England; suppose that if so you'll hear of them before I shall. A Piolet Boat which was taken sometime ago by the Roebuck (now Laying at the Cape) was a few days ago retaken near Lewistown with a Leiut. & 3 or 4 men belonging to the Roebuck. No late news from Canada."],["p","I am with great Esteem, Yours, Wm. Whipple"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0531":{"title":"John Hancock to Philip Schuyler","author_label":"John Hancock","kind":"letter","date":"1776-04-20","date_label":"April 20, 1776","date_type":"written","recipient":"Philip Schuyler","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","scan_url":"https://archive.org/details/lettersofdelegat03smit/page/562","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 12A).","authors":["john-hancock"],"paras":[["h","John Hancock to Philip Schuyler"],["p","Sir, Philada. April 20th. 1776."],["p","I do myself the Honour of transmitting herewith the Resolutions of Congress, under the Hand of the Secretary, as far as they relate to your own Conduct.1 You will perceive they have ordered four Battalions to Quebec; and by Letter from Genl. Washington, I understand, they are preparing to march with the greatest Expedition.2 I expect very soon to do myself the Pleasure of writing more fully. In the mean Time, I have the Honor to be with every Sentiment of Regard, yours &c."],["p","J. H. Prst."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0566":{"title":"John Adams to Abigail Adams","author_label":"John Adams","kind":"letter","date":"1776-04","date_label":"April 1776","date_type":"written","recipient":"Abigail Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi). Adams, Family Correspondence (Butterfield), 1:398-401.","authors":["john-adams"],"paras":[["h","John Adams to Abigail Adams"],["p","April 28. 1776"],["p","Yesterday, I received two Letters from you from the 7th. to the 14. of April. I believe I have received all your Letters, and I am not certain I wrote one from Framingham. The one I mean contains an Account of my dining with the Indians at Mr. Mifffins."],["p","It gives me Concern to think of the many Cares you must have upon your Mind. Am glad you have taken [Belcher] ' into Pay, and that Isaac is well before now I hope."],["p","Your Reputation, as a Farmer, or any Thing else you undertake I dare answer for. . . .2 Your Partners Character as a Statesman is much more problematical."],["p","As to my Return, I have not a Thought of it. Journeys of such a Length are tedious, and expensive both of Time and Money neither of which are my own. I hope to spend the next Christmas, where I did the last, and after that I hope to be relieved for by that Time I shall have taken a pretty good Trick att Helm whether the Vessell has been well steer'd or not. But if My Countrymen should insist upon my serving them another Year, they must let me bring my whole Family with me. Indeed I could keep House here, with my Partner, four children and two servants, as cheap as I maintain my self here with two"],["p","Horses and a servant at Lodgings."],["p","Instead of domestic Felicity, I am destined to public Contentions. Instead of rural Felicity, I must reconcile myself to the Smoke and Noise of a city. In the Place of private Peace, I must be distracted with the Vexation of developing the deep Intrigues of Politicians and must assist in conducting the arduous Operations of War. And think myself, well rewarded, if my private Pleasure and Interest are sacrificed as they ever have been and will be, to the Happiness of others."],["p","You tell me, our Jurors refuse to serve, because the Writs are issued in the Kings Name. I am very glad to hear, that they discover so much Sense and Spirit. I learn from another Letter that the General Court have left out of their Bills the Year of his Reign, and that they are making a Law, that the same Name shall be left out of all Writs, Commissions, and all Law Proscesses. This is good News too. The same will be the Case in all the Colonies, very soon."],["p","You ask me how I have done the Winter past. I have not enjoyed so good Health as last Fall. But I have done complaining of any Thing. Of ill Health I have no Right to complain because it is given me by Heaven. Of Meanness, of Envy, of Littleness, of — of — of — of — I have Reason and Right to complain, but I have too much Contempt, to use that Right."],["p","There is such a Mixture of Folly, Littleness, and Knavery in this World that, I am weary of it, and altho I behold it with unutterable Contempt and Indignation, yet the public Good requires that I should take no Notice of it, by Word or by Letter. And to this public Good I will conform."],["p","You will see an Account of the Fleet in some of the Papers I have sent you. Give you Joy of the Admirals Success. I have Vanity enough to take to myself, a share in the Merit of the American Navy. It was always a Measure that my Heart was much engaged in, and I pursued it, for a long Time, against the Wind and Tide. But at last obtained it."],["p","Is there no Way for two friendly Souls, to converse together, altho the Bodies are 400 Miles off? Yes by Letter. But I want a better Communication. I want to hear you think, or to see your Thoughts."],["p","The Conclusion of your Letter makes my Heart throb, more than a Cannonade would. You bid me burn your Letters. But I must forget you first."],["p","In yours of April 14. you say you miss our Friend in the Conveyance of your Letters. Dont hesitate to write by the Post. Seal well. Dont miss a single Post."],["p","You take it for granted that I have particular Intelligence of every Thing from others. But I have not. If any one wants a Vote for a Commission, he vouchsafes me a Letter, but tells me very little News. I have more particulars from you than any one else. Pray keep me constantly informed, what ships are in the Harbour and what Fortifications are going on."],["p","I am quite impatient to hear of more vigorous Measures for fortifying Boston Harbour. Not a Moment should be neglected. Every Man ought to go down as they did after the Battle of Lexington and work untill it is done. I would willingly pay half a Dozen Hands my self, and subsist them, rather than it should not be done immediately. It is of more importance than to raise Corn."],["p","You say inclosed is a Prologue and a Parody, but neither was inclosed. If you did not forget it, the letter has been opened and the Inclosures taken out."],["p","If the Small Pox spreads, run me in debt. I received a Post or two past a Letter from your Unkle at Salem,3 containing a most friendly and obliging Invitation to you and yours to go, and have the Distemper at his House if it should spread. He has one or two in family to have it."],["p","The Writer of Common Sense, and the Forrester, is the same Person. His Name is Payne, a Gentleman, about two Years ago from England, a Man who G[eneral] Lee says has Genius in his Eyes. The Writer of Cassandra is said to be Mr. James Cannon a Tutor, in the Philadelphia Colledge. Cato is reported here to be Dr. Smith — a Match for Brattle. The oration was an insolent Performance. ... A Motion was made to Thank the orator and ask a Copy — But opposed with great Spirit, and Vivacity from every Part of the Room, and at last withdrawn, lest it should be rejected as it certainly would have been with Indignation. The orator then printed it himself, after leaving out or altering some offensive Passages."],["p","This is one of the many irregular, and extravagant Characters of the Age. I never heard one single person speak well of any Thing about him but his Abilities, which are generally allowed to be good. The Appointment of him to make the oration, was a great oversight, and Mistake."],["p","The late Act of Parliament, has made so deep an Impression upon Peoples Minds throughout the Colonies, it is looked upon as the last Stretch of Oppression, that We are hastening rapidly to great Events. Governments will be up every where before Midsummer, and an End to Royal style, Titles and Authority. Such mighty Revolutions make a deep Impression on the Minds of Men and sett many violent Passions at Work. Hope, Fear, Joy, Sorrow, Love, Hatred, Malice, Envy, Revenge, Jealousy, Ambition, Avarice, Resentment, Gratitude, and every other Passion, Feeling, Sentiment, Principle and Imagination, were never in more lively Exercise than they are now, from Florida to Canada inclusively. May God in his Providence overrule the whole, for the good of Mankind. It requires more Serenity of Temper, a deeper Understanding and more Courage than fell to the Lott of Marlborough, to ride in this Whirlwind."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0202":{"title":"John Hancock to John Haslet","author_label":"John Hancock","kind":"letter","date":"1776-06-18","date_label":"June 18, 1776","date_type":"written","recipient":"John Haslet","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 12A). Addressed: \"To Colonell John Haslett or officer Com- manding the Battalion of Continental Troops in Delaware Government.\" ^See JCC, 5:452.","authors":["john-hancock"],"paras":[["h","John Hancock to John Haslet"],["p","Sir, Philada. 18 June 1776"],["p","The Two Companies which were Station'd at Cape May being order'd to Join their Regiment & proceed to Canada, and the Service requiring a constant force there, I have it in Charge from the Congress to Direct that you immediately order Two Companies of the Battalion of Continental Troops under your Command to proceed to Cape May, there to protect the Inhabitants 8c the Navigation, 8c to do Duty untill the further order of Congress.^ I am Sir, Your most obedt servt. J. H. Pt."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0255":{"title":"Benjamin Franklin to Benjamin Rush","author_label":"Benjamin Franklin","kind":"letter","date":"1776-06-26","date_label":"June 26, 1776","date_type":"written","recipient":"Benjamin Rush","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (DNA: PCC, item 82). Endorsed: \"Read 28th June before Bd War.\"","authors":["benjamin-franklin"],"paras":[["h","Benjamin Franklin to Benjamin Rush"],["p","Dear Doctor, Manor of Moreland, at Mr Duffield's, June 26. 76 I have just received the enclosed Letters by the Chevalier Kermorvan.^ By the Conversation I have had with him he appears to me skilful in his Profession. I hope in a few days to be strong enough to come to town & attend my Duty in Congress. In the mean time I could wish you to introduce the Gentleman where it may be proper and that you would translate the Passage relating to him that I have mark'd in M. Dubourg's Letter, and show it with what you have received to the same purpose from the same Friend. As I think Philada should be better fortify'd than it yet is, I hope some Use will be made of this Gentleman's Talents as an Engineer for that End. With great Esteem, I am, Dear Doctor, Your affectionate Friend &: most obedient Servant, B Franklin"],["p","[P.S.] Respects to Mrs. Rush."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0321":{"title":"John Adams to Joseph Reed","author_label":"John Adams","kind":"letter","date":"1776-07-07","date_label":"July 7, 1776","date_type":"written","recipient":"Joseph Reed","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"LB (MHi).","authors":["john-adams"],"paras":[["h","John Adams to Joseph Reed"],["p","Dear Sir. Philadelphia July 7 1776"],["p","Yesterday your Favour of the 4th Instant was handed me by the Post. Am much obliged to you for it, and will give all the attention I can to its Contents. Am not certain that I know the Gentleman who you recommend by the Name of Henshaw — but I believe I do.i There are several very worthy Men of that Name: which of them this is, I am not clear. The Difficulty is that we dont know what vacancies there are, to which Congress may with Propriety promote i such officers. If the general should recommend him to any advancement, he would readily have it. But if any Individual Member here should move for his Promotion without a Recommendation from Head Quarters, a suspicion would arise that he did not stand well there. Does he come to New York as Lt. Coll of a Regiment of Militia, or in what Capacity. Should be obliged to you for his Christain Name, and for a Hint of any Vacant Place to which he may be promoted. Nothing in my Power shall be wanting to serve a worthy Man and a usefull officer."],["p","Your description of the Force of the Enemy and your own weakness, is indeed allarming. The Importance of the Post you hold is very great; and it must be maintained and defended at all Events."],["p","Congress have already ordered three of the Battallions at Boston, to N. York, and tomorrow will order the other two.^ The two Pensilvania Battallions are ordered to N. York, and Measures have been taken to send all the Militia of Pensilvania, who can be armed to N. York and N. Jersey. Maryland is requested to send along their Proportion of the flying Camp. I hoped that the Militia from New England would have been with you before this Time, at least a considerable Part of them. You will Soon see Some of them I think. I have the Pleasure to agree perfectly with you, that now is the golden opportunity, for Sending into New York, Troops from every Quarter. The General may rely upon it, that no Tenderness for my own Province, nor any other Consideration shall induce me, to throw the least Impediment in the Way of any Measure that shall be proposed for that Purpose. I have even promoted the order"],["p","for calling away the five Battallions from Boston, altho I know not how the numerous Fortifications there are to be garrisoned, or even the Continental Stores to be defended."],["p","There really is a Strong, an earnest, and sincere desire, here, to do every Thing to forward the Militia from every Quarter. I wish their was as laudable a Spirit to give Bounties in Money, and Land, to Men, who would inlist during the War. But there is not. Congress offers Ten dollars Bounty to inlist for three years, when New Jersey, New York, Connecticut, Mass. Bay and New Hampshire are voting six. Eight, or Ten Pounds a Man to serve for Six Months. This Economy at the Spigot, and Profusion at the Bung will ruin us. Do for Gods Sake Coll Reed convince our Southern Brethren that the Common People and even Common Soldiers are rational Creatures, and that they can see, hear, and feel."],["p","My Heart bleeds in every Veign of it, for New York and the Army in it: But there is another Scene more affecting Still. The Army under Schuyler and Gates is an object miserable enough to affect less feeling Hearts than yours or mine. An Army, disgraced and dispirited, with repeated defeats; devoured with Vermin; without a Second Shirt, or pair of Hose, without Beds, or Blanketts, diseased with the Small Pox, and nothing to eat, but Salt Pork and flour — incapable of succour, by fresh Recruits, because such as have had the Small Pox are not to be found, and such as have not, would only bring fresh Wretchedness among them! What shall we do? Is it possible to cleanse that army from Infection? Without this, I fear, our Hopes in that Quarter are but delusions."],["p","After all I am not disconcerted by all these Confusions, because I have expected them these twelve Months, and because I have known our affairs in a situation much worse than they are even now. A fatal Delusion, from fond Hopes of Reconciliation, entertained, fostered and cherished, against the clearest Evidence, which is ever to be expected in such Cases, has held us back, from making such Preparations for our better Security as were in our Power. These Hopes are now extinguished, and I think that more Vigour will take Place and another winter will greatly befriend us. The golden opportunity however, is irretreivably lost. Canada is our Enemy, and We are now compleatly between two Fires. I expect an horrid Carnage upon our Frontiers, and a great Deal of Desolation upon the Sea Coast, but I hope still that We shall come out of the Furnace of Affliction, double refined. I am with great Respect,"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0346":{"title":"John Adams to Joseph Ward","author_label":"John Adams","kind":"letter","date":"1776-07-10","date_label":"July 10, 1776","date_type":"written","recipient":"Joseph Ward","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"LB (MHi).","authors":["john-adams"],"paras":[["h","John Adams to Joseph Ward"],["p","Sir Philadelphia July 10th. 1776"],["p","Yours of 1 July came duely to Hand.^ The Establishment of the War office as you observe has given me Work enough — more than I have a Relish for, and of a Kind not very suitable to my Taste, but must acquiesce. Shoud be greatly obliged to any officer of the Army"],["p","for a Hint of any Improvement in the Plan, and for any assistance in the Execution of it."],["p","The continual Reports of our Disasters in Canada have not intimidated the Congress: on the Contrary in the midst of them, more decisive steps have been taken than ever, as you must have seen, or will see before this reaches you. The Romans never would send or receive an Ambassador to treat of Peace when their affairs were in an Adverse situation. This generous Temper is imitated by the Americans."],["p","You hear there is not Candor and Harmony between Some of the Members of this Body. I wish you would mention the Names and Particulars of the Report — the Names I mean of the Members between [whom] it is reported there is not Candor and Harmony. The Report is groundless. There is as much Candor and Harmony between the Members as generally takes Place in assemblies, and much more than could naturally be expected in such an assembly as this. But there is a Prospect now of greater Harmony than ever. The principal object of dispute is now annihilated, and several Members are left out."],["p","In making a Return of your Division of the Army, pray give us the Name and Rank of every officer. We want to make an army List for Publication."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0377":{"title":"John Hancock to the New Jersey Convention","author_label":"John Hancock","kind":"letter","date":"1776-07-15","date_label":"July 15, 1776","date_type":"written","recipient":"the New Jersey Convention","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (NN). In the hand of Jacob Rush and signed by Hancock.","authors":["john-hancock"],"paras":[["h","John Hancock to the New Jersey Convention"],["p","Gentlemen, Philadelphia July 15th. 1776."],["p","The Article of Lead being so essentially necessary, and the Propriety of every Colony being furnished with it so evident, that the Council of Safety of this Colony recommended to the Inhabitants, to spare the Lead Weights from their Windows, and the Lead from their Houses; by which Means they have been furnished with a considerable Quantity, which has been run into Ball, and Part of which, the Council of Safety here have willingly spared, and is now on the Way to the Jerseys. But as under the present Exigency, that Quantity is far short of what is wanted for the Army in New Jersey, and every Method should be used to furnish it, I have it therefore in Charge from Congress, most earnestly to request you, to supply the Flying Camp and Militia, with all the Lead in your Possession, or that you can possibly procure.^"],["p","The Exigency of our Affairs will not admit the least Delay; and I am convinced, there is no Necessity to use Arguments to induce you to an instant Compliance with this Requisition."],["p","I am to inform you, that as you have not enclosed to Congress Copies of Genl. Washington's and Brigadr. Genl. Livingston's Letters, no Judgment can be formed by Congress concerning the Contents of them, and to request Copies of them to be sent hither.^"],["p","Measures are taking in Pennsylvania 8c Maryland, for forming the Flying Camp; and in the mean Time, the associated Militia are marching in great Numbers from Pennsylvania for the Defence of New Jersey. Ammunition has been, and will be supplied by this Congress, for the Defence of New Jersey. With Regard to the Pay of the Militia, I am to acquaint you, that Congress will observe the same Rule of Conduct towards New Jersey, as towards other Colonies."],["p","Four Tons of Powder are on the Way to New Jersey, and a large Number of Muskett Cartridges well balled, will this Day be sent forward."],["p","1 have the Honour to be. Gentlemen, your most obed. & very hble Ser., John Hancock Presidt"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0417":{"title":"Benjamin Franklin to Lord Howe","author_label":"Benjamin Franklin","kind":"letter","date":"1776-07-20","date_label":"July 20, 1776","date_type":"written","recipient":"Lord Howe","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"Tr (CSmH).","authors":["benjamin-franklin"],"paras":[["h","Benjamin Franklin to Lord Howe"],["p","My Lord, Philada. July 20th. 1776.i"],["p","I received safe the Letters your Lordship so kindly forwarded to me, and beg you to accept my Thanks."],["p","The Official Dispatches to which you refer me,^ contain nothing more than what we had seen in the Act of Parliament, viz. Offers of Pardon upon Submission; which I was sorry to find, as it must give your Lordship Pain to be sent so far on so hopeless a Business."],["p","Directing Pardons to be offered the Colonies, who are the very Parties injured, expresses indeed that Opinion of our Ignorance, Baseness, & Insensibility which your uninform'd and proud Nation has long been pleased to entertain of us; but it can have no other"],["p","Effect than that of increasing our Resentment. It is impossible we t should think of Submission to a Government, that has with the most wanton Barbarity and Cruelty, burnt our defenceless Towns in the midst of Winter, excited the Savages to massacre our Farmers, and our Slaves to murder their Masters, and is even now bringing foreign Mercenaries to deluge our Settlements with Blood. These atrocious Injuries have extinguished every remaining Spark of Affection for that Parent Country we once held so dear. But were it possible for us to forget and forgive them, it is not possible for you (I mean the British Nation) to forgive the People you have so heavily injured; you can never confide again in those as Fellow Subjects, 8c permit them to enjoy equal Freedom, to whom you know you have given such just Cause of lasting Enmity. And this must impel you, where we again under your Government, to endeavour the breaking our Spirit by the severest Tyranny, & obstructing by every means in your Power our growing Strength and Prosperity."],["p","But your Lordship mentions \"the Kings paternal Solicitude for promoting the Establishment of lasting Peace and Union with the Colonies.\" If by Peace is here meant, a Peace to be entered into between Britain and America as distinct States now at War, and his Majesty has given your Lordship Powers to treat with us of such a Peace, I may venture to say, tho' without Authority, that I think a Treaty for that purpose not yet quite impracticable, before w^e enter into Foreign Alliances. But I am persuaded you have no such Powers. Your Nation, tho' by punishing those American Governors who have created & fomented the Discord, rebuilding our burnt Towns, 8c repairing as far as possible the Mischiefs done us. She might yet recover a great Share of our Regard 8c the greatest part of our growing Commerce, with all the Advantage of that additional Strength to be derived from a Friendship with us; I know too well her abounding Pride and deficient Wisdom, to believe she will ever take such Salutary Measures. Her Fondness for Conquest as a Warlike Nation, her Lust of Dominion as an Ambitious one, and her Thirst for a gainful Monopoly as a Commercial one (none of them legitimate Causes of AVar) will all join to hide from her Eyes every View of her true Interests; and continually goad her on in these ruinous distant Expeditions, so destructive both of Lives and Treasure, that must prove as pernicious to her in the End as the Croisades formerly were to most of the Nations of Europe."],["p","I have not the Vanity, my Lord, to think of intimidating by thus predicting the Effects of this W^ar; for I know it will in England have the Fate of all my former Predictions, not to be believed till the Event shall verify it."],["p","Long did I endeavour with unfeigned and unwearied Zeal, to preserve from breaking, that fine & noble China Vase the British Empire: for I knew that being once broken, the separate Parts could"],["p","not retain even their Share of the Strength or Value that existed in the Whole, and that a perfect Re-Union of those Parts could scarce even be hoped for. Your Lordship may possibly remember the Tears of Joy that wet my Cheek, when, at your good Sister's in London, you once gave me Expectations that a Reconciliation might soon take place. I had the Misfortune to find those Expectations disappointed, 8c to be treated as the Cause of the Mischief I was labouring to prevent. My Consolation under that groundless and malevolent Treatment was, that I retained the Friendship of many Wise & Good Men in that Country, and among the rest some I have in the Regard of Lord Howe."],["p","The well founded Esteem, and permit me to say Affection, which I shall always have for your Lordship; makes it painful to me to see you engag'd in conducting a War, the great Ground of which, as | expressed in your Letter, is, \"the Necessity of preventing the American Trade from passing into foreign Channels.\" To me it seems that neither the obtaining or retaining of any Trade, how valuable soever, is an Object for which Men may justly Spill each others Blood, that the true and sure means of extending and securing ' Commerce is the goodness and cheapness of Commodities, & that the profits of no Trade can ever be equal to the Expence of compelling it, and of holding it, by Fleets and Armies. I consider this War against us therefore, as both unjust, and unwise; and I am persuaded cool dispassionate Posterity will condemn to Infamy those who advised it; and that even Success will not save from some degree of Dishonour, those who voluntarily engag'd to conduct it. I know your great Motive in coming hither was the Hope of being instrumental in a Reconciliation; and I believe when you find that impossible on any Terms given you to propose, you will relinquish so odious a Command, and return to a more honourable private Station."],["p","With the greatest and most sincere Respect, I have the honour to be; My Lord, Your Lordships most obedient humble Servt."],["p","B. Franklin"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0470":{"title":"John Hancock to Joseph Trumbull","author_label":"John Hancock","kind":"letter","date":"1776-07-27","date_label":"July 27, 1776","date_type":"written","recipient":"Joseph Trumbull","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 12A). Addressed: \"To Joseph Trumbull Eqr., Commissary Genl. New York.\"","authors":["john-hancock"],"paras":[["h","John Hancock to Joseph Trumbull"],["p","Sir Philadelphia 27 July 1776"],["p","Inclos'd you have a Resolution of Congress for the Supply of Provisions to the Frigates in the Eastern Departmt. out of the Stock of Provis[ion]s in that Quarter, & am to Request you will by the next Post issue your orders to your Deputy there to furnish such Quantities as shall be applied for by Mr Gushing & others who have the Care of the Ships.^"],["p","I have paid all your Bills that have been presented; Money will soon be sent to the paymaster. I wish you happy 8c am, Sir, Your very hum Servt,"],["p","J H Pt."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0481":{"title":"William Whipple to Joseph Whipple","author_label":"William Whipple","kind":"letter","date":"1776-07-29","date_label":"July 29, 1776","date_type":"written","recipient":"Joseph Whipple","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (MH).","authors":["william-whipple"],"paras":[["h","William Whipple to Joseph Whipple"],["p","My Dear Brother Philadelphia 29th July 1776"],["p","I receiv'd Yours of the 3d inst. Am really in pain for you; Tho I do not think there is any immediate danger it must give you great anxiety to see the country above you deserted by its inhabitants. I hope some Methods will be taken to quiet their minds. A few Companies properly station'd wod effectually secure you against any small parties of Indian that may be sent to our Frontiers &: there is no danger of any large bodies marching thro' that Country, as the army must have more important objects in view. I find the enemies army has increas'd amazingly in immagination. There certainly was no more than 4 thousand sail'd with Burgoyne 8c the same number to follow him, no advice of the latters having left England. We have no certain accots. of the strength of the Enemy in Canada but by the best information have not the least reason to think they have more than five thousand, or at the extent six. Our army has suffer'd extreamly by the Small pox. They are now at Tyconderoga 8c not more than 3000 strong more than half being sick. However they are now geting better, but the most we can expect this Campaign is to prevent the Enemy from geting possession of the Lakes which I hope we shall effect. I do most Heartily Lament the repeted 8c unaccountable Misfortunes, our army have meet with in Canada. I wish we may be able to get at the Bottom of them, a full investigation of the Causes will enable us in some measure to avoid the like in future.^ Our army at York are about 20,000 in high Spirits 8c the Flying Camp now Station'd in New Jersey consists of about 15,000 to be augmented 5,000. They (the Enemy) have not Yet begun their Operations, but I hope it won't be long before our army will give a good accot. of them. Its uncertain as to their numbers but its suppos'd not more than 8 or 10 thousand Land Forces but more expected. Genl Lee has been successful in repulsing the Enemy at South Carolina. In Verginia we have also succeeded against Lord Dunmore so far as to drive him from his entrenchments 8c oblige him to embark since which he has not been able to land. If we can keep him on board his vessels, disease will do his business as effectualy as the Sword. The People in this Country are in high Spirits. Gentn. of the first Fortunes take up their Musketts and March. No late accots from abroad; its probable our Letters have fallen into the hands of the Enemy. I agree with you that we are too late in all our movements. [How] ever these delays answer one good purpose, they certainly tend to produce unanimity, which is a desireable object in perfecting the Revolution. Congress were unanimous in the Declaration of independency which wod not have been three weeks sooner. Things go on much smoother now, then before that important Question was determin'd. I think to set out for home about"],["p","the 10th next month & wish may be able to carry some agreeable news with me. Perhaps I may be passing through York at the time of action. I shod like it exceedingly, Provided our arms are successfull but I must confess it wod be no very agreeable sight otherwise, not that I shod have the least objection to take my Chance. I do most heartily wish I had gone into the Army the last Campaign, in that case by this time I might have been a tolerable Soldier."],["p","Your apprehentions of Britains forming an alliance with France, I hope is without foundation, the latter knows her own interest too well, it wod be vastly more for her intrest to have a Commercial alliance with the American States which I flatter myself will take place e'er long. There is great reason to believe France will Commence Hostilities against Britain very soon perhaps before the commencement of another year. If so there will be no danger from that Quarter. In short I am under no apprehentions but America will support her Independency & an alliance with her will most certainly be a desirable object to every state in Europe who have any connections in America. If we have Wisdom 8c Vertue Enough to regulate our internal Police we may be a happy People. Its our own faults if we [are] not the happiest People on Earth. If I live to see that happy day I shall arrive to the Summit of all my wishes. By the length of this letter you wod not suppose me in a hurry but I am so much hurried that I cannot read what I have wrote, must therefore beg you'll correct any inaccuracies. Your very Affect. Bror,"],["p","W. Whipple"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0028":{"title":"Roger Sherman to Zebulon Butler","author_label":"Roger Sherman","kind":"letter","date":"1776-08-20","date_label":"August 20, 1776","date_type":"written","recipient":"Zebulon Butler","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/38","text_status":"unreviewed_ocr","editorial_source_note":"RC (CtY).","authors":["roger-sherman"],"paras":[["h","Roger Sherman to Zebulon Butler"],["p","Sir Philadelphia August 20th. 1776"],["p","I received by Mr Swift Your Letter of the 6th Instant with the representation made by the Authority, Selectmen 8c Committee of Inspection concerning their apprehentions of trouble from the Indians, upon which we applied to Congress to raise Some Companies upon the Continental Establishment.1 The application was referred to the Delegates of Connecticut and Pennsylvania who reported for raising three Companies in the Town of Westmoland to be under the Command of a Major, which now lies before Congress not acted upon, as also a report for raising a Battallion in Pennsylvania for Defence of the Frontiers of that State. Since these applications were made we have had favourable accounts from the Indians that they refused to comply with the Solicitations of Butler & others to take up arms against the colonies and are determined to remain Neuter. I dont know what will be finally done about raising Troops to defend the Frontiers, but if any are raised in Pennsylvania 'tis probable You will be allowed to raise three Companies. We shall pay proper attention to the affair and if anything is done about it Shall give You the earliest Notice.2 I hope your people will have restitution of their effects taken at the Warriours run, after the State of Pennsylvania hath Settled a regular Government."],["p","1 remain Your humble Servant, Roger"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0064":{"title":"Benjamin Franklin to Horatio Gates","author_label":"Benjamin Franklin","kind":"letter","date":"1776-08-28","date_label":"August 28, 1776","date_type":"written","recipient":"Horatio Gates","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/76","text_status":"unreviewed_ocr","editorial_source_note":"MS not found; reprinted from Benjamin Franklin, The Works of Benjamin Franklin . . . , ed. Jared Sparks, 10 vols. (Boston: Hilliard, Gray, and Co., 1836— 40), 8:185-86.","authors":["benjamin-franklin"],"paras":[["h","Benjamin Franklin to Horatio Gates"],["p","Dear Sir, Philadelphia, 28 August, 1776."],["p","The Congress being advised, that there was a probability that the Hessians might be induced to quit the British service by offers of land, came to two resolves for this purpose, which, being translated into German and printed, are sent to Staten Island to be distributed, if practicable, among those people.1 Some of them have tobacco marks on the back, that so tobacco being put up in them in small quantities, as the tobacconists use, and suffered to fall into the hands of these people, they might divide the papers as plunder, before their officers could come to the knowledge of the contents, and prevent their being read by the men. That was the first resolve. A second has since been made for the officers themselves. I am desired to send some of both sorts to you, that, if you find it practicable, you may convey them among the Germans that shall come against you."],["p","The Congress continue firmly united, and we begin to distress the enemy's trade very much; many valuable prizes being continually brought in. Arms and ammunition are also continually arriving, the French having resolved to permit the exportation to us, as they heartily wish us success; so that in another year we shall be well provided."],["p","As you may not have seen Dr. Price's excellent pamphlet, for writing which the city of London presented him a freedom in a gold box of fifty pounds' value, I send you one of them.2"],["p","My last advices from England say, that the ministry have done"],["p","their utmost in fitting out this armament; and that, if it fails, they cannot find means next year to go on with the war. While I am writing comes an account, that the armies were engaged on Long Island, the event unknown, which throws us into anxious suspense. God grant success. I am, &c. B. Franklin."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0124":{"title":"Caesar Rodney to John Haslet","author_label":"Caesar Rodney","kind":"letter","date":"1776-09-12","date_label":"September 12, 1776","date_type":"written","recipient":"John Haslet","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (DeHi).","authors":["caesar-rodney"],"paras":[["h","Caesar Rodney to John Haslet"],["p","Dear Sir Philadelphia Sepr. 12th 1776"],["p","I have been favoured with two Letters from you, one dated at New York, the Other at Kings Bridge,1 in both of which you desired I would Communicate to my friends your Scituation after the Engagement from whom Misses Haslet might hear it. Imagining it might be a Considerable time before the News woud Get to her in that way, and that in the meantime She would be verry uneasy, therefore I wrote a Letter to her immediately on the Rect of your first, in which I let her know the whole affair and Sent it by a safe hand."],["p","I am happy that I have it in my power to Congratulate you on the Bravery your Battalion has Shewn in the late Action, and the great Honor the Officers and Men have Acquired by it. They are much Spoken of here and I have been often Complimented in behalf of the Government on their account. They deserve much of their Country, and (as an Individual) have my most hearty Thanks. I am Extreemly Sorry for poor Stuart and the other brave Lads that fell, tho in the Bed of Honor. Must Confess I don't like your present Scituation, yet hope the best. The Justice of our Cause, and the bravery of our Troops may do Wonders."],["p","In your last Letter you Seem to Show some Uneasiness least there Should be Some Change in the delegates. I believe you may be Easy on that head. In the first place I imagine They would not venture to Risque the making Such an Uproar in the Government as the turning me out probably wou'd make, and in the Next the undesigning Patriotick part are determined to protest against their doing any thing but that of framing a plan of Government. In Mr. Reads last letter to me is the following paragraff. \"Our business has been delayed in Convention by the death of Mrs. Thompson, the Sister of Mr. McKean, who was buried this day. Mr. McKean's Eldest son lies dangerously ill at Mr. Thompson's house, and I know not when he can attend. A Committee of Ten is Employed in the Drafting a Declaration of Rights, the rest of the Members from Kent & Sussex are getting impatient, Doctr. Ridgely is Returned Home Sick. Such is the Scituation of Matters Here.\" When Mr. Read went to Newcastle he prevailed on me to stay in Con-"],["p","September 12, 177C> 151"],["p","»ress, and that lie would get the Convention to give a power to one Member to Act so that our Government might be Represented by me alone till the Convention Should Rise. I mentioned this to Mr. MtKean who directly declared they should make no appointment of Uelegages, nor even alter the powers Given them, least they (meaning the Convention) should plead that as a president for going into some other appointments, which they were not authorised to do by their Choice. Therefore Upon the Whole I don't imagine they will attempt any Change. But sir whether they do or not, I do not purpose Continuing here longer than till the other Gentlemen Return; I have made a verry Great Sacrifice of my property to the Cause, Government never paid me above half what I have necessarily Expended even when my friends were at the Helm. What may I Expect from these? They would see me Serve without a Shilling. You know they wou'd, because you know they like not either me or the Cause.2"],["p","General Dagworthy, Mr. Clowes and Mr. Peery were here, and say the Tory plan for leaving me out of the Convention was, first to put me at the head of their Ticket to shew their approbation of me, after which they put another person in my Stead, and assigned as a Reason for it, that it was now a Critical time. That it was absolutely necessary We should keep up our Representation in the Congress. That they wished I might not be laid under the necessity of leaving the Congress at a time so Interesting which I must Do if Chose in Convention &c. These Gentlemen then said that the Inhabitants of Newcastle County had not Considered to the Matter in that light for they had chose both their delegates. In Answer to this, it was said they, the people of Newcastle, had done verry wrong &;c. By Such little Cunning are the people to be Cajoled. I saw a Man from Mispillion who left there a day or two before my letter Could have reached it, who told me that yours and Captain Adams's families were well, but they were in Much distress for the Delawares who (from all accots. they had Received) were at least two thirds Cut off, that almost all the officers were killed particularly you. He told me the people were Generally distressed haveing most of them some friend or Relation in the Battalion. My letter I am Sure has set that Matter Right."],["p","I wrote above a week ago to Mr. Montgomery the Chaplain, not knowing then whether you were among the Dead or living. Should be Glad to know whether the letter got Safe [to] hand.3 Be pleased to Enquire of him and let me know in your next which I hope will be soon. Make my compliments to Doctr. Tilton, and tell him I forwarded his Brothers letter. That you may have a happy deliverance, and your Battalion be Crowned (if possible) with still more Honor in every Combat is the Sincere wish of Sir, Yr. Real Friend & Humble Servt. Caesar Rodney"],["p","P.S. I Remembered you as desired to Messers Killen & Rodney"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0173":{"title":"William Williams to Jonathan Trumbull, Sr.","author_label":"William Williams","kind":"letter","date":"1776-09-20","date_label":"September 20, 1776","date_type":"written","recipient":"Jonathan Trumbull, Sr.","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (Ct).","authors":["william-williams"],"paras":[["p","William Williams to Jonathan Trumbull, Sr."],["p","Hond & Dear Sir Philadel. 20th Sepr. 1776"],["p","It will undoubtedly be needless for me to give You any account of the Evacuation of N York by our army on Sab. Day the 15th, of most of our heavy Cannon falling into the hands of our Enemies 8cc, as it will be communicated to you by my Bror. Comissa., many ways ee'r this can reach your Hand. This Event unhappy & distressing as it is has been foreseen & known ever since the quitting of Long Island, & had been determined by the Genl. & his Council; Congress had been made fully accquainted with 8c assented to it as absolutely necessary, 8c directed that it shod not be destroyed by Us on leaving it. These Events however, 8c signal advantage gained by our oppressors, & the Distress to which our Army & Country are & must be subjected in Consequence of them, are loud speaking Testimonies of the Displeasure 8c Anger of almighty God against a sinful People, louder than sevenfold Thunder. Is it possible that the most obdurate 8c stupid of the Children of America shod not hear 8c tremble? God has surely a Controversie with this People, 8c He is most certainly able to manage it 8c He will accomplish his Designs, 8c bring Us to Repentance 8c Reformation, or destroy Us. We must bend or break. The ways of his Providence are dark 8c deep but they are holy, wise, 8c just 8c altogether right, tho our feeble Understandings comprehend them not, 8c tho his Chastisements are severe 8c dreadful, They are dictated by unbounded Wisdom 8c Love. They have a meaning of awful 8c kind Import. Turn unto me for why will ye die O Sons of America. We have thought God was for Us 8c had given many 8c signal Instances of His Power 8c Mercy in our Favor, 8c had greatly frowned upon 8c disappointed our Enemies 8c verily it has been so, but have we repented 8c given Him the Glory? Verily no. His Hand seems to be turned 8c stretched out against Us, 8c strong is his Hand 8c high is his right Hand. He"],["p","can 8c will accomplish all his Pleasure. It is God who has blunted the Weapons of our warfare, that has turned the Counsels of wise Men into Foolishness, that has thus far blasted 8c disappointed our Hopes, 8c made Us flee before our Enemies, & given them Possession of our Strong Holds. Trouble does not spring out of the dust nor rise out of the Ground. I have always thot this was a just & righteous Cause in which We are engaged. I remain unshaken in that firm persuasion, & that God wod sooner or later vindicate & support it, I believe so still, but I believe this People must first be brot to know & Acknowledge the righteousness of his Judgment, & their own exceeding Sinfulness 8c Guilt, & be deeply humbled under his mighty hand, & look & cry to 8c trust in Him for all their Help & Salvation but in the Use 8c Exertion of all the Strength He has given Us. Surely We have seen enough to convince Us of all this, 2c then why are We not convinced, why is not every Soul humbled under the mighty hand of God, repenting 8c mourning For its Sins 8c putting away the evil of his Doings, 8c looking to Him that smites Us by humble, earnest 8c fervent Prayer 8c Supplication day 8c Night. Why are not the dear Children of God (surely there are many, tho the Scorn 8c Insult of our Enemies) beseiging the Throne of Grace, sighing 8c crying for their own Sins 8c back slidings 8c for all the abominations that are done in the Land, 8c saying spare, spare thy People O Lord 8c give not thine Heritage to Reproach. Let not the Vine which thy right Hand has planted here be rooted up 8c destroyed, let not thy Churches be wasted 8c devoured, let not virtue 8c the remains of Religion be torn down 8c trampled in the Dust, Let not thy Name be blasphemed, nor our insulting wicked Foes say where is your God, nor the profane world that there is no God that rules the world 8c regardeth the Right, that vindicateth the just 8c the righteous Cause. I know that God can vindicate his own Name 8c Honor without our Help, 8c out of the Stones raise up Children to Abraham, 8c it is amazing Folly 8c Madness to cry the Temple, the Temple of the Lord, 8c trust in that while We remain an incorrigible People. But Such Things are what God wod have Us learn 8c practice while his Judgments are abroad in the Land, 8c with such like Arguments fill our Mouths, 8c pour out our Souls before Him. Are any? Are not all? in N England especially, who have any Interest in Heaven, crying, beging 8c intreating for the out pouring of blessed Spirit of God upon the Land, tis a most grievous 8c distressing Consideration that God is pleased so to withhold the blessed Influences 8c operations thereof, without which We shall remain stupid forever. Therefore with redoubled fervency of ardent Prayer 8c Supplication, shod every Soul that has one Sparck of Heavenly Fire kindle it to a fervent Heat 8c expanded Blaze."],["p","O New England, O my dear native Land, how does my Soul Love thee. Be Instructed therefore lest Gods Soul depart from thee,"],["p","lest thou be like Corazin & Bethsaida in Condemnation as thou hast been in Privileges, lest He make thee as Admah & set thee as Zeboim. Are the Ministers of the Gospel alive 8c awake 2c lifting up their Voices like a trumpet & sounding the Alarm of the Almightys Anger 2c Wrath ready to burst on the defenseless Heads of a guilty People? Are they warning the wicked of their infinite Danger, animating 8c arousing them to Consideration? Are they with ardent Zeal & Fervour animating 2c enlivening the languid Graces of the Godly, exciting 2c leading them to fervent Prayer, sighing 2c crying for their own Declensions 8c Luke warmness in Religion 8c for the Sins 8c Iniquities of the Land, praying, beging 8c intreating with unceasing 2c as it were resistless Importunity for the copious Effusions of the Blessed Spirit upon all orders 8c degrees of People 8c refusing to let God go, without an Answer of Peace, 2c in the midst of Wrath to remember Mercy, 8c not give up this his Heritage to Reproach nor blast the blooming Hopes 8c Prospects of this infant Country, the Asylum of Liberty 8c Relegion?"],["p","Strange that Mankind shod need such alarming Providences to produce such an Effect. It is no more than to act like reasonable Creatures, to possess a Spirit 8c Temper that will add a thousand fold sweetness 9c pleasure to all the Enjoyments of this World, to exchange the Slavery of the Devil, that accursed Enemy of our Souls, for the Service of God 2c the Liberty of his Children, to do justly, to love Mercy 8c walk humbly with our God, to answer the sole end of our Creation, to secure a Peace here infinitely better than the World can give, 8c an Eternity of Peace 2c Happiness in the World to come. But still more strange if possible, 2c astonishing is it that They Shod disregard the Voice of the most high, remain thoughtless 2c stupid under the dreadful Tokens of his Anger 8c the awful Judgments of his Hand, by Sickness 2c by the Sword of our unnatural 8c enraged Enemies threatening to depopulate the Land 2c drench the Plains with the Blood of its Inhabitants, leaving the weeping Widows, helpless Orphans 8c the all that survive the shocking Carnage 8c subsequent Masacre to drag out their Lives in Want, Wretchedness 8c miserable Bondage 8c all this aggravated with the certain Prospect of leaving this dreadful Curse intailed on all Posterity."],["p","A thorough Repentance 8c Reformation, without all peradventure will appease the Anger of a holy 8c just God, avert these amazing Calamities, secure Liberty 8c Happiness to this 2c all succeeding Ages 8c eternal Felicity 8c Glory to all the Subjects of it. If such Considerations 2c Motives wont awaken a [11] to serious Thoughfulness 8c Attention, I know n[ot] what will, but the Voice of the Arch Angel 8c the Trump[et] of God."],["p","I am hond 2c dear Sir most affectionately your dutiful Son 2c Servant. Wm Williams"],["p","P.S. You will not think proper to communicate this Letter to the Assembly. I am anxious beyond the power of Language to describe, of contributing something to the Good & Salvation, temporal & eternal, of my Countrymen. (Hope I have not been totally useless here.) If you shod think this may have any tendency, to awake our sleepy People & be of no disadvantage, I am willing it shod be printed &, for no other possible reason, leaving out such of the begining as may be a clue to guess the author or where He is, 8c with the description or Signature of a Letter from a Gent of Connecticut, now in a different Colony.1"],["p","May God in great Mercy preserve your Health, & long continue your valuable & important Life. With kindest Remembrance to my dear Wife & Friends. W W"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0196":{"title":"John Adams to James Warren","author_label":"John Adams","kind":"letter","date":"1776-09-25","date_label":"September 25, 1776","date_type":"written","recipient":"James Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/237","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi).","authors":["john-adams"],"paras":[["h","John Adams to James Warren"],["p","Dr sir Septr. 25. 1776 J"],["p","This Express carries a new Plan of an Army. I hope the Gen. Ct. without one Moments delay will Send Commissions to whole Corps of their officers, either by Expresses or Committees to New York and Ticonderoga that as many Men may be inlisted without delay as possible. It may be best to send a Committee with full Powers to each Place. There is no Time to be lost. I inclose you a Sett of Articles as lately amended.2 Discipline I hope will be introduced at last. I am, Jonn Adams"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0249":{"title":"William Ellery to Nicholas Cooke","author_label":"William Ellery","kind":"letter","date":"1776-10-05","date_label":"October 5, 1776","date_type":"written","recipient":"Nicholas Cooke","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/307","text_status":"unreviewed_ocr","editorial_source_note":"RC (R-Ar).","authors":["william-ellery"],"paras":[["h","William Ellery to Nicholas Cooke"],["p","Sir, Philadelphia Octr. 5th. 1776."],["p","I received a Letter from Mr Ward of the 17th of September, which informed Me that your Honour &: your Lady were inoculated and were expected to break out in a Day or Two. I most sincerely hope that when this reaches you, you will be intirely recovered from the Small Pox."],["p","Since my last, Congress have entered into sundry Resolves which respect the several United States, and which will be communicated to you so soon as the Multiplicity of Business in which the President is engaged will admit of it; But as they may not reach our State so soon as the Post, it may not be improper to give you the Heads of them."],["p","It is recommended to the Legislatures of the United States to appoint Gentn. in their respective States skillful in Physick & Surgery to examine those who offers to serve as Surgeons or Surgeon's Mates in the Army and Navy, and that no Surgeons or Mates shall hereafter receive a Commission or Warrant to act as such in the Army or Navy who shall not produce a Certificate from some or one of the Examiners so to be appointed to prove that he is qualified to execute the office.1"],["p","A Loan Office is to be established in each of the United States, and"],["p","a Comme. to superintend such officers to be appointed by the States respectively. The Sum proposed to be hired is Five Millions of Continental Dollars and the Commissioners are to receive One Eighth per Cent in Lieu of all Demands for their Services. Certificates with the Resolve will be transmitted to our State when the Certificates are printed.2"],["p","It is Resolved that the President be desired to write Letters to the Conventions k Assemblies of the respective States, requesting that Measures be taken to cause as speedily as possible a full Representation of the States in Congress.3 I would beg Leave here just to mention in Addition to what I have said in a former Letter that there is not a State that sends less than Three Delegates to represent it in Congress."],["p","Congress too have recommended it to the several Legislatures in the United States to confine the Price of such Articles as the Quarter Master General may want to a reasonable Sum by an Act of the Legislature.4"],["p","The Committee who were appointed to inspect the State of the Army &c at Haerlem have returned and represented Things in a more favorable Light than We had used to view them. Methods are taking that the Army shall be better disciplined and provided in every Respect than it hath been. Although We have some good officers in some of the principal Departments; yet in others there is great Want of Skill and Abilities. The Quarter Master General Moylan was perswaded by the Committee to resign and Brigadier Genl. Mifflin to accept that office with the Rank and Pay of Brigadier General."],["p","This Appointment will give great Satisfaction to the Army; for Gen. Mifflin is not only well acquainted with the Business of the Office, but he hath Spirit and Activity to execute it in a proper Manner."],["p","The Officers of the Army in general are not equal to their Appointments and from hence it is that our Soldiery is disorderly and undisciplined. It is therefore recommended by Congress to the several States in officering the new Army, that they pay a particular Regard to Merit and Qualifications in their Appointments.5 It is agreed on all Hands that our Men will make good Soldiers when they have good Officers. I hope the Genl. Assembly will be as ready and active in raising the new Levies as they were in dispatching the Continental Battalion to New York. The Time for raising the new Levies is short, and it is of the last Importance that they should be ready to supply the Places of the Troops that may quit the Service when the Time of their Inlistments shall expire. The Enemy if they should have such an Opportunity as they had last Fall will without Doubt improve it."],["p","By Letters from G. Washington reed, yesterday Things at our Camp in Harlem remained as they were; and by some inclosed"],["p","Letters from Henry B. Livingston Captn. of a Company which have been employed on Long Island to bring off Inhabitants and Stock it appeared that he had brot off a Number of Families and a considerable Quantity of Stock and Grain. That the Enemy were collecting all the Stock and Grain they could and levying Companies there. In which Business Brigr. Genl. Oliver De Lancey is very active. Capt. Livingston having heard that One Richard Miller a Tory of Distinction had raised a Company of Men and that he was about to join them, posted his Men so advantageously for intercepting him that they came across him, & ordered him to stop, which he refusing and attempting to escape they shot him dead on the Spot.6"],["p","Letters were also received the same day from the Northern Army from Genls. Schuyler &: Gates & Arnold, some of them inclosing Accounts from Deserters respecting the Enemy's Army $c Navy.7 By One of the Accounts it appears that their Army was sickly; That they had plundered and otherwise abused the Canadians so that but few had joined them, and that fifty of the British Troops had agreed to desert, but were unluckily discovered. From what I am able to collect the Enemy's Naval Force is equal if not superior to ours; but there Land Force not superior if equal. Genl. Arnold was at the Island Le Motte when he wrote, and intended to place his Fleet advantageously for Attack 8c Retreat. Our Army was still sickly, and in Want of cloathing, especially of Shoes & Stockings."],["p","Congress have sent a Committee to Ticonderoga to inspect the State of the Army &c &c. When they return I will communicate such Part of their Report as I may be at Liberty to disclose."],["p","We have nothing New from the Southward. The Papers have already informed that We have burned a Number of the Lower- Towns of the Indians & an Expedition is formed for destroying then- Upper Towns. General Lee is not arrived. Genl. Green to the Joy of the Army hath recovered his Health. I have nothing more to add at present but that I am with the sincerest Regard your Honor's & the State's Friends and humble Servant, William Ellery"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0430":{"title":"William Hooper to the North Carolina Convention","author_label":"William Hooper","kind":"letter","date":"1776-11-15","date_label":"November 15, 1776","date_type":"written","recipient":"the North Carolina Convention","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (Nc-Ar).","authors":["william-hooper"],"paras":[["h","William Hooper to the North Carolina Convention"],["p","Sir Philadelphia, Nov 15, 1776."],["p","I omitted to mention in the letter which I have closed and"],["p","accompanies this, that the Enemy are scant of provisions k may have"],["p","some dependance upon the Cattle on the Sea Coast of the southern States for a supply. In that Case you will perhaps think it prudent to drive back the Stock from the low Country as soon as possible. Horses are much an Object with them for their Waggons — & therefore must be kept out of their way. It may be worth while to spend a thought upon a mode of securing our Negroes, and preventing any Communication between the Enemy & any who may be disaffected amongst you whether of the late Insurgents or others. I am, Gentlemen, With great Respect, Your Obed Serv,"],["p","Will Hooper"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0044":{"title":"Samuel Chase to the Maryland Council of Safety","author_label":"Samuel Chase","kind":"letter","date":"1777-01-08","date_label":"January 8, 1777","date_type":"written","recipient":"the Maryland Council of Safety","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/50","text_status":"unreviewed_ocr","editorial_source_note":"RC (MdAA).","authors":["samuel-chase"],"paras":[["h","Samuel Chase to the Maryland Council of Safety"],["p","Gentlemen Wednesday Morning [January 8, 1777J"],["p","We remain in the most anxious Suspence. Some important Event has taken place, but We are unable to inform the particulars."],["p","The enclosed is a Copy of a Letter from the Committee of Congress to Mr. Hancock.1 I have no Leave to make it public ; I send it to give You all the Intelligence in my power. It may be shewn but not printed."],["p","Our State is still unrepresented, & every day matters of the greatest Importance are debated and determined in Congress."],["p","I am afraid our Recruiting Service will be greatly injured unless Satisfaction be given to the officers. I beleive many Reasons will occur to convene the General Assembly as soon as possible.- Many Reports from Somerset County cause Uneasiness here, & if true, demand speedy and vigorous Measures."],["p","I have just heard of this Conveyance, & drop this Line from Grants Tavern."],["p","I am, Gentn, with Respect, Yr. obedt. Servt. Saml. Chase"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0071":{"title":"Robert Morris to John Jay","author_label":"Robert Morris","kind":"letter","date":"1777-01-12","date_label":"January 12, 1777","date_type":"written","recipient":"John Jay","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/87","text_status":"unreviewed_ocr","editorial_source_note":"RC (NNC). 1 Not found.","authors":["robert-morris"],"paras":[["h","Robert Morris to John Jay"],["p","Dear Sir Philada. Jany 1 2th 1 7 7 7"],["p","I have been possessed of your obliging favr. of the 2d Ulto a considerable time,1 but being too much pressed with public & private business to permit my being a regular correspondent it is needless to apologize. You undoubtedly must have been acquainted with the Rapid progress made by our Enemies through the Jerseys and the danger to which this City has been exposed for some Weeks past and you will have heard of the removal of Congress to Baltimore in the midst of pannic. This step has been highly censured by many of their Friends and undoubtedly lost them the confidence of some valuable Men."],["p","I confess for my own part I am not amongst the number of those that Censure them for this hasty measure, for when it is considered that the Enemys Troops were within a very few miles of us & no apparent Force sufficient to oppose their progress, it surely was time for a public body on which the support of the American cause so much depended, to provide for their safety. Meer personal safety I suppose wou'd not have induced many of them to fly, but their Security as a body was the object. Had any number of them fallen into the Enemies hands so as to break up the Congress America might have been Ruined before another Choice of Delegates cou'd be had & in such an event they wou'd have been deemed criminal & rash to the last degree. Most of them dislike their present Station & complain horridly, particularly those you esteem, but it seems some others who generally carry their points, like their quarters & are for staying. I suppose it answers some of their purposes and I have but one objection in the world. They have appointed Mr Walton of Georgia, Mr Clymer & myself a Committee to transact all Continental business that may be necessary & proper in this place. The business of this Committee engrosses my whole time & increases daily, so that I am now the veriest Slave you ever saw and wish them back to be relieved."],["p","I wish to Heaven they had removed from hence last winter. If they had, Pensylvania wou'd long since have had a wholesome constitution, its Strength might have been drawn into proper exertion & her Capitafwou'd never have been made to tremble. What has happened is the fruits of that winters Cabals. Our Constitution is disliked, the People divided, unhappy, and consequently weak, the power if any there be, is placed in improper hands and in short the people seem to loose one day, the Confidence they placed in leaders of the day before."],["p","Where it will end God only knows. Dickinson & A. Allen have given mortal stabs to their own Characters & pity it is the wounds shou'd penetrate any further, but they were men of property, Men of fair private Characters & what they have done, seems to pierce through their sides into the Vitals of those who have similar pretentions to Fortune & good Character. The defection of these men is supposed to originate in a desire"],["p","to preserve their Estates & consequently glances a suspicion on all that have Estates to loose. I pity them both exceedingly. Dickensons Nerves gave way & his fears dictated a letter to his Brother advising him not to receive Continental money. His Judgment & his virtue shou'd have prevented this act of Folly, I call it such because I believe his Heart to be good & regret much that his exalted Character shou'd be degraded, by what cou'd hardly be called a crime at the time he did it, but he thought the Game was up. A Allen deserves a better fate than he will meet with. Aimiable in private character and deserving of the Felicity he has heretofore enjoyed he has rashly sacrificed it by a hasty resolution. He has long thought it impossible for us to withstand the power of Great Britain & he complained of that Conduct amongst ourselves which has been loudly censured by America's warmest advocates & frequently exposed by the keen sentences of Mr. Jay. However nothing can justify the step he has taken & it seems wrong to paliate it. I will therefore only say I am most sincerely sorry for him. I removed my Family & some of my effects in the heat of our Fright but determined to stay by the City to the last moment. Very happy have I been since, in this determination, as it is fallen in way to be very usefull on many occasions, both to this State & to the Continent, and in every instance I have exerted myself to the utmost. Congress are Sensible of it and have approved all my doings, altho I acted for a considerable time without their Authority. I join in all your Sentiments respecting our good Friend Duane and if I had not been well convinced how III used he was by that cursed piece of Slander I shou'd not have troubled him with it, nor shou'd I have sent it when I did, but having heard he was coming to Congress, I thought it my duty to prepare him. I have a letter from him on the subject and think he treats it very properly by despising the report & its author or authors. I wish to heaven the affairs of your state wou'd permit both your attendance at Congress, believe me you & others are wanted there. There is a leader there that you do not like and as I understand they have the rule of the roost totally since their removal to the Southward. Pray shew this to Mr Duane & tell him the next bit of leisure I get shall be devoted to answer his two letters."],["p","I do not pretend to give you any acct of military operations as I suppose you get them from day to day. What a glorious change in our prospects. Pray heaven Continue our Success and grant me an opportunity of Congratulating you on regaining the City of New York. I have not heard from Mr. Deane for sometime past & fear he will complain for want of remittances & Intelligence. These Damnd Men of War plague us exceedingly & have taken many of our Vessells, but we must persevere untill we gain success. I am Dear Sir, Your affectionate Friend & Servt,"],["p","Robt Morris"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0100":{"title":"John Hancock to the Executive Committee","author_label":"John Hancock","kind":"letter","date":"1777-01-18","date_label":"January 18, 1777","date_type":"written","recipient":"the Executive Committee","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/120","text_status":"unreviewed_ocr","editorial_source_note":"RC (DNA: PCC, item 58). In the hand of Jacob Rush and signed by Hancock. Addressed : \"Robert Morris Esqr & Commee.\"","authors":["john-hancock"],"paras":[["h","John Hancock to the Executive Committee"],["p","Sir, Baltimore Jany 18. 1777."],["p","I do myself the Honour to transmit you the enclosed Resolves, by which you will perceive the Steps taken by Congress since my last.1"],["p","The Affairs of our Country were perhaps never so critical as they seemed to be by your last Accounts which were dated the 11th inst — and yet, some how or other it has happened we have not heard from Philada. since that Time, nor from the General for two or three days before. This Interval, you may suppose, we pass in the greatest Anxiety & Suspense, and wish to be relieved from it in any Manner, rather than be tormented with Doubt, and Uncertainty. I hope therefore, for the future, you will not let us be so long without hearing from you, but will send us an Express, if it is only to inform us, that our Affairs have undergone no Alteration since your last."],["p","I am, with great Respect, Sir, your most obed Servt."],["p","John Hancock Presidt."],["p","19th. Since the foregoing, I have had the Pleasure of receiving your Favour of the 16th and am to request you will pay particular Attention to the Resolves relative to the Horses in the public Stables, and give the Quarter Master Genl. all the Information in your Power on this Subject.2"],["p","Pray continue to send us Intelligence, if not every day, at least, every other day; and do not let any Idea of the Expence, come in Competition with the Importance of our receiving instant Dispatches."],["p","I am yours &c, John Hancock Pt."],["p","[P.S.] Please to forward the Letter to Genl. Washington, sent herewith."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0157":{"title":"John Hancock to Jonathan Trumbull, -Sr.","author_label":"John Hancock","kind":"letter","date":"1777-01-30","date_label":"January 30, 1777","date_type":"written","recipient":"Jonathan Trumbull, -Sr.","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/164","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 12A).","authors":["john-hancock"],"paras":[["p","John Hancock to Jonathan Trumbull, -Sr."],["p","Sir, Baltimore, Jany. 30th. 1777"],["p","I was duely honoured with your Favour of the 12th inst, and in Consequence of the same being laid before Congress, am now to inform you, that the Transactions of the Committee therein referred to will be taken up and considered by Congress tomorrow. The Result of this important Business, as well as every other Determination of Congress, in which the State of Connecticut is either partially or wholly interested, you may depend on my transmitting with the utmost Dispatch.1 Wishing you very sincerely the Compliments of the Season, and every other Happiness, I am, with great Respect, Sir, your most obed. & very hble Serv."],["p","J H Presidt."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0275":{"title":"William Hooper to Joseph Hewes","author_label":"William Hooper","kind":"letter","date":"1777-02-15","date_label":"February 15, 1777","date_type":"written","recipient":"Joseph Hewes","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/289","text_status":"unreviewed_ocr","editorial_source_note":"RC (MdBJ-G).","authors":["william-hooper"],"paras":[["h","William Hooper to Joseph Hewes"],["p","Dear Joseph Halifax Monday February 15. 1977"],["p","Here I arrived late yesterday after a most fatiguing Journey all the way on Horseback from Baltimore hither. An unremitting attendance upon congress all day and upon committees on Evenings during the solitary representation of North Carolina by degrees impaired my accustomed stock of health and at length brought on a fever which for several days baffled the Skill of Doctor Wirzinthale and the power of medicine. It had a crisis which proved fortunate, I took the advantage of an Intermission and resumed my seat in Congress & Relapse was the Consequence & I had very nearly measured my length under Ground in that worst of all terrestrial places, a situation bad as it is yet preferable to being above it long in that wretched place. I have not yet recovered, I was broiling in a fever all last night & I can scarce muster strength to get on horseback tho I propose to go on this day."],["p","Burke came to my relief on Saturday the first day of February and your express delivered me your packet about two hours before Burke appeared. Your Express with the fatigue of his Journey and from other causes found himself much indisposed and from this and his apprehension of the Small pox was averse to proceeding to Philadelphia. Fortunately, the next morning two congress expresses set off, one for Philadelphia to return the next Saturday — the other for Boston to return as soon as might be. Your letters for Philad I gave to the former & wrote R Morris who was there & your Brother to dispatch answers by the return Express under Cover to Mr Hancock for you. Your Letter to the Governour of Mass'tts went by the Boston express. I gave directions to Mushraw to call upon Mr Hancock on Saturday for any letters which might come to him for you & if any were not arrived to wait till they did & then proceed immediately to Edenton. I apprized Mr Hancock of this measure so that no mistake can occur in the Conduct of it. Your letter to the President &c were layed before Congress, a Committee at my request appointed, & by Mushraw as soon afterwards in a letter by Burke you will know the Result.1"],["p","Freeman Payne whom you mention as the owner of the Privateer is a fellow who was employed in Rh. Island by the State of South Carolina to recruit Sailors. They intrusted him with a Sum of money which he applied to his own uses in the purchase of a privateer. He has preyed upon all the World & is said now to be worth 30,000£ the fruits of his pious labours. I prevailed upon the N Eng. delegates to write long ago to Boston; as yet they can hear nothing of the arrival of the Privateer or his plunder."],["p","The North Carolina Regiments as well the 6 in So Carolina as the three new ones here are ordered to join G Washn. as soon as it can be effected.2 He is distressed for want of men, has not I fear 7000 & many of those are militia when the Enemy are 10,000 Strong & are prevented attacking him only from want of Cannon."],["p","A Col Buckners Cowardice prevented our getting possession of 3 Rgts of the Enemy & perhaps 100 Waggons loaded with provisions. His Lieut Col Josiah Parker fought like a Hero, killed the Col Command[an]t of the Enemy & the second Col & would have totally routed them if Buckner had come up to his assistance with 400 Men which he had with him while Parker maintained the unequal conflict with 200 agt the whole force of the Enemy. Buckner ran off it is said, He is of Virginia, is under Arrest & I think will have the honor of dying by a Bullet tho not in the Bed of Honor.3"],["p","The French begin to shew their teeth. They have spared us 200 brass Cannon, 30,000 Musquets, 100 Ton of powder; Salt petre & 1/2 Million of livres. Genl Coudray is coming out with several of the French Nobility. Dean (entre nous) says if We hold out this Summer, France must declare for us in the fall. I inclose you George's Speech. See he trembles for his Kingdom — but I can no more. You may shew this to my friends Johnston, Iredell & Smith to whom give my love. If they & you can read it you have the Advantage of your affectionate, Wm Hooper"],["p","[P.S.] I furnished your express Mushraw with 10£ proc. or 25 Cont dollars, remember it in your settle with him. Below is the Copy of a Resolve4 which concerns Mr Johnston, the Govs Warrant should be sent immediately & the board of War will send on the Money."],["p","I forget to tell you that Fras. Nash was made a Brig. Genl & is to go to the Northward.5"],["p","Write me to Wilmington immediately. I will send you the Resolve as to our Troops as soon as I can get any one to copy it. I am too sick to do it myself."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0284":{"title":"John Hancock to Robert Treat Paine","author_label":"John Hancock","kind":"letter","date":"1777-02-16","date_label":"February 16, 1777","date_type":"written","recipient":"Robert Treat Paine","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/300","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi). In a clerical hand, with signature and postcript by Hancock. Ad- dressed: \"To The Honble Robert Treat Paine Esqr., Chairman of the Come, for Procurg Cannon, at Boston or Taunton.\" 1 See JCC, 7:119.","authors":["john-hancock"],"paras":[["h","John Hancock to Robert Treat Paine"],["p","Sir Baltimore Feby. 16th. 1777"],["p","By the above resolve you will perceive Congress have desired you to agree wth. Colo. Gridley for forty 8 Inch Howitzers upon reasonable terms.1 I must beg your attention to it, cannot enlarge at this time being much hurried, shall write you more fully by Express. I am, your most Obed Hb Servt. John Hancock Prest."],["p","[P.S.] I Sent your Trunk by a Waggon with Money, which went off 1 1th Inst."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0319":{"title":"James Wilson to Arthur St. Clair","author_label":"James Wilson","kind":"letter","date":"1777-02-20","date_label":"February 20, 1777","date_type":"written","recipient":"Arthur St. Clair","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/333","text_status":"unreviewed_ocr","editorial_source_note":"RC (OHi). RC damaged; in the hand of James Wilson.","authors":["james-wilson"],"paras":[["h","James Wilson to Arthur St. Clair"],["p","My dear Sir [February 20, 1777] 1"],["p","Yesterday Congress proceeded to the Promotion of General Officers. There was much Difficulty and Delicacy in settling the Principles, on which the Promotions ought to be founded. I expresed my Sentiments in Favour of adhering to the Line of Seniority adoptjed, by Observations which I will not repeat [at present?] to you, that, if it was proper to deviate [from that line], you were the officer, in whose Favour the alteration ought to be made. Lord Stirling, General Mifflin, yourself, General Stevens and General Lincoln were chosen Major Generals. I need not express my Satisfaction at your Promotion. I feel peculiarly pleased that I have seen the Event take Place before I leave Congress."],["p","I am exceedingly hurt that our deserving Friend General Thompson was passed over: It is Misfortune sufficient to be a Prisoner. I am, however, willing to believe that the only Reason, with many Gentlemen, for omitting him was an Apprehension that a Promotion would increase the Difficulty of his Exchange."],["p","If you have not already engaged yourself, you will much oblige me by appointing Billy Bird your Aid de Camp. You will recollect that, when he first entered into the Service, I was solicitous he should be formed under you. You know [however, of his] Activity : He is young : But he is far from [being perfect] in Sense and Judgment. If he is not [yet exchanged; I hope his Exchange will soon take [place. I] have been informed that he has either obtained or has a Prospect of obtaining a Lieutenancy in the light Horse. But I would, on every Account, perfer what I now recommend him to."],["p","I have good Reason to believe, and think it not improper to hint, that the important Command of Ticonderoga is destined for you next Campaign. I presage it a Theatre of Glory.2"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0576":{"title":"John Hancock to Patrick Henry and to the Massachusetts Council","author_label":"John Hancock","kind":"letter","date":"1777-04-18","date_label":"April 18, 1777","date_type":"written","recipient":"Patrick Henry and to the Massachusetts Council","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/610","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 1 2 A ) . 1 See JCC, 7:242-43,258. 3 Or \"the former\" in the case of Massachusetts.","authors":["john-hancock"],"paras":[["h","John Hancock to Patrick Henry and to the Massachusetts Council"],["p","Gentlemen, Philada. April 18th. 1777."],["p","I have the Honour to enclose you the Resolves of Congress ordering"],["p","Monuments to be erected to the Memories of Genls. Warren and Mercer,1"],["p","and to request you will take proper Measures for carrying the Resolve into Execution relative to the latter.2 You will perceive the Congress have voted five Hundred Dollars for this Purpose."],["p","Every Mark of Distinction shewn to the Memory of those illustrious Men who offer up their Lives for the Liberty & Happiness of their Country, reflects the truest Honour upon those who pay the Tribute; and by holding up to others the Prospects of Fame & Immortality will animate them to tread in the same Path. I have the Honour to be, Gentlemen, your most obed. & very hble Svt. J H Presid."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0628":{"title":"John Adams to William Tudor","author_label":"John Adams","kind":"letter","date":"1777-04-27","date_label":"April 27, 1777","date_type":"written","recipient":"William Tudor","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/663","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi).","authors":["john-adams"],"paras":[["h","John Adams to William Tudor"],["p","Philadelphia April 27. 1777"],["p","Aha! Exchanging the Pride, Pomp and Circumstance of Glorious War, for the soft charms of Wedlock and domestic Felicity, I Suppose — abandoning Gun, Drum, Trumpet, Blunderbuss and Thunder, for the less terrible Sounds of the Wranglers at the Bar."],["p","Well! Young Folk must have their Way. But I suppose by that Time you have laid the Foundations of a Young Tudor or two, you will be on Fire again with military Ardor, and get into the Army."],["p","You must find the Pleasures of Books, and the City active and violent enough for your Nerves so long Stretched with the Grand and sublime Events of War."],["p","I believe it lies with the Agent to employ whom he will in filing Libells. But I have been so long out of the scaene that I know nothing about it. There will be soon a Navy Board in Boston, and then it will lie with them. Who the Men will be I know not. Men of Business and Integrity I hope. It would give me Pleasure to give you Business, if in my Power, but I dont know how. I am &c, John Adams"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0655":{"title":"William Whipple to Joseph Whipple","author_label":"William Whipple","kind":"letter","date":"1777-04-30","date_label":"April 30, 1777","date_type":"written","recipient":"Joseph Whipple","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/690","text_status":"unreviewed_ocr","editorial_source_note":"RC (MH-H).","authors":["william-whipple"],"paras":[["h","William Whipple to Joseph Whipple"],["p","My Dear Bror. No. 1 1 Philadelphia 30 Apl 1 777"],["p","My last acknowledged the receipt of such of Yours as have come to hand, I thot I had wrote you that I wish'd to be releav'd by the Middle of May, if I did not mention it to you, I certainly did to some body else for that has been my constant wish. My Colleague will not be very Cerimonious, he will set out in a few days, but I shod think myself inexcusable in leaving the State unrepresented at this Critical & important day, but my Health absolutely requires a Respite which I hope will be given me soon. It is very Unfortunate that Guns cannot be procur'd for the Ships, but I still hope the Raleigh will be supplied from the Furnice lately Erected in the Massachusetts, but why may we not have a Furnice in New Hampshire. I have heard there is a large Quantity of ore in Barrington, at no great distance from water carriage & streams suitable for Erecting works on, abound in that Country, & there is a Sufficiency of wood to supply a Furnice for many years, if the Proprietor of the land, nor the State will undertake to erect works, it wod be worth while for the Continent to do it provided the Ore is suitable for Cannon & the land could be obtain'd on reasonable terms. The American Navy will be increasing & I know of no place so suitable for Building ships as Piscataqua River & it wod be very convenient to have the Guns made near where the Ships are"],["p","Built. This is a matter worthy Consideration, I wish you wod pay some attention to it & let me know if its probable any thing can be done."],["p","Inclos'd you have Invoice of 10 bbs flour on board the Friends Adventure half of which I intended for you. As you had the trouble of fiting out those two vessels for Baltimore I suppose you will have the selling of the flour as greatest part of it will be for sail. The Army is increasing 'tho not so fast as I could wish. I cannot accot for the inactivity of the Enemy unless it is their weakness. I must refer you to Capt Thompson for news as perhaps he may collect some in his way home, at present there is none here 'tho we are in daily Expectation of a Packet from France, which no doubt will bring very interesting intelligence. The Bays of Delaware & Chesepeake are still infested by the Enemies ships, which makes the navigation very Hazerdous. Many of our merchantmen fall into their hands and some Privateers have been taken by them, in Perticular a Brig, mounting 16 Guns belonging to South Carolina Commanded by Tho. Pickering. The Culture of Hemp is a matter worthy of attention, I think if our Legislatures were to give suitable encouragement for that purpose, very good consequences might result therefrom, I just throw out the hint leaving it for those who have more leasure to form the Plan."],["p","Your most affecte. Bror, Wm Whipple"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0226":{"title":"Charles Carroll of Carrollton to Charles Carroll, Sr.","author_label":"Charles Carroll of Carrollton","kind":"letter","date":"1777-06-26","date_label":"June 26, 1777","date_type":"written","recipient":"Charles Carroll, Sr.","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (MdHi).","authors":["charles-carroll-of-carrollton"],"paras":[["p","Charles Carroll of Carrollton to Charles Carroll, Sr."],["p","Dear Papa, 26th June 1777. Pha."],["p","Johny arrived here yesterday evening & delivered me your letter of the 22d instant with its inclosures & £52.2.6. I return you the sundry letters which came under cover of your letter together with Mr. Lewis' letter. I really do think your correspondence with Chase was imprudent. What good did you propose to yourself by it? & why should you wish to be called before the assembly? To treat them as you have treated Chase you say: the consequence would be a commitment; perhaps, to Goal? Can you at your time of life bear such confinement? and would this conduct obtain a repeal of the law? Are you the only man injured by it? I have always thought it becoming a man to resent a private injury. I can not conceive that any individual is to turn Don"],["p","Quixote, or that the point of honor obliges him to combat whole bodies of men, particularly the Legislature of the State, which even when it errs, ought to be treated, at least, with complaisance, especially if it may be presumed that a majority has erred thro' well-meaning tho' mistaken principles: coarse language never yet corrected the folly or wickedness of man, or men — how honest would the British Park, have become, if the harshest epithets & the severest language could reform dishonesty? I intreat you to make yourself easy; fretting only hurts yourself & exposes you to the raillery or malice of your enemies. I have no apprehension of Wallace & Co. offering to discharge their balance due in England, in our paper money; if they were to make the offer I would reject it; they can not under the law compel us to receive that currency in payment. Johny tells me he thinks that neither yr. appetite or spirits are so good as they were when I left you. I suppose the chagrin occasioned by the unjust law above alluded to, & your confinement in consequence of your sore leg may occasion both — when the weather permits, I would advise you to use the exercise of your chair, and above all endeavour at a serenity of temper. If we succeed, & I have the strongest hope we shall, the money will be good in the end; it will & must surfer a temporary depreciation, which will not affect us very considerably. I am pleased to find a very considerable, nay a very great majority of Congress as anxious for a confederacy, as I am or you can be. The necessity of this measure is now obvious almost to every man, yet I fear the confederacy will not be formed on principles so mutually advantageous as it ought & might be: but in my opinion an imperfect & somewhat unequal Confederacy is better than none. We have not heared from Gen. Washington since the 22d nor do we know where abouts the enemy is encamped. General Arnold returned the day before yesterday to this house from Corryel's ferry, the enemy have abandoned in appearance all thoughts of marching thro' the Jersies to this city. I cannot think the piece signed Meanwell to be written by Chase — nor is there any thing contained in it to warrant the Major's suspicion, but I suppose he has better grounds for his conjecture.1 I can not think Chase will attempt so undisguised a violation of our Bill of Rights as to move for such an appropriation as is mentioned by the Major. The Proprietary's Estate is somewhat differently circumstanced, and maybe in Jeopardy. The regalities most assuredly must be surrendered up. A purchase of his Q[uit] R[en]ts would be the most equitable manner of proceeding, but what is most equitable in such Convulsions as the present seldom takes place."],["p","27th June"],["p","By the Evening post of yesterday you will learn the situation of the enemy. Gen. Washington writes they are too strongly posted to be attacked in their present situation, but that he has parties ready to take advantage of their movement.2"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0243":{"title":"Charles Carroll of Carrollton to Charles Carroll, Sr.","author_label":"Charles Carroll of Carrollton","kind":"letter","date":"1777-06-30","date_label":"June 30, 1777","date_type":"written","recipient":"Charles Carroll, Sr.","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (MdHi).","authors":["charles-carroll-of-carrollton"],"paras":[["p","Charles Carroll of Carrollton to Charles Carroll, Sr."],["p","Dear Papa 30th June 1777."],["p","I just write to inclose you a copy of Gen. Washington's last letter to Congress & acknowledge the receipt of yr. letter of the 25th past, which I shall answer more fully by Johny, whom if Sam continues to mend, I shall send off in 3 or 4 days from this day. Sam is out of all danger, but not well enough to wait upon me yet. I hope Molly will excuse my detaining him here, tho it may possibly prevent her going to Miss Carroll's wedding. I refer you to the inclosed newspaper for eastern news. It"],["p","gives me great pleasure to hear that your leg is healing. I hope it will soon be perfectly healed that you may take your evening's walk as usual."],["p","1st July"],["p","Upwards of 4,000 stand of muskets have lately arrived at an eastern port on Account of the Massachusetts State & on continental acct the following articles vizt. 285 pieces of shirting, 54 do of Duck, 52 Tons of cordage & 16 large anchors. Commodore Manly has taken a Snow bound from London to N.Y. with cordage, duck, &c. A transport has been taken by a privateer bound for Quebec with 32 recruits, a captain & Lieutenant. A transport has been taken by one of our sloops of war after 9 glasses fight with 70 soldiers bound for N. York. I mention these articles of news least the newspaper should not be out in time to go by this post. My love to Molly & Mrs. Darnnall. Sam rested well last night & continues to mend. I hope I shall be able to send Johny off Thursday or Friday next. Wishing you a long continuance of health I remain, yr. affectionate Son, Ch. Carroll of Carrollton"],["p","P.S. Not being able to get the Pena. packet I send you the last Boston paper brought by yesterday's post. We have no news from the General since his last letter which you have inclosed. I write this in Congress at 10 o'clock."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0257":{"title":"Charles Carroll of Carrollton to Charles Carroll, Sr.","author_label":"Charles Carroll of Carrollton","kind":"letter","date":"1777-07-04","date_label":"July 4, 1777","date_type":"written","recipient":"Charles Carroll, Sr.","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (MdHi). A continuation of Carroll to Charles Carroll, Sr., June 29, 1777.","authors":["charles-carroll-of-carrollton"],"paras":[["p","Charles Carroll of Carrollton to Charles Carroll, Sr."],["p","4th July A.M. 7 o'clock. We had yesterday advices from Gen. St. Clair, who commands at Tionderoga, as low down as the 26th ultimo.1 The Enemy were approaching: their fleet was on the lake, part of it at Crown Point, but uncertain whether they had landed any forces there. They had landed Some on Chimney point opposite to Crown Point. They had an encampment at Gilliland's Creek 45 miles below Crown Point: several of our People have been killed or taken by small parties of Indians within a very small distance of our lines at Tionderoga. Our garrison is weak, not exceeding 2500 effectives: however if they defend themselves well, time may be given to collect a force sufficient to prevent the place from falling into the enemy's hands, but the garrison is badly armed & cloathed. If the Enemy [waste?] away their time & delay their attack"],["p","to the middle of this month, I have hopes we shall keep possession of Tionderoga, at least of Mount Independance. This day the Congress dine at Smith's Tavern. You will see by the inclosed paper it is to be celebrated as the anniversary of Independance. When Sam gets well enough to travel, I believe I shall return home as our State will be represented without me.2 But I am anxious before I leave this place to see what sort of confederation will be formed & on which side G. Howe will begin his operations. Give my love to Molly & Mrs. Darnall. I shall write to you again by next Tuesday's post. I am, yr affectionate Son,"],["p","Ch. Carroll of Carrollton"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0374":{"title":"John Hancock to the States","author_label":"John Hancock","kind":"letter","date":"1777-08-03","date_label":"August 3, 1777","date_type":"written","recipient":"the States","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 12A).","authors":["john-hancock"],"paras":[["h","John Hancock to the States"],["p","Gentlemen, (Circular) Philada. Augt. 3d. 1777."],["p","While the American War continues, & our cruel Enemies manifest a Disposition to persevere in their Views of reducing us by Force of Arms to submit to their Dominion & Government, it becomes the United States to pursue every Step in their Power to oppose them. The American Army, from the Events of War, and other Losses unavoidable in Camps, must necessarily suffer a considerable Diminution. To supply this continual Waste, as well as to encrease our Army, and to fill up the Regiments which were to be raised by the respective States, must certainly be an object of the utmost Importance. The Congress therefore in Hopes of accomplishing their Views in this particular, and rendering the Army of the United States sufficiently strong to vanquish our Enemies, have come to the enclosed Resolves, which are extremely well calculated to answer those Purposes, and if adopted by the States, cannot, I flatter myself, fail of Success. I beg Leave to request your particular attention to them, and also Compliance therewith.1 I have the Honour to be, Gent., Your most obedt. Set."],["p","J.H. Presid."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0450":{"title":"Samuel Adams to Elizabeth Adams","author_label":"Samuel Adams","kind":"letter","date":"1777-08-19","date_label":"August 19, 1777","date_type":"written","recipient":"Elizabeth Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (NN).","authors":["samuel-adams"],"paras":[["h","Samuel Adams to Elizabeth Adams"],["p","My dear Betsy Philade Augt 19 1777"],["p","I was favord with yours of the 2d of this Month by yesterdays Post. I am much obligd to you for writing to me so often, and hope you will not omit any future opportunity. One or another of my Boston Friends write to me by every Post, [sol that I think I should be informd if any extraordinary Accident should happen to my Family, but I am never so well satisfied as when I receive one from you. I am in continual Anxiety for your Safety, but am happy in committing you to the Protection of all gracious Heaven. May He be your Refuge in every Time of Distress! I had before heard that the Enemies Fleet was seen off Gape Ann. We had an Account of it by an Express from General Heath, who contradicted it the [same] Day by another Express. Indeed I did not give Credit to [the] News for the British Ships were seen off the Maryland Shore on the first of August, the very day on which they were reported to have been seen off Cape Ann. Having the Command of the Sea, they have it in their Power to give frequent Alarms to our Seaport Towns. We have not heard of them since, and it is the opinion of some that they are gone to South Carolina, but as it is altogether uncertain when they will go, it is prudent to be ready to receive them in every Place. It is a Question with me whether they have any Plan upon which they can depend themselves. I pray God that [their] Councils may be confounded."],["p","I earnestly hope with you, my Dear, that our [. . .] Life is not always to live at this Distance from each o[ther] but that we shall see the happy Day when Tyranny sfhall] be subdued and the Liberty of our Country shall be settled upon a permanent Foundation. If this is not to be accomplishd in our Day, May we hereafter meet our virtuous Friends in that blessed Region, where the wicked shall cease from troubling."],["p","My Love to my dear Daughter, Sister Polly & the rest of my Family & Friends. Tell my Servants I thank them for their kind Remembrance of me. I am, my dear, ever yours, S.A."],["p","[P.S.] I have sent the Letter to Capt. M. inclosd in one to Dr F."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0518":{"title":"John Hancock to William Livingston","author_label":"John Hancock","kind":"letter","date":"1777-08-30","date_label":"August 30, 1777","date_type":"written","recipient":"William Livingston","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 12A).","authors":["john-hancock"],"paras":[["h","John Hancock to William Livingston"],["p","Sir, Philada. Augt. 30th. 1777."],["p","The Congress having received such Information of the Disaffection of the Quakers as to leave the Matter no longer doubtful, they have come to the enclosed Resolves recommending it to the different States forthwith to apprehend all Persons of that Society, and indeed all others, who have evidenced by their Conduct & Conversation a Disposition inimical to the Cause of America. It is also recommended to the different States to take Possession of the Records & Papers of the Meeting of Sufferings and that such Parts of them as are of a political Nature be transmitted to Congress.1 I beg Leave to refer your Attention to the"],["p","whole of the enclosed Resolves, and shall only add that the greatest Secrecy is highly necessary touching the Premisses. I have the Honour to be, with Respect, Sir, your most obed. & very hble Set."],["p","J.H. Presid"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0607":{"title":"Robert Morris to Abraham Whipple","author_label":"Robert Morris","kind":"letter","date":"1777-09-17","date_label":"September 17, 1777","date_type":"written","recipient":"Abraham Whipple","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (Capt. J. G. M. Stone, Annapolis, Md., 1973). In the hand of John Swan- wick.","authors":["robert-morris"],"paras":[["h","Robert Morris to Abraham Whipple"],["p","Sir Philada. Septr. 17th. 1777"],["p","The Attempt Genl. Howe is now making to get possession of this City has caused me to remove my Family, Books, Papers &ca. to a place of Safety. Consequently I can not attend closely to my Correspondents till something decisive is done & this is all I have to offer in extenuation for my not answering by this post your favr. reed, by yesterday's, Time not permitting me to add any thing more than just to assure you that indeed I am, Sir, Your Obedt. hble Servt. For Robt. Morris,1 John Swanwick"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v09.0640":{"title":"Josiah Bartlett to Meshech Weare","author_label":"Josiah Bartlett","kind":"letter","date":"1778-05","date_label":"May 1778","date_type":"written","recipient":"Meshech Weare","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 9","source_url":"https://archive.org/details/lettersofdelegat09libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi).","authors":["josiah-bartlett"],"paras":[["h","Josiah Bartlett to Meshech Weare"],["p","Hond Sir York Town May the 27th 1778"],["p","I arrived here the 21st Inst, in the Morning."],["p","Mr. Wentworth & his waiter were Innoculated at Fish Kills the 13th, and rode with me to Reading about 46 miles from this place."],["p","where by the advice of Genl Gates, they tarried till they should get thro' the disorder. Mr. Wentworth began to have the Symptoms about 20 miles before he arrived there. I have not heard from him since I left there the 19th."],["p","I think it my Duty to inform you that the President of Congress thinks himself neglected in not receiving answers to his letters. He Desired to know of me whether our Governor had Receivd any letter from him for Eight months past: that he had Reed no answer to any of his for that time; tho he had taken particular Care to Send Duplicates as often as he trusted them to the Common posts. I Endeavoured to Excuse the matter as well as I could, by telling him that some of his letters were little more than covers to acts 8c resolves of Congress which were supposed to Require no other answer than a Compliance with their Directions: that I Believed Some answers had been sent since that time, which by reason of the irregularity of the post were not come to hand. He said that Every letter that he wrote by order of Congress, deserved an Answer, at least so far as to let it be Known that it was received; that the way to know whither any letter miscarried, was to keep up a constant Correspondance and note the last letter sent; that it would be but a small matter on the Receipt of Every letter to inform of its being Receivd, if nothing more; and when any thing was done in consequence of any order of Congress to let it be known Sec Sec Scc.^"],["p","The Confederacy is not yet Ratified, North Carolina being unrepresented 8c two or three of the other States not having impowered their Delegates to Confirm it; It is the opinion here that it will be Universally agreed to."],["p","I have nothing new to inform you of, more than you will see in the Public papers."],["p","I am with the greatest Respect Sir, your most obedient. Humble Servant, Josiah Bartlett"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v10.0270":{"title":"Samuel Adams to James Warren","author_label":"Samuel Adams","kind":"letter","date":"1778-07-20","date_label":"July 20, 1778","date_type":"written","recipient":"James Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 10","source_url":"https://archive.org/details/lettersofdelegat10smit","scan_url":"https://archive.org/details/lettersofdelegat10smit/page/314","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi). FC (NN).","authors":["samuel-adams"],"paras":[["h","Samuel Adams to James Warren"],["p","My dear sir Philada. July 20 17781"],["p","Last Saturday a Letter was brought into Congress from the British Commissioners. You have it in the inclosd News Paper with a short Resolution upon it.2 This shuts the Door and it will remain shut till they will be pleasd to open it again. Governor Johnston has acted so base a Part as to hint the offer of Bribes to the President and every other Member of Congress, as well as the General, as you will see in the printed Letter to Mr. R. Morris. By this he has in my Opinion forfeited the Character of an honest Man and exposed himself to"],["p","the just Comtempt of the World.3 I hope some Strictures will be made in the News Papers on this, as well as the disrespectful and even insolent Language in the Commissioners Letters, not so proper to be noticed by Congress. I have lately been well assured that a Bribe of ten thousand Guineas has been offerd to a Gentleman of Station & Character here. He refusd it, as you might well suppose, with proper Resentment, telling the Lady who negociated this dirty Business, that the British King was not rich enough to purchase him.4"],["p","Mr D,5 of whom I may hereafter have much to say to you, is arrivd with the Sieur Gerard. I have long ago made up my Opinion of the American Commissioner, & have not yet alterd it. That of the French Minister is a sensible prudent Man, not wanting in political Finesse, and therefore not to be listend to, too implicitly. The French Squadron lies off Sandy Hook. I have inclosd the Names & Rates of the Ships that compose it; together with those of the British Ships in the Harbour of N York as deliverd to the Marine Committee by a Prisoner lately escaped from thence. Their Force bears no Proportion to each other. I am told that this is a favorite Expedition of Count D Estaing himself, proposd by him6 to the French Court, and that his Reputation depends upon the Issue of it. What Foundation there is for this, I do not know. From the Character of this Admiral, I make no Doubt he will fully answer the reasonable Expectations of the King his Master and of America. Mr. Ds political and commercial Friends, some of whom I suppose are in Boston, are disposd to give him great Eclat, on Account of the Aid afforded us in sending this Squadron. His Interest is represented as having been very forceable in procuring it, and the News Papers mention the Tokens of great Respect shown to him by the King & his Ministers at Versailes. The Truth, as I conceived it is, The total Overthrow of Burgoyns Army was an Event which it was thought, would produce Overtures from Britain, and France was apprehensive of our listening to Terms and compromising Matters. Hence it was, more than from any other Cause or the Interest of any Individual, that a Treaty was facilitated and agreed to; and to secure us in their Alliance and support us in our Independence was, I suppose, their Intent in sending this Squadron as well as the Purpose of Mr Gerards Mission.7"],["p","I have not yet answerd your Letter of the 26th of June. I declind it until I could assure you that the Sum you wishd for, for the Use of your Department, was granted.8 I now have the Pleasure of acquainting you, that it is done and the Money will be orderd on as soon as it arrives here from York Town, which is every hour expected.\" I am in Pain about the Ship in your Harbour. Her Owners neglect to put her into Repair, and I fear, some of her officers for Want of Skill and Experience will be at a Loss what to do with her"],["p","if she should meet with a Storm. What a Pity it is that an honest old Pilot, who used to steer successfully through Rocks and Quicksands has lately been dischargd from Service! And that he should suffer this hard Usage, only because unknown to him, One who was a hearty well wisher to the Voyage, and was anxious that Capacity and Merit should always govern Promotions, had ventured to declare him the fittest Man to take the Command, when it was thought a Commander would be wanted. Vanity and Avarice, which create an insatiable Desire of Places and Preferment, without Ability or Intention to fulfill the Duties of them, if gratified, would effect the Ruin of a Country. It would be the Glory of the American Republick, to find Men having no ruling passion but the Love of our Country, and ready to render her the most arduous Services, with the Hope of no other Reward in this Life, but the Esteem of their Virtuous Fellow Citizens. But this, some tell us, is to wish for more than it is in the Power of human Nature to give."],["p","1 find Mr Dana an excellent Member of Congress. He is a thorough Republican, and an able Supporter of our great Cause. I am satisfied it would be for the great Benefit of our Country if you and he were to form an intimate Connection with each other. This I am the more desirous of, because I have no Idea of your being long secluded from the publick Councils. He will go home shortly."],["p","Adieu My Friend. S A."],["p","P.S. I shall take it as an Act of Kindness if you will call on Mrs A & let her know I am well— not having Leisure to write to her by this Post."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v10.0354":{"title":"Josiah Bartlett to Mary Bartlett","author_label":"Josiah Bartlett","kind":"letter","date":"1778-08-09","date_label":"August 9, 1778","date_type":"written","recipient":"Mary Bartlett","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 10","source_url":"https://archive.org/details/lettersofdelegat10smit","scan_url":"https://archive.org/details/lettersofdelegat10smit/page/410","text_status":"unreviewed_ocr","editorial_source_note":"RC (NhHi).","authors":["josiah-bartlett"],"paras":[["h","Josiah Bartlett to Mary Bartlett"],["p","My Dear Philadelphia August 9th 1778"],["p","This will go by Express inclosed in a letter to Colo. Langdon,1 just to let you Know I am well: Charles Chace has had a very bad turn of the Camp Distemper; I am in hopes he is rather better, as he Could not be taken Care of where I board 8c the Gentlemen who board here were not willing he Should Remain Sick in the House, I have procured a place for him at a Distant part of the Town where he is taken good Care of, and I visit him Morning & Evening, his fever Continues but his Bloody flux is abated. I hope & believe he will Recover."],["p","Mr. Wentworth is arrived here, but in so bad a State of health that he Does not attend Congress. If he Does not get better Soon I Suppose he will Set out for Home.2 Last Thursday the minister Plenipotentiary of France had his Public audience of Congress: The Speches made by him & the answer of Congress, with the King of France's Letter of Credentials to Congress will be printed tomorrow3 and I will try to Send them by the Post on Tuesday."],["p","The next news of importance is Expected from Rhode Island and I Suppose you will hear what is Done there before you Receive this letter. We have nothing very material here at present. I am 8cc,"],["p","Josiah Bartlett"],["p","[PS.] Remember my Love to all my Children."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v10.0487":{"title":"Gouverneur Morris to George Washington","author_label":"Gouverneur Morris","kind":"letter","date":"1778-08-31","date_label":"August 31, 1778","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 10","source_url":"https://archive.org/details/lettersofdelegat10smit","scan_url":"https://archive.org/details/lettersofdelegat10smit/page/542","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC).","authors":["gouverneur-morris"],"paras":[["h","Gouverneur Morris to George Washington"],["p","Dear General. Congress 31 August 1778."],["p","I wrote you a Letter long since which went backwards & whether it hath ever Yet got so far forwards as to reach you I am utterly incapacitated even to guess, trusting however that you have got or will get it I shall not from Memory repeat what if there at all is at best but faintly traced."],["p","At present I trouble you on the Subject of recruiting your Army which is at this Moment in Debate before the House. It hath been proposed to give ten Dollars in Specie and ten Square Dollars to Recruits which I have offered and it is determined in the Negative.1 I will not fatigue you with the Reasons opperating on my Mind, they derived not inconsiderably from the probable Consequences of the Measure even upon the Army. Among others I fear to inflame the Rapacity of Soldiers with the Love by the Possession of a Metal of which we have such a plentiful Lack. However let me have your Sentiments for I can promise you a Mind open to Conviction if you differ in Opinion desirous of Information in all Cases and willing to urge your good Reasons should the Matter be again opened."],["p","I can send you no News and therefore I shall only repeat what you knew before that I am, most sincerely yours,"],["p","Gouv Morris"],["p","[P.S.] My compliments to Bannister, to Genl. Reed, to all Friends."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v10.0615":{"title":"Samuel Adams to James Warren","author_label":"Samuel Adams","kind":"letter","date":"1778-09-22","date_label":"September 22, 1778","date_type":"written","recipient":"James Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 10","source_url":"https://archive.org/details/lettersofdelegat10smit","scan_url":"https://archive.org/details/lettersofdelegat10smit/page/680","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi).","authors":["samuel-adams"],"paras":[["h","Samuel Adams to James Warren"],["p","My Dear Sir Philadelphia Sept 22 -78"],["p","The Bearer of this Letter Ebenezer Hazard Esq is a sensible Gentleman of good Character, and has had a liberal Education at the College in Princetown. He has a few years past been at Pains to obtain Copies of publick Records and Manuscripts relating to America. These with such others as he may be able to avail himself of he intends to publish, in hopes that some other gentleman finding Materials thus collected may be induced to furnish the Publick with the History of the United States. Congress has countenanced his laudable Undertaking.1 As I am sure you are ready to afford Assistance to a Person disposd to serve Mankind in this or any other Way, (and I can assure you he is true Republican Whigg) I have taken the Liberty to recommend him to your patronage. Might he not be permitted to have Access to the Records of our State— Are there not some valuable Manuscripts in the Hands of private Gentlemen in the County of Plymouth or in the Records of that County or Town? The Papers which were carefully collected by the late Revd & curious Mr Prince were left to the Hon Mr Gill. It might perhaps serve Mr Hazards Purpose to be introducd to that Gentleman. But I forget that you have your Hands full of publick Business. Excuse me my Friend. Adieu. Your affectionate,"],["p","S Adams"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v10.0646":{"title":"Robert Morris to Jean Holker","author_label":"Robert Morris","kind":"letter","date":"1778-09-29","date_label":"September 29, 1778","date_type":"written","recipient":"Jean Holker","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 10","source_url":"https://archive.org/details/lettersofdelegat10smit","scan_url":"https://archive.org/details/lettersofdelegat10smit/page/711","text_status":"unreviewed_ocr","editorial_source_note":"Tr (DLC).","authors":["robert-morris"],"paras":[["h","Robert Morris to Jean Holker"],["p","Dear Sir Philada. Septr. 29th. 1778."],["p","I hope this will find you Safe and Sound in Boston after an agreable journey. As you will probably have many things to claim your attention in Boston, I mean to trouble you as little as possible and Shall therefore avoid writing to you, unless when matters of business require it.1 This is now the case— Major Franks having informed me that the Schooner Dolphin of Virginia lately commanded by Capt. Josh Peck and belonging to my friend Mr. S. Bealle of Williamsburg is now with the Count D'Estaing. She was taken by the Roebucks Tender a Brigt & Retaken by your fleet when lying off Sandy Hook. She was laden with 70 hogsheads of Tobacco, which was taken out as Mr. Franks tells me and distributed amongst the Fleet, and the Vessell being a fast Sailor and having Guns was detained for a Tender to the Fleet. I imagine that the former Owners of this Vessell have a good claim to her and paying Such Salvage as the Recaptors may be intittled to by the marine ordinances of France provided for Such cases, for this Schooner had been but a Short time in possession of the British When retaken and had not been in port to be Condemn'd. Mr. Bealle has wrote me Several Very pressing letters to put in his Claim and he can make all the Needfull Proofs of his property, 8cc. I am however a good deal at a loss as to the proper mode of proceeding and must rely on you to do in the Premises whatever is right and I beg you will advise me as Soon as you can of your proceedings and of what may be necessary for Mr. Bealle to do in the matter. Col. Langdon has Sent a young Gentleman here who proposes paying me the ballance due me and in that case you will not have any money to receive from him on my Accot. I have"],["p","not Sold any bills Since you left this altho' Some enquiries have been made alter them; but that business may perhaps as well remain untill you return as you are not here to draw the bills if agreed for. I congratulate you on the good news from Dominica and hope Soon to hear of Some more important Strokes in the West Indias. Mrs. M joins me in best compliments & Wishes, Being Dear Sir, your affectionate Friend & obedt. hble sert. Sfigned]. R.M."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v11.0054":{"title":"Samuel Adams to James Warren","author_label":"Samuel Adams","kind":"letter","date":"1778-10-14","date_label":"October 14, 1778","date_type":"written","recipient":"James Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 11","source_url":"https://archive.org/details/lettersofdelegat11smit","scan_url":"https://archive.org/details/lettersofdelegat11smit/page/56","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi: Warren- Adams Papers).","authors":["samuel-adams"],"paras":[["h","Samuel Adams to James Warren"],["p","My dear Sir. Philada. Oct. 14, 1778."],["p","In my last 1 1 inclosed a News Paper containing certain Queries calculated, as 1 conceive, to blast the Reputation of a truly virtuous Man. Dr. Lee and Dr. Berkenhout mentioned by the Querist, were formerly fellow Students at Edinburg; and as both were esteemed learned in their Profession, it is not improbable that on that Account they kept up their Acquaintance while both continued in Great Britain. Dr. Lee, you know was requested by Congress to go over to France, where he was made a joynt Commissioner with Messrs. Franklin & Dean. It is possible that a Correspondence afterwards have been carried on between them; but from the Knowledge I have of Dr. Lee, I will venture to pledge my self it was not a criminal one as the Querist would seem to insinuate, and if Dr. Berkenhout was in the Service & under the Direction of the British Ministry, which by the Way is but bare Suspicion here, it must have been utterly unknown to Dr. Lee: I am rather inclind to think it is a Creature of the Querists own Fancy, or an artful Suggestion thrown out to the Publick, to serve the Cause of our Enemies. America should beware how she suffers the Character of one of the most able & vigilant Supporters of her Rights to be injured by Questions designd to impute Slander without any Reasons offerd why such Questions should be made. It is the old Game of mischievous Men to strike at the Characters of the Good and the Great, in order to lessen the Weight of their Example and Influence. Such Patriots as Lord Russel 8c Algernon Sydney of the last Age, have been of late falsely and audaciously charged, by a Scotch Tool of the most nefarious Court in Europe, as having receivd Bribes from the Ministers of France;2 and it is not strange that a Gentleman whom the leading American Whigs have placed high in their List of Patriots, who has renderd the most laborious 8c important Services to our Country in England,"],["p","France & other Parts of Europe, who has so often & so seasonably developd the secret Intrigues & Practices of wicked Men, and who at this Time stands high in the Esteem $c Confidence of the Congress, & when it is considered in Addition to this, that there are too many disaffected & insidious Men still lurking among us, it is by no Means a strange thing to hear it insinuated by an anonimous Writer, that Dr. Lee also is chargeable with a criminal Correspondence with the Enemy, without even the Shaddow of Reason."],["p","You may publish this if you think proper, f receivd your favor of Sept. 30th.3 It contains very interesting Matter which shall have my Attention at a more leisure Hour than the present. In the mean time Adieu my Fd. S. A."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v11.0129":{"title":"Roger Sherman to Jonathan Trumbull, Sr.","author_label":"Roger Sherman","kind":"letter","date":"1778-10-27","date_label":"October 27, 1778","date_type":"written","recipient":"Jonathan Trumbull, Sr.","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 11","source_url":"https://archive.org/details/lettersofdelegat11smit","scan_url":"https://archive.org/details/lettersofdelegat11smit/page/136","text_status":"unreviewed_ocr","editorial_source_note":"Tr (DLC: Force Collection).","authors":["roger-sherman"],"paras":[["p","Roger Sherman to Jonathan Trumbull, Sr."],["p","Sir Philadelphia Octr. 27th. 1778"],["p","The great affairs of Finance, and the Clothing Department are yet unfinished— the delay of these important matters gives me great anxiety. I have used my utmost endeavours to forward them. I wish another Delegate might be immediately sent from Connecticutwas in hopes Col. Dyer would have come before now. The Committee appointed to consider your Excellency's letter respecting the late Commissary Trumbull's affairs, have not yet made report, tho' I understand they are ready when Congress can receive it. I dont know what their Report will be. The affair of the currency is to be further considered to day.1 The members in general seem to be at a loss what can be done to restore its credit. The plan that appears to me most probable to be adopted, is to recommend to the Legislatures of the several States immediately to pass acts to raise by taxes about five millions dollars annually for eighteen or twenty years, as a sinking fund, sufficient for the redemption of all the Bills and Loan Office certificates, to take out of currency about fifty millions Dollars by loan, to lay a tax of about twelve or thirteen millions dollars for the expence of the next year; and if further emissions are necessary; that additional funds be provided for sinking them within the time limited for sinking those that are now outstanding; so that the possessors of the Bills and lenders of money be able to make a just estimate of the value of their securities.2 A note for £.100 on compound interest, payable at the expiration of 20 years would be equal to one for £321 for the same term without interest. If the Bills of public credit, so far as they exceed a sufficient quantity for a medium of trade, are to be considered only as securities for money without interest, rebating the compound interest for the time before they are redeemable will determine their present value, and they will gradually appreciate as the time of their redemption approaches. Enclosed is a computation of the annual increase of £100 for 21 years on compound interest. I wish to be favored with your Excellency's opinion on the best mode of establishing the credit of the currency. I expect that it will be referred to the several States to clothe their quotas of the army for the future, and that the Continental clothing on hand, and which may be imported in consequence of orders already given will be divided to the several States in some just proportion."],["p","There has been a late embarkation of troops at New York, but we dont yet learn their destination. We hear they are leaving Staten Island. Some think they are about to abandon New York and leave the country. Others conjecture they will make an attack on Boston, and attempt to destroy the French fleet."],["p","We have no late advices from Europe— no letter from Mr. John Adams in France has been received of later date than last May."],["p","I am with the greatest Respect and Esteem, Your Excellency's Obedient humble Servant, Roger Sherman"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v11.0191":{"title":"William Whipple to John Langdon","author_label":"William Whipple","kind":"letter","date":"1778-11-09","date_label":"November 9, 1778","date_type":"written","recipient":"John Langdon","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 11","source_url":"https://archive.org/details/lettersofdelegat11smit","scan_url":"https://archive.org/details/lettersofdelegat11smit/page/193","text_status":"unreviewed_ocr","editorial_source_note":"Tr (DLC: Force Collection).","authors":["william-whipple"],"paras":[["h","William Whipple to John Langdon"],["p","My Dear Sir, Philadelphia 9th Novr 1778"],["p","Your letter No 1 is just come to hand. I could have wished you had given me some account of the cartel that arrived from York the day I set out. I found on my arrival here money had been sent you from the Commercial Committee.1 What you have for the use of the Navy must go through the Commissioners at Boston at present. I find Congress exceedingly pressed with business— the great object is finance— you will (I hope) soon hear what is done in that matter. In the mean time it is the duty of every individual to endeavor to keep up the value of the money. Every movement of the enemy at York seems to indicate their intention of leaving that place.2 I have not been able to do any thing yet respecting the Ranger, but hope shall by next post. Every kind of thing is rising here with an unparallelled rapidity— flour is got to 20 dollars and wheat 30/. I could wish to give you a particular account of things here, but time will not permit me. Adieu, your friend &c. Wm Whipple"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v11.0336":{"title":"William Paca to Thomas Johnson","author_label":"William Paca","kind":"letter","date":"1778-12","date_label":"December 1778","date_type":"written","recipient":"Thomas Johnson","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 11","source_url":"https://archive.org/details/lettersofdelegat11smit","scan_url":"https://archive.org/details/lettersofdelegat11smit/page/332","text_status":"unreviewed_ocr","editorial_source_note":"RC (PHi: Etting Collection).","authors":["william-paca"],"paras":[["h","William Paca to Thomas Johnson"],["p","Dr. Sir. 12 Dc. 1778"],["p","I enclose you a few Blank Commissions & Bonds. Congress have lately ordered a new Form for Commissions which will Soon be published and therefore I send a few only of the old.1 I send you some Instructions. I could not find the President to sign them and the [. . .] could not wait. By a Letter from Genl. Washington of the 7th Instant we are in-"],["p","formed that Clinton & his Armament have returned back without being able to effect any Thing except burning a House or two at Kings Ferry. The General conjectures that Clinton was misinformed of the Strength of the Highland Forts. Our army are moving into Winter Quarters. Yrs. [. . .], W Paca"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v11.0446":{"title":"Robert Morris to Henry Laurens","author_label":"Robert Morris","kind":"letter","date":"1779-01-11","date_label":"January 11, 1779","date_type":"written","recipient":"Henry Laurens","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 11","source_url":"https://archive.org/details/lettersofdelegat11smit","scan_url":"https://archive.org/details/lettersofdelegat11smit/page/452","text_status":"unreviewed_ocr","editorial_source_note":"RC (ScHi: Laurens Papers, no. 23).","authors":["robert-morris"],"paras":[["h","Robert Morris to Henry Laurens"],["p","Sir Philada. Jany. 11th, 1779."],["p","I am to acknowledge the Honour of Your Communication of this Morning.1 I shall say nothing as to the Propriety of Vindicating yourself in the News paper, nor pretend to determine whether there is or is not a better Method."],["p","Your own feelings must prompt and your own judgement direct you. For myself I am indifferent what attacks may be made on me. I feel a consciousness of innocence which puts me above every Effort to cast a stain on what, I thank God, hath hitherto been an unblemished reputation. Since you have enclosed that paper to me I am under the necessity of pointing out some of those instances in which from inadvertancy you have mistated Facts lest a silent Acquiescense shou'd be misconstrued into admission."],["p","You will observe that I have not chosen the Press as a Tribunal for the liquidation of Accounts but being charged Publickly by Name, I was under a Necessity of defending myself in my own Name publickly. \"The one other Fact, you allude to— which if proved must affect my reputation\" or rather one other allegation, I never heard untill last Saturday Evening when a Gentleman informed me what passed in Congress on the Subject. I have here to add that no circumstances could have given me greater pleasure than to learn that matters which had so long been the groundwork of private Conversation against me, were now to be publickly investigated and I will add, Publickly refuted."],["p","I am little solicitous who gave you the information, but am to thank you for the Public communication, and confess my astonishment that the similar declaration at York Town, if such was made, was not followed by an immediate investigation for I agree with you that if it be true the Public ought to be informed, and I go farther the offender ought to be punished. Why I have not made an enquire into that charge is already answered for I could not enquire after things I had not heard and never shou'd expect to be charged with."],["p","The reason why I did not call on you was that from my information, you had only drawn wrong conclusions from mistated Facts, and thence taken an opportunity to urge insinuations to my disadvantage, to which a justification of myself before Members of Congress was unnecessary, and their cordial and unabated Friendship to me convinced me I had done what was right on that occasion."],["p","You are mistaken if you suppose I said that I hoped to accomplish the Settlement of the Books in question in about two Months. I did not say so."],["p","I agree that you or I or any person that understands Book-Keeping might soon post up the Books had the Entries been regularly made in the waste Book. They were not, but minutes of the Committee were regularly Kept, from which and the letters and Accounts in their possession, those Entries can be made. This is the State of that matter & this I Stated to Congress while you was in the Chair and Moved a resolution that the Members of that Committee should be directed to finish the Settlement of those Accounts,2 and when the Honourable"],["p","454 January 11. 1779"],["p","R. H. Lee Esqr. declined this task then I asserted that I had no more business to settle the Books than (not any body else, but [)] any Member of that Committee. If there was no decision in Congress on my letter of the 8th Feby., Mr. Lewis 8c Mr. Ellery must justify themselves for signing and Sending me the answer I have published.3 I cannot suppose they wou'd have done it without proper Authority therefore am inclined to think they can set you right in that respect. You have much misapprehended what passed in Congress in Septr. 1778. I informed Congress that I had Worked at the Books of the Secret Committee untill the Ledger was filled so that there was no room for opening new Accounts and that I had delivered the Books to the Clerk of the Commercial Committee. So far from saying, \"that I had done all I could in the Books\" (except on acct. of the Ledger) \"and that they were in such Confusion I could make nothing of them and therefore wished to be rid of them.\" I deny the Fact. I never entertained such Sentiments and declared quite the reverse. I said the Accounts were in such forwardness that they might easily be settled by the Members of the Secret Committee & therefore moved they might be appointed for that service, this Sir will be well Remembered by many Members of Congress. What Conversation passed between You & the Young Gentleman who called for the Books I really do not know. I authorized no such conversation on my part as you mentioned. That Young Gentn. when he recovered from Sickness went to the office to work at the Books, not finding 'em there he came to me. I knew nothing of them, but Mr. Brown informed him you had them, as I did not know your intentions, I told him I supposed you wou'd give them to him when you had done with them."],["p","With respect to the reasoning of your Piece I shall at present be Silent, if you are convinced of the justness of it you will abide by it, my own opinions govern me, and as you & I differ I will only tell you at this time, that I beleive your strictest search after deficiencies in the Committees or my Brothers Accounts will not answer your expectations, but if any such appear I will chearfully abide the Consequences shou'd Congress determine me to be answerable. When I have received that acquittal which I am confident of and placed in that light which I know myself to deserve, it will be time enough to speak of private Friendships. I have a better opinion of you than to believe you would prostitute that term by a Connexion with me whom you seem to consider as a dishonest Man.4"],["p","I am Sir with proper respect, Your most Obedt. & humble Servant,"],["p","Robt. Morris"],["p","RS. I return your piece herewith."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v12.0219":{"title":"Richard Henry Lee to Thomas Jefferson","author_label":"Richard Henry Lee","kind":"letter","date":"1779-03-15","date_label":"March 15, 1779","date_type":"written","recipient":"Thomas Jefferson","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 12","source_url":"https://archive.org/details/lettersofdelegat12smit","scan_url":"https://archive.org/details/lettersofdelegat12smit/page/197","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Jefferson Papers).","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee to Thomas Jefferson"],["p","Dear Sir, Philadelphia March 15, 1779"],["p","I have not been unmindful of the small commission you gave me to procure the song and receipt for you. I once had these, but they are mislaid so that I could not find them when I returned home from Williamsburg, or they should have been sent from thence. I have here applied to Mr. Peters for the one, and to Mrs. Shippen for the other and I have hopes of getting them both. I send you herewith a small pamphlet containing a collection of such papers and proceedings as clearly defeats the calumny of the British Commissioners charging this war to our ambition,1 when the Tyranny and avarice of the British Court most indubitably produced and has continued it."],["p","That our enemies will not get aid from any power in Europe to carry on the war against us is very certain, and the probability is great that Spain will speedily join in the war with France against England. Yet such is the temper of the British Court that it seems clear to me that nothing but the severest gripes of adversity and the last necessity can inspire wisdom and moderation. They certainly mean another campaign, a last effort; and"],["p","Georgia and South Carolina, with the frontiers and sea coasts appear to be their objects at present. Whether Gen. Clinton will take the field or not must depend on the succors he shall receive and the strength of our army. The flattering royal visits that are industriously made to the Nobility and gentry of England may possibly give such energy to the militia as to enable the sending a small reenforcement from their national troops to Gen. Clinton. With our present prospects every nerve should be strained to make our Army strong. By being prepared we shall have a moral certainty of defeating the designs of our enemies the next campaign, which will in my opinion put a glorious period to the war. I am, with much esteem and affection yours, Richard Henry Lee"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v12.0465":{"title":"Gouverneur Morris to Charles Pettit","author_label":"Gouverneur Morris","kind":"letter","date":"1779-05-01","date_label":"May 1, 1779","date_type":"written","recipient":"Charles Pettit","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 12","source_url":"https://archive.org/details/lettersofdelegat12smit","scan_url":"https://archive.org/details/lettersofdelegat12smit/page/414","text_status":"unreviewed_ocr","editorial_source_note":"Tr (PPAmP: Nathanael Greene Papers).","authors":["gouverneur-morris"],"paras":[["h","Gouverneur Morris to Charles Pettit"],["p","Sir Philadelphia 1st May 1779"],["p","Having considered your Application1 grounded on the Agents Letters from Charleston in answer I have to observe that as disputes between the publick Servants and the Government of the State they are in, must greatly prejudice the Service, it is my earnest desire that Harmony and a good Understanding may be cultivated between them in Carolina. I have no doubt but the President of that State had good reasons to detain the vessels mentioned in Mr. Livingstons Letters. The Demurrage becomes one of those unavoidable Circumstances which must be submitted to. All the Vessels should sail together about the latter end of this Month or the beginning of the next as shall be most proper. They ought to be ready by the 25th. If more are procured than are sufficient to bring away the Rice already ordered, let them nevertheless be loaded. They must in the first Instance clear out for the Capes of Delaware and there receive further"],["p","Instructions, either to come to this City or go to the Eastward. They ought therefore to be charter'd by the Month and the Property insured by the Publick. Having already written on this Subject to the Governor and to the Agent,2 submitting the latter entirely to the directions he might receive from the former, I am now to desire that you will urge a prompt obedience to the requisitions, and Directions which may be made upon or given to Mr Livingston."],["p","Enclosed you have Letters to the Governor and to the Agent which I pray you to forward."],["p","I am Sir, your most obedt & humle Servt, Gouvr. Morris."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v14.0488":{"title":"Samuel Huntington to Benjamin Lincoln","author_label":"Samuel Huntington","kind":"letter","date":"1780-02-14","date_label":"February 14, 1780","date_type":"written","recipient":"Benjamin Lincoln","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 14","source_url":"https://archive.org/details/lettersofdelegat14smit","scan_url":"https://archive.org/details/lettersofdelegat14smit/page/414","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 14).","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to Benjamin Lincoln"],["p","Sir, Philada Feby 14. 1780"],["p","You will receive herewith enclosed two Acts of Congress of the 1 1 & 12 Instant."],["p","The former among other things approving the plan adopted by the State of Georgia for reducing the four Regiments of that State into one, for officering the same, and also the Regiment of Cavalry; and resolving that such Officers as cannot be employed in the line of that State be deemed supernumeraries and entitled to every Privilege with Officers in like Situation."],["p","This Act of Congress so far as it differs from any former Act relative to the same Subject you may have received you will consider as superseding the former.1"],["p","By the other Act of the 12 Instant you will observe Congress have made provision for supplying the military Chest in your Department by such advances as the Governor and privy Council of the State of South Carolina shall be able to make for that purpose from [time] to time.2"],["p","1 have the honour to be, with much Esteem, your hble Servt."],["p","S.H."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v14.0538":{"title":"Samuel Huntington to Thomas Jefferson","author_label":"Samuel Huntington","kind":"letter","date":"1780-03-06","date_label":"March 6, 1780","date_type":"written","recipient":"Thomas Jefferson","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 14","source_url":"https://archive.org/details/lettersofdelegat14smit","scan_url":"https://archive.org/details/lettersofdelegat14smit/page/472","text_status":"unreviewed_ocr","editorial_source_note":"RC (Vi: Continental Congress Papers). In a clerical hand and signed by Huntington.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to Thomas Jefferson"],["p","Sir, Philadelphia March 6. 1780"],["p","You will receive Herewith enclosed an Act of Congress of this Day requesting the Governors of Virginia, North, & South Carolina, to use their utmost Exertions in filling up their Continental Battallions, and in the mean Time to raise a Body of Militia to supply the Places of the Battalions.1"],["p","From the Intelligence your Excellency must have received from the southern Department it is presumed the Necessity of reinforcing the Southern Army hath called forth the Exertions of Virginia and the more southern States."],["p","Your Excellency's Dispatches of the 9th ultimo has been received and laid before Congress.2"],["p","I have the honour to be with great respect your Excellency's hble servant, Sam. Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v15.0014":{"title":"Samuel Huntington to George Washington","author_label":"Samuel Huntington","kind":"letter","date":"1780-04-06","date_label":"April 6, 1780","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 15","source_url":"https://archive.org/details/lettersofdelegat15smit","scan_url":"https://archive.org/details/lettersofdelegat15smit/page/18","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Washington Papers). In a clerical hand and signed by Huntington.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to George Washington"],["p","Sir Philadelphia April 6. 1780"],["p","Your Excellency's favors of the 2d & 3d instant & 31st Ulto. have been duly received and laid before Congress.'"],["p","Herewith you will receive a Copy of an Act of the Senate and Assembly of New York of the 2d of March, together with an Act of Congress of the 4th Instant; by which you will be informed that Congress in Compliance with the Desire of that Legislature have approved of their raising a Body of Eight hundred Militia for the Defence of that State to be entitled to Continental Pay and Rations and employed under the Direction of the Commander in Chief of the Continental Army for that Purpose."],["p","By the Act of Congress of the 5th Instant herewith enclosd you will observe that they approve of the Measures taken by your Excellency to reinforce the southern Army.2"],["p","I have the honour to be, with the highest respect, your Excelly's hble servant, Sam. Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v15.0229":{"title":"Samuel Huntington to Meshech Weare","author_label":"Samuel Huntington","kind":"letter","date":"1780-06-04","date_label":"June 4, 1780","date_type":"written","recipient":"Meshech Weare","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 15","source_url":"https://archive.org/details/lettersofdelegat15smit","scan_url":"https://archive.org/details/lettersofdelegat15smit/page/245","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 15).","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to Meshech Weare"],["p","Sir Philadajune 3. 1780"],["p","By the Act of Congress of the 1st Instant herewith enclosed you will be informed, that the President & Council of the State of New Hampshire are authorized to embody 8c maintain at the Expence of the United States any Number of Men not exceeding two hundred 8c fifty Rank 8c file with a suitable Proportion of Officers to assist in guarding the Frontiers of that State.1"],["p","I have the honour to be &c &c &c, S.H."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v15.0251":{"title":"Samuel Huntington to the Committee at Headquarters","author_label":"Samuel Huntington","kind":"letter","date":"1780-06-06","date_label":"June 6, 1780","date_type":"written","recipient":"the Committee at Headquarters","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 15","source_url":"https://archive.org/details/lettersofdelegat15smit","scan_url":"https://archive.org/details/lettersofdelegat15smit/page/268","text_status":"unreviewed_ocr","editorial_source_note":"RC (DNA: PCC, item 39). In a clerical hand and signed by Huntington. 1 See/CC, 17:487-89; and Huntington to Certain States, June 5, note 2.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to the Committee at Headquarters"],["p","Sir, Philadelphia June 6, 1780"],["p","For your Information I have herewith enclosed a Copy of the report of a Committee appointed to receive the Communications from the Minister of France relating to Supplies &c, and the Resolution of Congress of the 5th Instant consequent thereon.1"],["p","I have the honour to be, with the highest Regard, Gentlemen, your most obedt and hbble servant, Sam Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v15.0364":{"title":"Samuel Huntington to George Washington","author_label":"Samuel Huntington","kind":"letter","date":"1780-06-25","date_label":"June 25, 1780","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 15","source_url":"https://archive.org/details/lettersofdelegat15smit","scan_url":"https://archive.org/details/lettersofdelegat15smit/page/374","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Washington Papers). In a clerical hand with signature and postscript by Huntington. LB (DNA: PCC, item 15). RC damaged; missing words supplied from LB.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to George Washington"],["p","Sir, Philadelphia June 25. 1780"],["p","I am now to lay before your Excellency an Act of Congress of the 21st Instant by which you will be informed of the further Measures they have taken to obtain the necessary Information from Time to Time how far they may rely upon the several States for furnishing their several Quotas of Men, Money & Provisions called for by Congress or their Committee at Head Quarters.1"],["p","Your Excellency will also receive herewith enclosed an Act of Congress of the 23d Instant, directing a Court of Enquiry as soon as Circumstances will admit respecting the Loss of Charlestown, and the Conduct of Major Genl Lincoln the late Commanding Officer in the southern Department; and the Proceedings of the Court of Enquiry to be laid before Congress.2"],["p","Also an Extract of a Letter from Genl. Lincoln of the 22d Instant relative to the Exchange of Prisoners, which is referred to your Excellency's Consideration.3"],["p","I have the Honour to be, with the highest Respect, your Excellency's humble servant, Sam. Huntington President"],["p","P.S. Your dispatches of the 20th & 25th instant have been duly receivd.4"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v15.0410":{"title":"William Churchill Houston to John Jay","author_label":"William Churchill Houston","kind":"letter","date":"1780-07-10","date_label":"July 10, 1780","date_type":"written","recipient":"John Jay","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 15","source_url":"https://archive.org/details/lettersofdelegat15smit","scan_url":"https://archive.org/details/lettersofdelegat15smit/page/419","text_status":"unreviewed_ocr","editorial_source_note":"RC (NNC: Jay Papers). Endorsed: \"Reed. 5 Octr.\"","authors":["william-churchill-houston"],"paras":[["h","William Churchill Houston to John Jay"],["p","Sir, Philada. 10 July 1780."],["p","The principal military Event which has happened this Spring, indeed since you left us, is the Fall of Charleston, the Capital of South Carolina. No Circumstance very material can be added to the Account officially published, and which you have had from the Papers transmitted already and repeated by this Conveyance. It will, I hope be excused in us, that you will probably see this in the European Papers before it reaches you from this City: our Intelligence being over-land, is tedious in it's Passage; add to this that the Enemy after the Capitulation, interposed every Means by dilatory and frivolous Pretences, by what Candour will probably decide to be a Breach of the Spirit of their Engagements, to delay the Dispatches General Lincoln had stipulated should be forwarded immediately to Con-"],["p","gress. This you will readily believe when you compare the Date of the Surrender of the Town with that of the Arrival of Lieut Colonel Ternant at Philadelphia, and are advised withal that he met with no Obstruction on the Way. General Lincoln with his Family has since arrived.1"],["p","We have daily Accounts from the Southward that the Enemy pay no regard to the Stipulations pledged in Favour of the Citizens. Rapines, Violences, Devastations and Abuses of every Kind are comitted without reserve. You recollect their Conduct in New Jersey in the year 1776 and 7; it is similar in this Case, though they are under Terms. The Issue too may be like; they have overrun a considerable Part of the State in the Hour of its Nakedness and Debility, but as General Gates is assembling a Force against them, and their Measures seem as usual to be dictated by Infatuation, Impolicy and Ignorance, when they have wrought up the the Spirits of the People to Fury and Desperation they will be expelled from the Country."],["p","It seems to be the Ordination of Providence, and, though the Sufferings are severe, the Interest of the States, that each should have a Share of this Kind of Calamity. It is clear and undisputed Experience that in those States where for a Time they have made Progress, and from whence they have been driven with Arms, or retired with Disappointment and Disgrace, the Flame of Liberty and Patriotism burns with double Strength and Brightness, and the Exertions of the People are greater and more deciding. The Militia of New Jersey and New- York, whose Vengeance against Great Britian Ages will not be able to eradicate, have in several late Instances fought them with the most desperate internecine Furry. We have Not heard of such a Thing to the Southward as yet, but may in due Time."],["p","Every Person who has attended to the Course of our Revolution will know the Meaning of what seems a Paradox, 'that our Misfortunes are our Safety.' They are certainly, under GOD, the Source of it. Our Captive Soldiers will as usual be prisoned, starved and insulted, will be scourged into the Service of the Enemy; the Citizens will suffer Pillagings, Violences and Conflagrations; a fruitful Country will be desolated; but the Loss of Charleston will to all Appearance promote the general Cause. It has awaked a Spirit unknown since the Year 1776; a Spirit which is fast pervading the Mass of the Community; a Spirit which enlivens and encreases daily. I am more afraid of an unfavourable Effect of this Disaster on your Side of the Water, and hope you will take the proper Means for preventing any ill Impressions it might otherwise have."],["p","The Enemy have brought back more than Half their [troops] from the Southward. Cornwallis commands with between four and five Thousand Men. At this Date they are at Kingsbridge and some miles above."],["p","Governour Livingston and Family were well four Days ago."],["p","I am, Sir your obedt hble Servant, Willm Ch Houston"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v15.0448":{"title":"William Churchill Houston to Joseph Ward","author_label":"William Churchill Houston","kind":"letter","date":"1780-07-17","date_label":"July 17, 1780","date_type":"written","recipient":"Joseph Ward","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 15","source_url":"https://archive.org/details/lettersofdelegat15smit","scan_url":"https://archive.org/details/lettersofdelegat15smit/page/456","text_status":"unreviewed_ocr","editorial_source_note":"RC (ICHi: Ward Papers).","authors":["william-churchill-houston"],"paras":[["h","William Churchill Houston to Joseph Ward"],["p","Dear Sir, Philadelphia 17 July 1780"],["p","On the 18th ult I received yours of the 5th and this Day yours of the 29th for both which please to accept my Thanks. We have a Dawning of the Arrival of the French Fleet at Rhode-Island, said to have happened on the 10th inst. and we believe the Intelligence. The Occasion is great and solemn, and every Exertion will now be necessary to press the Preparations. Every Person of whatever rank or Abilities may now find full Employment. I think it to be regretted we are in no better Forwardness to enter fully and effectively into the Cooperation. The Spirits of the People are however up in this Quarter, and that being the Case I am well aware that such is the Case with you for you are never behind, almost always before us."],["p","I am just on the Point of setting out for New Jersey, and expect to be some Time absent from Congress.1 Have paid due Attention to your generous Willingness to be again in active Service, and have had a Conversation with Mr. Adams. Hope an Occasion will offer, and as far as I may have any Voice or Influence will ever wish to put Opportunities into the Power of such as are deserving and disposed to render Service to their Country."],["p","We have no Intilligence from the Southward very lately, but believe the Enemy's Career is checked there, and hope a proper Countenance will be held up against them in that Quarter till Things are in a Situation to give them a Push."],["p","In great Haste, I am with much Respect, your obedt hble Servant, Wm Churchill Houston"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0342":{"title":"Samuel Huntington to George Washington","author_label":"Samuel Huntington","kind":"letter","date":"1780-12-04","date_label":"December 4, 1780","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/411","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Washington Papers). In a clerical hand and signed by Huntington.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to George Washington"],["p","Sir, Philadelphia December 4. 1780"],["p","Your Excellency will receive herewith enclosed, the Copy of an Act of Congress of the 30th Ulto respecting the Department of the Commissary General."],["p","I am informed by Letter from Govr Jefferson that the Brittish have all reimbarked and left, the Chesapeake.1"],["p","By Dunlaps Paper enclosed you will be informed of the Success of the Corps under Genl Sumpter against Majr Wemyss.2"],["p","I have also to acknowledge the receipt of your Despatches of the 28th Ulto.3"],["p","I have the Honor to be, with Sentiments of the highest respect & Esteem, your Excellency's most obedient & most humble Servant,"],["p","Sam. Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0373":{"title":"Samuel Huntington to John Laurens","author_label":"Samuel Huntington","kind":"letter","date":"1780-12-14","date_label":"December 14, 1780","date_type":"written","recipient":"John Laurens","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/443","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 15)","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to John Laurens"],["p","Sir, Philada December 14. 1780"],["p","I have the Pleasure to transmit you the enclosed Copy of an Act"],["p","of Congress by which you will be informed they have been pleased"],["p","unanimously to elect you an Envoy Extraordinary, to repair to the"],["p","Court of Versailes.1"],["p","I am Sir &c &c &c, S.H."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0398":{"title":"Samuel Adams to John Adams","author_label":"Samuel Adams","kind":"letter","date":"1780-12","date_label":"December 1780","date_type":"written","recipient":"John Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/470","text_status":"unreviewed_ocr","editorial_source_note":"FC (NN: Adams Papers). In the hand of Samuel Adams.","authors":["samuel-adams"],"paras":[["h","Samuel Adams to John Adams"],["p","My dear Sir. Philadelphia Deer. 20 1780"],["p","Mr. Palfrey is just embarking, so I have only a few Moments to inform you, that I have this Morning been conversing with an old Man and an old Whig, who has all his Days been an Inhabitant of South Carolina & Georgia.1 He was taken Prisoner last Summer & carried to New York, from whence he lately came to this Place. And though his Fortune would enable him to live here at Ease, he thinks he can be useful to America by returning to that Part of it, and at the Age of 73 [has] undertaken the long Journey. He has always mixed with the People of those States, & is well acquainted with their Temper & Sentiments. He also has been much among the Indians & is greatly beloved by them. This Account I have had of him often from the Delegates of Georgia & others whom I can confide in. The"],["p","old Gentleman tells me that the People of those States are in general firmly attachd to the American Cause, & most fervently deprecate their being finally seperated from the United States. His Soul was refreshd to hear me say that I did not apprehend any Danger of it — that the Idea would, in my Opinion, be abominated by the Eastern States, and, as far as I could judge, by all the rest. He says, that the Creeks & the Chictaws, which are the most numerous tribes of Indians, consisting of at least 8 perhaps 10 thousand gunmen, are our staunch Friends. The Heads of them have lately spoken to him in this Language, \"We stand [on] the same Ground with you, we drink the same Water & breathe the same Air, we are the Trees, you are the Buds, & can there be Fruit if the Buds are nipped off.\" These are forceable Words, which express their own Sense of the Necessity of their Union with us for their very Existence. They are a sagacious as well as a powerfull People, & an Alliance & Friendship with them is of Importance to all the United States. The People, of whatever Nation, who shall possess Georgia & South Carolina, will be the Leaves of their Trees. It is my Opinion, that even a Thought of leaving the Inhabitants of those States to be subject to any foreign Power, who so gallantly defended themselves in the Begining of this Contest, & have lately sufferd so much for the Sake of American Liberty, would not only be unjust to them, but in a high Degree impolitick."],["p","In every View we see the Necessity of a sufficient Naval Force. A few Ships of War at the Bar of Charles town, & a Frigate or two in Stono River, might at this time effect the Recovery of that City. I need not inform you, what an Effect the Sight of a Sixty Gun Ship would probably have at Penobscott. Do not our Enemies conceive the Idea of Uti possidetis? And Can there be Peace in America while Britain holds a Foot of Ground in any Part of it?"],["p","Adieu, S A"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0509":{"title":"James Madison to Nathanael Greene","author_label":"James Madison","kind":"letter","date":"1781-01-13","date_label":"January 13, 1781","date_type":"written","recipient":"Nathanael Greene","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/594","text_status":"unreviewed_ocr","editorial_source_note":"Reprinted from Madison, Papers (Hutchinson), 2:283-84, from an extract printed in Stan V. Henkels Catalogue, no. 988 (1909).","authors":["james-madison"],"paras":[["h","James Madison to Nathanael Greene"],["p","Jan. 13, 1781 I1 enclose you an extract of a letter from General Washington of the 2d instant,2 giving a more precise account of the embarkation from New York on the 20th ulto. than has been before obtained. On the night of the 1st instant a mutinous spirit which had been for some time working in the Pennsylvania Line of the Army broke out with such violence that the utmost efforts of the Officers were insufficient to suppress it. Two of them unhappily fell victims to the fury of the Mutineers, after completely shaking of[f] all military authority they proceeded in an entire body and in regular order to Princeton with an intention as they gave out to come on to this city"],["p","and with a determination neither to lay down their arms nor return to their obedience until their grievances should be redressed. These consisted principally in the detention of many in service beyond the term of enlistment, and the sufferings of all from deficient supplies of cloathing and provisions, and the long arrearage of pay, contrary to their first plan they declined coming to this place and established their encampment at Princeton, where they entered into negotiations with Genl. Wayne, Lt. Cols. Stuart & Butler (the only officers they suffered to remain among them and whom they kept under close confinement, although in every other respect they treated them with the utmost decorum) on the subject of redress. The nature of some of their demands and the manner of their proceeding gave at length a very serious countenance to the affairs, and as the proximity of Princeton to a place of junction with the Enemy was surmised to be the probable motive of their stopping at that place, as it was confidendy alleged that the Enemy were coming out in force to avail themselves of the event, and as many of the troops were foreigners & not a few deserters from the British Army it was thought best to appoint a Committee with full powers to take the necessary steps for quieting the disturbance as speedily as possible. In consequence of the appointment the Committee judged it advisable to proceed immediately to meet the Troops. The President of the State with several other Gentlemen from this place had set out for the same purpose a litde time before then. The information since received both from the forces & the latter is, that the President had met with a confidential reception from the troops, that they had given up to him & Genl. Wayne, an emissary and guide from Clinton with a flattering invitation to them to take sanctuary from their miseries & the resentment of those who had usurped the public authority, under the British Government, that they had been prevailed on to come forward as far as Trenton where an accommodation of principles of equity was pretty far advanced & in a sure train of being soon completed, & that the emissary & guide were under sentence of death, and would be executed yesterday morning."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0618":{"title":"James Madison to Edmund Pendleton","author_label":"James Madison","kind":"letter","date":"1781-02-13","date_label":"February 13, 1781","date_type":"written","recipient":"Edmund Pendleton","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/709","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Madison Papers). Endorsed by Pendleton: \"James Maddison Esq Feb. 13. 1781.\" Madison, Papers (Hutchinson), 2:311.","authors":["james-madison"],"paras":[["h","James Madison to Edmund Pendleton"],["p","Dear Sir Philada. Feby. [13]1 1781"],["p","I have your favor the 5th instant by the post.2 Col. Harrison arrived here yesterday,3 and as he mentions no circumstance which indicated an intended departure of the Enemy, I am afraid your intelligence on that subject was not well founded. Immediately on the receipt of your former letter relating to an exchange of C . Taylor4 I applied to the Admiralty department, and if such a step can be brought about with propriety, I hope he will be gratified, but considering the tenor of their treatment of naval prisoners, and the resolutions with which it has inspired Congress, I do not think it probable that exchanges will go on easily, and if this were less the case, a mere passenger under the indulgence too of a parole, can scarcly hope to be preferred to such as are suffering the utmost hardships and were made prisoners in public service."],["p","A vessel arrived here a few days ago from Cadiz which brings letters of as late date as the last of Deer. Those that are official tell us that England is making the most strenuous exertions for the current year, & that she is likely to be but too successful in the great article of money. The Parliament have voted 92000 seamen, and a considerable land reinforcement for their Southern Army in America is also sd. to be in preparation. Private letters by the same conveyance mention that the blockage of Gibralter is going on with alacrity, and that the garrison is in such distress as flatters the hope of a speedy capitulation."],["p","If Mr. Pendleton your nephew5 is still with you be pleased to return him my compliments. With great respect I am, Dr Sr, Yr. Obt. servant, J. Madison Junr."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0665":{"title":"Samuel Adams to Caleb Davis","author_label":"Samuel Adams","kind":"letter","date":"1781-02-28","date_label":"February 28, 1781","date_type":"written","recipient":"Caleb Davis","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/752","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi: Davis Papers).","authors":["samuel-adams"],"paras":[["h","Samuel Adams to Caleb Davis"],["p","Dear Sir, Philade Feb 28 1781"],["p","A Gentleman of the State of Pennsylvania is desirous of importing a small Quantity of Flax Seed from Massachusetts to put into his own Ground, (a Barril might be sufficient) and has engagd me to apply to a Friend in Boston to procure it. If you could send a Barril, by a Vessel that may sail soon for this place, you will much oblige him & me. He will satisfy you for the Expence. Direct your Letter to Henry Wynkoop Esqr of Bucks County, Pennsylvania, to the Care of any one of the Massachusetts Delegates who may then be here. I mention this, because I expect to be at Boston early in the Spring. You will excuse my giving you this Trouble and be assured that I am affectionately, your Friend, S Adams"],["p","[P.S. ] Be so good as to let Mrs A know that I am well."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v17.0426":{"title":"Daniel of St. Thomas Jenifer to John Hall","author_label":"Daniel of St. Thomas Jenifer","kind":"letter","date":"1781-07-24","date_label":"July 24, 1781","date_type":"written","recipient":"John Hall","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 17","source_url":"https://archive.org/details/lettersofdelegat17smit","scan_url":"https://archive.org/details/lettersofdelegat17smit/page/435","text_status":"unreviewed_ocr","editorial_source_note":"RC (MiU-C: Sir Henry Clinton Papers). An intercepted letter.","authors":["daniel-of-st-thomas-jenifer"],"paras":[["h","Daniel of St. Thomas Jenifer to John Hall"],["p","My dear Sir, Phila. July 24th. 1781"],["p","The last accounts from Genl. Green were that he was obliged to raise the Siege of 96, but expected to come to some action with Lord Rawdon. General Mou'trie who left Charles Town about the 8th Inst, informs that it was reported that Lord Rawdon had retreated from 96 to Orangeburg about 80 Miles from Charles Town and that General Greene had reinvested it."],["p","The last information from the Marquis mentions an action between a part of our Troops & Cornwallis near Wmsburg, the consequence of which was, that Cornwallis crossed James River, and it is generally conjectured here that he intends to Portsmouth, leave a proper Garrison there & then divide the rest of his Troops for New York & S Caro. We lost in killed, wounded and missing about 140, many of our Officers wounded, none killed, a Lieutt. Coll. of the Jerseys taken prisoner. The Marquis says that the British lost many more, but had concealed their Dead. I am afraid that our Execution in this engagement was not great. What prowess Genl. Washington will make against New York God only knows; I confess that my expectations are but small. It is said that two British Ships of the Line, and seven Transports are gone up North River; if this be true it is done to draw the General back towards Westpoint. Mr. Clagget now in Phila. informs me, that there will be great Canvassing for the Electors who are to elect the Senate in Sepr. and that the Landed interest are alarmed by the late Publications against the Members of that body,1 and that he and Mr. Crawford had offered themselves for the purpose to the people of Prince George's. I wish that the same Spirit may prevail throughout all the Counties, for the safety and happiness of the State depends greatly on the choice to be made at the next Election of Senators. I make not the least doubt but SC2 whom it is probable will be the Elector for Annaps. will do every thing in his power to turn out most of the present Members, and to get in as many of his friends as he can; therefore it is the business of every friend to the Constitution to do every thing in his power to circumvent him. He has lately met with a mortification from Mr Sharpe Delegate from N.C. who has forbid him any further Correspondence with him. SC has wrote in Answer a most humiliating"],["p","Letter indeed but I believe Mr Sharpe will be inflexible but this between ourselves. We have had no late accounts from Europe. Attempts have been made by the Generals Clinton & Haldimand to seduce the people of Vermont 8c I fear not without some success; if we do not soon make them independant the British will endeavor to do it. Ned Rutledge, Middleton & Gadsden with many others exchanged are dayly expected from Augustine."],["p","Our great Estate as you call it remains in the same situation as it did before the confederation, indeed I think in a much worse. The adoption of that measure after holding out so long will I fear be productive of many ill, but not one good consequence to our State, nor do I believe that our Ally ever hinted to his Minister that the succession of Maryland was a desirable event with him. I wish our Troops were in motion for some place or other, they must distress the inhabitants near them."],["p","This moment I am informed that R. H. Lee has wrote to a Gentn. in Town that Cornwallis was Marching towards the Carolina's. I am not sorry for it, He must lose many of his men should this intelligence prove true. With my respectful Compliments to Mrs. Hall,"],["p","I am Dear Sir, Your affectte. friend & Servt."],["p","Daniel of St Thos Jenifer3"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v17.0438":{"title":"Thomas McKean to George Washington","author_label":"Thomas McKean","kind":"letter","date":"1781-07-26","date_label":"July 26, 1781","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 17","source_url":"https://archive.org/details/lettersofdelegat17smit","scan_url":"https://archive.org/details/lettersofdelegat17smit/page/449","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Washington Papers). In a clerical hand and signed by McKean.","authors":["thomas-mckean"],"paras":[["h","Thomas McKean to George Washington"],["p","Sir, In Congress July 26th. 1781."],["p","I have the Honor to inclose your Excellency the Copy of a Letter from the Marquis de la Fayette to Major General Greene dated the 1st Instant, and also Copies of several Letters between General Lord Cornwallis & the Marquis respecting Prisoners.1"],["p","These Papers having been just now read in Congress, I send them on to your Excellency by Express, that you may have the earliest Information possible of the Situation of the British Army in Virginia."],["p","My private Conjecture is, that after leaving a strong Garrison at Portsmouth, Lord Cornwallis intends to proceed with the rest of his Army to New York, excepting perhaps his Cavalry, which may probably be sent to Charlestown, as they could not be of so great Benefit at New York as there."],["p","If the Count de Barras could intercept his Lordship on his return to New York, it would be a glorious Enterprize. I wish it was attempted."],["p","I shall not detain the Express on Account of any other Communications at present, and shall therefore subscribe myself, with the utmost Regard, Your Excellency's Most obedient & most humble Servant, Tho M:Kean President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v18.0113":{"title":"Abraham Clark to James Caldwell","author_label":"Abraham Clark","kind":"letter","date":"1781-10-03","date_label":"October 3, 1781","date_type":"written","recipient":"James Caldwell","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 18","source_url":"https://archive.org/details/lettersofdelegat18smit","scan_url":"https://archive.org/details/lettersofdelegat18smit/page/110","text_status":"unreviewed_ocr","editorial_source_note":"RC (PHC: Roberts Collection).","authors":["abraham-clark"],"paras":[["h","Abraham Clark to James Caldwell"],["p","Dear Sir, Philada. Octor. 3d. 1781."],["p","Your favour of the 1st inst. I reed, in answer to which I can inform you that many reasons will prevent my Acceptance of the Office you mention, I am Certain I cannot Accept without giving offence. Weighty reasons induce me to decline a seat in the Legislature, in this I am clearly determined should I be put in Nomination at the Ensuing Electing, justice to the County will Oblige you to make this my resolution known to prevent the expense of a New Election. You know I cannot take a seat in the Legislature while I hold one in Congress, and this I shall avail my self of by Continuing my present Standing untill the end of my Delegation, which will Necessarily Vacate my Election should I be chosen, as I must resign here at the meeting of the Houses in order to entitle me to a seat, by omitting this my Election would be Vacated of Course 8c a new Writ be ordered — from this my determination you will take measures at the ensuing Election for the choice of such as can & will serve; My present situation will excuse me without the Necessity of saying / will not.1 I question whether you can offer reasons equal with mine for declining, and therefore need not wait for my example to stimulate you to do what you hold forth as a duty for me to comply with — very bad Divinity to call upon me for Example, I must confess were I to serve I should be happy in your assistance."],["p","As to your late discovery of the Spirit of Confederation, I can scarcely say any thing about, without incurring Censure as being Interested; I must therefore remind you that it is well known Attendance in Congress hath long been a painful service to me, and I feel a strong desire to be free from it. My self therefore out the question, I cannot but reflect upon our situation should you Act as you propose unless I am mistaken in some facts; If I am rightly informed Dr. Witherspoon, Mr. Houston, Dr. Elmer &: myself have served three Years, & that Dr. Scudder, Mr. Boudinot, Dr. Henderson & Colo. Freilinghuysen will decline if Chosen, if this is the Case shall We have New Members that know any thing of the Business of Congress, while Many if not all of the Other states whose Constitutions Admit of it send some of their old members without regard to the time they have served, judging that the Confedration cannot"],["p","and Ought not to have any Operation before its final ratification; indeed, it never was made a Rule to govern Congress before that period. The Limitation is in general useful but then it ought to be a rule equally regarded by all or none, or those who do not confine themselves by it will have a manifest Advantage over the Others who are not prepared to Act agreable to the Spirit of it. The present situation of our publick affairs requires the assistance of such as have a thorough knowledge in the business before Congress. The only proper System for the Choice of members, in my opinion, is to Elect only three Members Annually two of which Acquainted with the business, one of the old ones to go out at every Choice to make room for a New one, by this measure there will always be two that had served before. The three Chosen should be such as agree to Attend except prevented by sickness — the Choice of five members will only incapacitate a greater Number after three years service without giving better Attendance."],["p","We have Accounts, tho not official, but such as seem not to Admit of a doubt that a severe battle was fought near Charles Town on the 8th Ulto, in which we had upwards of two hundred killed and Wounded, and the Enemy lost in killed, wounded 8c taken between Six and Nine hundred, and when the Accounts came away our forces were in pursuit of the Enemy who were on a precipitate retreat; Colo. Lee 8c Marian with their Corps were not in the Action, but had got near the Enemy in their retreat 8c it was expected would soon come up with them with their fresh troops — the Enemy had no horse — during the Action Our horse was intirely surrounded, Colo. Washington wounded but not Mortally, taken prisoner 8c after four hours with the Enemy retaken, All his officers except one Lieut, were either killed or Wounded; All Accounts agree that the Action was very bloody, and that we Obtained a compleat Victory — the Acct. is brought by a Delegate from North Carolina who saw Letters from officers in the Action. Governor Burke of North Carolina was lately taken 8c Carried of[f] by the tories. I am, Dr Sir, Most sincerely yours, Abra. Clark"],["p","[PS.] Please to forward the enclosed.2"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v18.0138":{"title":"Thomas McKean to George Washington","author_label":"Thomas McKean","kind":"letter","date":"1781-10-14","date_label":"October 14, 1781","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 18","source_url":"https://archive.org/details/lettersofdelegat18smit","scan_url":"https://archive.org/details/lettersofdelegat18smit/page/132","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Washington Papers). In a clerical hand and signed by McKean.","authors":["thomas-mckean"],"paras":[["h","Thomas McKean to George Washington"],["p","Sir, (Private) Philadelphia, October 14th. 1781. 8 oClock. P.M."],["p","My two last letters must, I know from your opinion of my character, have spread the wings of your expectation. My intelligence was true; the inclosed copies of two original letters from Sir Henry Clinton to Lord Cornwallis, which I have in cyphers, and which have been faithfully decyphered by Mr Lovell (whose key I had the honor to forward to you about a fortnight ago) more than prove the fact.1"],["p","I shall make no comment on the letters of Sir Henry, lest I should wade beyond my depth, but I rest assured you will excuse what I think it a duty to add. From comparing all my secret informations together, I firmly believe the British Admiral has now twenty nine ships of the line, and a very respectable number of Frigates; which, with ten fire-Ships, have probably sailed yesterday for the Chesa-"],["p","peake, having on board between five & six thousand Land forces. As to the three additional ships, they are supposed to have come from the west Indies, and are said to have arrived the beginning of last week. Sir Henry expected to be ready to sail on the 5th instant, I am greatly deceived if he sailed before Friday, for I have had faithful Friends to myself, as well as to the cause, who left the Sea-coast yesterday, some distance, 'tis true, from the Hook to the Southward, who know nothing of it; and if he had sailed before Friday, I believe they would have known it — These are the Gentlemen who brought me Sir Henry's dispatches. Among the letters (all being carefully inclosed in lead) I have found some, that will enable me to prevent some men of Sussex County in the State I have the honor to represent, from doing us much mischief, and perhaps they may enable me to make further discoveries: they have little relation to your immediate concerns, and therefore I shall not trouble you with the contents, except that intelligence is intended to be conveyed to & from Lord Cornwallis by way of the Tanjier Islands in the Chesapeake near the Eastern shore. I never heard of them before, and not having time to satisfy myself where they lie, must refer it to your enquiry."],["p","It is far from my thoughts to intermeddle in the operations of the campaign, but I know you will pardon me for suggesting to Major General Heath, that after Sir Henry Clinton sails, it is my opinion there will not be above Four thousand land forces left in New-York and it's environs, of whom there cannot be above a thousand regulars, and that therefore it may be adviseable for him to be in readiness to attack it, if he should be so directed by you. Should you, Sir, think this practicable, or adviseable, there will, in less than a fortnight after I shall have information of it, be five thousand militia to co-operate with him."],["p","The use that may be made of the three large smoaks, if you shall have succeeded against Lord Cornwallis, will readily suggest itself, to you, and if not, the knowledge of it may prove advantageous."],["p","I am, Sir, with the most perfect esteem, Your Excellency's Most obedient Servant, Tho M:Kean"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v18.0399":{"title":"William Ellery to Joseph Clarke","author_label":"William Ellery","kind":"letter","date":"1782-03-17","date_label":"March 17, 1782","date_type":"written","recipient":"Joseph Clarke","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 18","source_url":"https://archive.org/details/lettersofdelegat18smit","scan_url":"https://archive.org/details/lettersofdelegat18smit/page/400","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Continental Congress Miscellany).","authors":["william-ellery"],"paras":[["h","William Ellery to Joseph Clarke"],["p","Dr. Sir, Phil. March 17th. 1782."],["p","Immediately upon the receipt of your letter inclosing Genl. Roberdeau's certificate and bills, he wrote you a letter acknowledging the receipt thereof; and upon the same sheet I gave you a line referring thereto,1 and assuring you that I would do every thing in my power to procure the payment of your loan-office account &c, &c. I accordingly made an extract from your letter of that part which respected that matter, and laid it before the Committee of the week, but finding they would report that it should lay on the table, I took it back, and laid it before the Superintendant of Finance; who told me that he would write to you on the subject of it.2 Whether any addition will be made to the pay of the Keepers of the Loan-offices I cannot determine; but as it is the design of the Superintendant of Finance that those appointments should be abolished as soon as it can be done with propriety, I believe none will be made. You will most certainly be paid what is due and may become due to you from the public; but perhaps not so soon as you may wish. I think I may congratulate you on the surrendry of Brimstone Hill and the complete reduction of St Kitts, Nevis & Montserrat; which you will see an account in the News paper.3 You will also see there an account of the disaster of the Brest Fleet, which obliged them to return to Port; whereby every advantage that might have been derived from their having a month's start of Admiral Rodney is lost. However it is a very happy circumstance that the Duke De Bouille should have taken the places beforementioned, before the arrival of Admiral Rodney. You will likewise particularly take notice of the change in the British Ministry. What will be the issue of this change I cannot"],["p","pretend to predict; nor dare I hazard an opinion upon it, not having had time to make up my mind on the subject. It seems by the speeches of Lds North 8c Germain that the mode of conducting the war was to be changed; but whether that will be the sentiment of the present ministry you can determine as well as I. I rather think that they will strengthen their post at Newyork for the reasons assigned in those speeches; and, instead of exposing whole armies to be conquer'd as they have done by carrying on an internal war, secure that post and Charlestown if they can, that they may have something to make peace with; and employ their naval, and what land force they may have to spare in recovering the islands they have lost, protecting those which may be in danger; while at the same time their cruising ships will be employed upon our trade. Much depends upon our allies preserving their naval superiority; and I think we have something to apprehend from Lord Howes being at the head of the Admiralty. His skill and abilities in naval affairs I believe are great, and 1 don't doubt they will be exerted to the utmost, to increase the strength of the British and lessen that of the French 8c Spanish Navies. The fort of our enemies used to be and is in their navy. While the combined fleets preserve their superiority we have nothing to fear; if that should be lost we shall have reason to be concerned. The war will I believe be carried on principally upon the water hereafter. While our allies and foes are contending for victory on the ocean, it will be our duty to be active on land. At all events we ought to be early and thoroughly prepared to embrace every opportunity which may offer to make an impression on the enemies strong holds."],["p","Congress have reed, letters from Mr. Dana giving an account of his journey to, arrival at St Petersburg &c. His last letter was dated about the middle of September.4 I shall keep this letter open and if any thing new should occur before the post goes out I will give it to you. Give my love to your wife & children and accept of my best wishes for your 8c their prosperity. Yrs W.E."],["p","[P.S.] I find that the account of a change in the British Ministry is rather premature: But it is said that Ld Sandwich had resigned and that Lord Howe had taken his seat at the Admiralty. I have seen the capitulation of Brimstone Hill. W. E."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v18.0430":{"title":"James Madison to James Madison, Sr.","author_label":"James Madison","kind":"letter","date":"1782-03-30","date_label":"March 30, 1782","date_type":"written","recipient":"James Madison, Sr.","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 18","source_url":"https://archive.org/details/lettersofdelegat18smit","scan_url":"https://archive.org/details/lettersofdelegat18smit/page/431","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Madison Papers). Madison, Papers, (Hutchinson), 4:126-27.","authors":["james-madison"],"paras":[["p","James Madison to James Madison, Sr."],["p","Hond Sir Philada. March 30th 1782"],["p","Mr. J. Walker has safely delivered to me three letters from you attended with the money therein specified. He has also been so obliging as to undertake the conveyance of the several articles of Medicine you wanted with a gallon keg filled with good Port wine; to all which I add a large packet of Newspapers — and an Almanack. The last packet I sent was by a waggon returning to your neighbourhood which brought me a letter from Mr. W. Maury; By which I sent at the same time a small supply of Bark for my Mother."],["p","I mentioned to you in one of my former letters that I had a prospect of getting on very favorable terms a few scarce books from a library brought hither for sale by Col. Zane.1 My purchases of him have amounted in the whole to Nineteen pounds three shillings of this currency.2 As I had not the money here for him, 8c he could not conveniently wait till it would be convenient for me to pay him, I was obliged to give him a draught on you. I hope you will be able to find means to satisfy it. If it can not be otherwise done than by a deduction from the further supply you have in contemplation for me I must submit to it. How far I shall depend on you for the resources necessary for my expences here not included in the legal provision, and for the arrearages into which I have unavoidably fallen, will be known as soon as the Assembly have finally decided on our accounts & the allowance which is to be made to us. This I suppose will be done at their Session in May next. Unless liberal principles prevail on the occasion, I shall be under the necessity of selling a negro."],["p","I have not time to provide for this opportunity the information relative to the Copper plates."],["p","The newspapers give you in general the intelligence we have from Europe. As far as we are enabled to Judge of the views of the British Cabinet, the misfortunes of one more campaign at least will be necessary to conquer their obstinacy. They are attempting a separate peace with the Dutch & talk of suspending their offensive war agst. us, 8c directing their whole resources agst. the naval power of France &: Spain. If this be their real plan we may be sure they do not mean by it to abandon their pretensions to the U. States but try another mode for recovering them. During their offensive exertions agst. our Ally, they can be practising insidious ones agst us, and if in the first they should be successful, & in the latter disappointed, a renewal of a vigorous war upon us will certainly take place. The best"],["p","security agst. every artifice 8c every event will be such military preparation on our part as will be sufficient either to resist or expell them as the case may require."],["p","With my affectionate regards for the family, I am Kind Sir Yr. dutiful son, J. Madison Jr."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v19.0312":{"title":"Abraham Clark to Benjamin Lincoln","author_label":"Abraham Clark","kind":"letter","date":"1782-12","date_label":"December 1782","date_type":"written","recipient":"Benjamin Lincoln","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 19","source_url":"https://archive.org/details/lettersofdelegat19smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (DNA: RG 93). Addressed: \"Honble Secretary at War.\"","authors":["abraham-clark"],"paras":[["h","Abraham Clark to Benjamin Lincoln"],["p","Sir, Deer. 3d. 1782."],["p","In Answer to your favour of the 30th Ulto. with a Copy of the Charges exhibited Against the late Commsy. of Military stores,1 I must inform you, that the first Charge is to be proved by William Thorne paymaster of the department, and by receipts now or of late in his possession, if not at present with him, he can inform where they may be found. Mr Thorne can also inform respecting the mode of payments made to some of the Officers 8c others having demands upon the department, that after orders were given for payment, the Commissary restrained such payment unless upon his Special Order after wards given, thereby making partial payments to the great injury of those deprived of their pay."],["p","The second Charge respects the Commissarys calling from Massachusets Mr. Hay to Command the Company from which Mr. Godfrey was discharged by the Act of Congress of the 30th of August 1 780 As An Unnecessary Officer, founded on a report of the board of War of the 26 of the same month. A Copy of the report Accompanies this. Boyer a Clerk in the department, as also Mr Hay himself may be called upon to inform the manner of Mr. Hays coming to the Command. I well remember that at the time of dismissing Godfrey the members from the board of War attending Congress, declared that his removal was not to give place to any other, but purely as an Office unnecessary agreable to a resolution of Congress of the 12th of August, and it cannot be Supposed that the board of War intended to deceive Congress."],["p","The third Charge relates to the Commsys. removing from his trust and employ Major Jonathan Gostelowe by his own Authority, placing one of his Clerks in the Military store. The Letters of removal were put into the hands of a Committee of Congress where it is supposed they yet remain. No Order of the board of War hath appeared or was mentioned in the Letters, to justifie such a procedure, Nor does even the board of War Appear to have such a power without reporting to and Obtaining the Concurrence of Congress; this appears to have been their sense respecting their powers as expressed in their report of the 26th of August Accompanying this, for it is Observable that Charles Lukens and Jona. Gostelowe were both Appointed at the same time on the 11th of Novr. 1777 and both under Similar Circumstances as to their appointments, the former of which the board did not think themselves impowered to remove. Gostelowe can be called to Witness"],["p","as to his dismission, the Letters being as is said out of Town. Mr. Boyer also may know something of this matter."],["p","The fourth Charge, intended to be proved principally by Capt. Jordan who is now absent. Jona Gostelowe, Moses Gistland a late Clerk to the Commissary, Mr. McFee a late Conductor, can be called to testifie on this head. Mr. Boyer may also know something of this business and produce the books, where, I am told, it will appear that the Commissary and the Officers about him received their pay, while others were deprived of it; the Commissarys receiving more than his pay will appear by the rects. under the first Charge."],["p","I am, Sir, Your Obedt. Humble Servt. Abra. Clark"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v19.0339":{"title":"James Madison's Notes of Debates","author_label":"James Madison","kind":"notes","date":"1782-12-10","date_label":"December 10, 1782","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 19","source_url":"https://archive.org/details/lettersofdelegat19smit","scan_url":"https://archive.org/details/lettersofdelegat19smit/page/471","text_status":"unreviewed_ocr","editorial_source_note":"MS (DI.C: Madison Papers). Madison, Papers (Hutchinson), 5:388.","authors":["james-madison"],"paras":[["h","James Madison's Notes of Debates"],["p","Teusday 10. Deer. [1782] A Motion was made by Mr. Ramsay directing the Secy, at War who was abt. to visit his family in Massachusetts, to take Vermont in his way, 8c deliver the Resolutions passed a few days since to Mr. Chittenden.1 For the motion it was urged that it would insure the delivery, would have a conciliating effect, and would be the means of obtaining true and certain knowledge of the disposition 8c views of that people. On the opposite side it was exclaimed agst. as a degradation of so high a servt. of the U. S. as exposing him to the temerity of leaders who were on good grounds suspected of being hostile to the U. S. and as treating their pretensions to Sovereignty with greater complaisance than was consistent with the eventual resolutions of Congress. The motion was rejected."],["p","A motion was made by Mr. Oilmon that a day be assigned for ditermining finally the affair of Vermont.2 The opposition made to the motion itself, by Rhode Island 8c the disagreement as to the day among the friends of the motion prevented a decision 8c it was suffered to lye over.3"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v19.0462":{"title":"James Madison's Notes of Debates","author_label":"James Madison","kind":"notes","date":"1783-01-27","date_label":"January 27, 1783","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 19","source_url":"https://archive.org/details/lettersofdelegat19smit","scan_url":"https://archive.org/details/lettersofdelegat19smit/page/617","text_status":"unreviewed_ocr","editorial_source_note":"MS (DLC: Madison Papers). Madison, Papers (Hutchinson), 6:133-41.","authors":["james-madison"],"paras":[["h","James Madison's Notes of Debates"],["p","Monday 27 Jany. 1783. A letter from Genl. Washington was red. notifying the death of Lord Sterling 8c inclosing a report of the Officer sent to apprehend Knowlton & Wells. (See ).1 The following is an extract from"],["p","the report \"he (one Israel Smith) further sd. that Knowlton 8c Wells had reed, a lettr. from Jonathan Arnold Esqr. at Congress part of which was made public, which informed them that affairs in Congress were unfavorable to them 8c wd. have them look out for themselves. What other information this letter contained he cd. not say — I found in my March thro' the State that the last mentioned gentleman was much in favor with all the principal men in that State I had any conversation with.\"2"],["p","Mr. Arnold being present at the reading informed Congress that he was surprized how such a notion should have prevailed with respect to him; that he had never held any correspondence with"],["p","either Knowlton or Wells; and requested that he might be furnished with the extract above. In this he was indulged without opposition. But it was generally considered, notwithstanding his denial of the correspondence, that he had at least at second hand, conveyed the intelligence to Vermont.15"],["p","A long petition was read, signed as alledged by near two thousand inhabitants (but all in the same hand writing), of the territory lately in controversy between Pa. & Va. complaining of the greivances to which their distance from public authority exposed them 8c particularly of the late law of Pena. interdicting even consultations about a new State within its limits; and praying that Congress wd. give a sanction to their independence & admit them into the Union. The Petition lay on the table without a single motion or remark relative to it.4 The order of the day was called for, to wit the Resolution of Saturday last in favor of adequate & substantial funds.5"],["p","This subject was introduced by Mr. Wilson with some judicious remarks on its importance & the necessity of a thorough 8c serious discussion of it. He observed that the U. States had in the course of the revolution displayed both an unexampled activity in resisting the enemy, and an unexampled patience under the losses & calamities occasioned by the war. In one point only he said they had appeared to be deficient 8c that was a cheerful payment of taxes. In other free Govts, it had been seen that taxation had been carried farther & more patiently borne than in States where the people were excluded from the Govts., the people considering themselves as the sovereign as well as the subject; 8c as receiving with one hand what they paid with the other. The peculiar repugnance of the people of the U. S. to taxes he supposed proceeded first from the odious light in which they had been under the old Govt, in the habit of regarding them; 2dely. from the direct manner in wch. taxes in this Country had been laid; whereas in all other countries taxes were paid in a way that was little felt at the time. That it cd. not proceed altogether from inability he said must be obvious: Nay that the ability of the U. S. was equal to the public burden might be demonstrated. According to the calculations of the best writers the inhabitants of G. B. paid before the present war at the annual rate of at least 25s. Sterlg per head. According to like calculations the inhabitants of the U. S. before the revolution paid indirectly & insensibly at the rate of at least 10s. Sterlg per head. According to the computed depreciation of the paper emissions, the burden insensibly borne by the inhabitants of the U. S. had amounted during the first three or four years of the war to not less than twenty Million of dollars per annum, a burden too which was the more oppressive as it fell very unequally on the people. An inability therefore could not be urged as a plea for the extreme deficiency of the revenue contributed by the States, which did not amount during the past year to Vi a million of dollars, that is to Ve> of a dollar per head."],["p","Some more effectual mode of drawing forth the resources of the Country was necessary. That in particular it was necessary that such funds should be established as would enable Congress to fulfill those engagements which they had been enabled to enter into. It was essential he contended that those to whom were delegated the power of making war 8c peace should in some way or other have the means of effectuating these objects; that as Congress had been under the necessity of contracting a large debt justice required that such funds should be placed in their hands as would discharge it; that such funds were also necessary for carrying on the war; and as Congress found themselves in their present situation destitute both of the faculty of paying debts already contracted, and of providing for future exigences, it was their duty to lay that situation before their constituents; and at least to come to an eclaircissement on the subject; he remarked that the establisht. of certain funds for payg wd. set afloat the public paper; adding that a public debt resting on general funds would operate as a cement to the confederacy, and might contribute to prolong its existence, after the foreign danger ceased to counteract its tendency to dissolution. He concluded with moving that it be Resol[ve]d"],["p","'That it is the opinion of Congress that complete justice cannot be done to the Creditors of the United States, nor the restoration of public credit be effected, nor the future exigences of the war provided for, but by the establishment of general funds to be collected by Congress.\""],["p","This motion was seconded by Mr. Fitzimmons. Mr. Bland desired that Congress wd. before the discussion proceeded farther, receive a communication of sundry papers transmitted to the Virga. Delegates by the Executive of that State; two of which had relation to the question before Congress. These were 1st. a Resolution of the Genl. Assembly declaring its inability to pay more than £50,000 Va. currency towards complying with the demand of Congress. 2dly. the Act repealing the Act granting the impost of 5 PerCt. These papers were receiv'd and read.6"],["p","Mr. Wolcot expressed some astonishment at the inconsistency of the two acts of Va.; supposed that they had an unfavorable aspect on the business before Congress; 8c proposed that the latter sd. be postponed for the present. He was not seconded."],["p","Mr. Chorum favored the general idea of the motion, animadverted on the refusal of Virga. to contribute the necessary sums 8c at the same moment repealing her concurrence in the only scheme that promised to supply a deficiency of contributions, thought the motion however inaccurately expressed, since the word \"general\" might be understood to refer to every possible object of taxation as well as to the operation of a particular tax throughout the States: he observed that the nonpayment of the 1,200,000 Drs. demanded by Congress for paying the interest on the (interl) debts for the year demonstrated that the constitutional mode of annual requisitions was defective; he intimated"],["p","that lands were already sufficiently taxed; that polls & commerce were the most proper objects. At his instance the latter part of the motion was so amended as to run \"establishment of permanent & adequate funds to operate generally throughout the U. States.\""],["p","Mr. Hamilton went extensively into the subject, the sum of it was as follows: he observed that funds considered as permanent sources of revenue were of two kinds, 1st. such as wd extend generally & uniformly throughout the U. S. 8c wd. be collected under the authority of (longs. 2dly. such as might be established separately within each State, 8c might consist of any objects which were chosen by the States, and which might be collected either under the authority of the States or of Congs. Funds of the 1st kind he contended were preferable; as being 1st more simple, the difficulties attending the mode of fixing the quotas laid down in the confederation rendering it extremely complicated & in a manner insuperable: as being more certain; since the States according to the seed, plan wd. probably retain the collection of the revenue and a vicious system of collection prevailed generally through the U. S. a system by which the collectors were chosen by the people 8c made their offices more subservient to their popularity than to the public revenue — 8c as being more ceconomical, since the collection would be effected with fewer officers under the management of Congress, than under that of the States.7"],["p","Mr. Ghorum observed that Mr. Hamilton was mistaken in the representation he had given of the collection of taxes in several of the States; particularly in that of Massachusetts, where the collection was on a footing which rendered it sufficiently certain. Mr. Wilson having risen to explain some things which had fallen from him; threw out the suggestion that several branches of Revenue if yielded by all the States, would perhaps be more just & satisfactory than any single one; for example an impost on trade combined with a land tax."],["p","Mr. Dyer expressed a strong dislike to a collection by officers appointed under Congress, 8c supposed the States would never be brought to consent to it."],["p","Mr. Ramsay was decidedly in favor of the proposition. Justice he said entitled those who had lent their money & services to the U. S. to look to them for payment; that if general & certain revenues were not provided, the consequence wd. be that the army 8c public Creditors would have soon to look to their respective States only for satisfaction; that the burden in this case wd. fall unequally on the States; that rivalships relative to trade wd. impede a regular impost 8c wd. produce confusions amg. the States; that some of the States would never make of themselves provision for half pay and that the army wd. be so far defrauded of the rewards stipulated to them by Congress; that altho' it might be uncertain whether the States wd. accede to plans founded on the proposition before the house, yet as Congress was convinced of its truth 8c importance it was their duty to make the experiment."],["p","Mr. Bland thought that the ideas of the states on the subject were so averse to a general revenue in the hands of Congs. that if such a revenue were proper it was unattainable; that as the deficiency of the contributions from the States proceeded not from8 complaints of their inability but of the inequality of the apportionments, it would be a wiser course to pursue the rule of the confederation, to wit to ground the requisition on an actual valuation of lands; that Congress wd. then stand on firm ground & try a practicable mode."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v19.0545":{"title":"Oliver Wolcott to Laura Wolcott","author_label":"Oliver Wolcott","kind":"letter","date":"1783-02-21","date_label":"February 21, 1783","date_type":"written","recipient":"Laura Wolcott","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 19","source_url":"https://archive.org/details/lettersofdelegat19smit","scan_url":"https://archive.org/details/lettersofdelegat19smit/page/723","text_status":"unreviewed_ocr","editorial_source_note":"RC (CtHi: Oliver Wolcott, Sr., Papers).","authors":["oliver-wolcott"],"paras":[["h","Oliver Wolcott to Laura Wolcott"],["p","My Dear, Philadelpa. 21 Feb. 1783"],["p","I wrote to Rhina by the last Post.1 I think that I have wrote to you or some of the Family by every Post for several Weeks past. I hear but seldom from owing I beleive to the want of oppertinity to write by — such as you shall have I hope that you will embrace."],["p","We have no material News since We had the British Kings Speech. The Non Arrivals induce an opinion that the Vessells for these Ports wait till that Event is ascertained, which is much expected has taken Place in Europe."],["p","By the Blessing of God I still injoy Health. Take the best Care in your Power of your own — and may the Almighty Protect and Bless you and the Family. Our Happiness depends upon his Favour. My Love to our Children. Yours affectionately Oliver Wolcott"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v20.0178":{"title":"James Madison to Edmund Randolph","author_label":"James Madison","kind":"letter","date":"1783-04-29","date_label":"April 29, 1783","date_type":"written","recipient":"Edmund Randolph","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 20","source_url":"https://archive.org/details/lettersofdelegat20smit","scan_url":"https://archive.org/details/lettersofdelegat20smit/page/218","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Madison Papers). In Madison's hand, though not signed. Madison, Papers (Hutchinson), 6:503-4.","authors":["james-madison"],"paras":[["h","James Madison to Edmund Randolph"],["p","My dear Sir Philada. Apl. 29. 1783"],["p","Yesterday's post was the third that has arrived successively without a line from you."],["p","The Definitive Treaty it is said is to be remitted to the two Imperial Courts for their approbation, before the last hand will be put to it. This will be a mere compliment however, and as the parties have settled their contests without their intermediation there can be no pretext if there were a disposition to meddle. It appears from English Gazettes that Shelburne has been so pressed by the unpopularity of some of the terms of peace, that he cd. not prevent a vote of the House of Commons declaring them to be disadvantageous 8c dishonorable. The consequence prognosticated is another change of the Administration in favor of North's 8c Fox's parties, who have made a common cause agst. Shelburne."],["p","The propositions relative to the National debt, with an address enforcing it 8c referring to sundry documents &c is completed and will soon be forwarded to the Legislatures.1 Mr. Jefferson will have given you the general views of Congress on this subject."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v21.0050":{"title":"James McHenry to Margaret Caldwell","author_label":"James McHenry","kind":"letter","date":"1783-10","date_label":"October 1783","date_type":"written","recipient":"Margaret Caldwell","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 21","source_url":"https://archive.org/details/lettersofdelegat21smit","scan_url":"https://archive.org/details/lettersofdelegat21smit/page/74","text_status":"unreviewed_ocr","editorial_source_note":"RC (MdHi: McHenry Papers).","authors":["james-mchenry"],"paras":[["h","James McHenry to Margaret Caldwell"],["p","[Princeton] Sunday morning 19 Octbr. [ 1 783] . Considers their relationship and financial prospects after marriage. \"When last in Philadelphia I suggested to you some little dispositions for our future happiness, since which I have been endeavouring so to forward them, as to put it in my power to be always with my Peggy. I did not tell you, I beleive, that in addition to a share in my brothers business in Baltimore,1 I was to throw one thousand pounds into a partnership with Mr. Armstrong, who is to open a dry good store in Philadelphia. From the profits of these two funds I hope we shall have few difficulties to encounter on our e[ntry] into life. It is not, my present intention to appfly] myself in the commercial line, unless I should be left out of Congress; or unless, my brother should think it more to my advantage; and as I have a great opinion of his professional knowlege, should he think so, I shall be very much under the direction of his advice. What is wanting to compleat my plan I shall arrange with my brother sometime in the next month, when I must leave Congress to attend our general assembly.\""]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v21.0061":{"title":"Samuel Huntington to Jonathan Trumbull, Sr.","author_label":"Samuel Huntington","kind":"letter","date":"1783-10","date_label":"October 1783","date_type":"written","recipient":"Jonathan Trumbull, Sr.","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 21","source_url":"https://archive.org/details/lettersofdelegat21smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (Ct: Trumbull Papers).","authors":["samuel-huntington"],"paras":[["p","Samuel Huntington to Jonathan Trumbull, Sr."],["p","Sir, Princeton, Octor 22d. 1783 }"],["p","Congress have recommended to the United States to Set apart the Second Thursday in Decemr as a day of public Thanks-giving."],["p","They have also resolved that in future two places be prepared for the residence of Congress viz. at or near Trenton on the Deleware & at or near Gorgetown on the Patowmac, & until accomodations are provided necessary for the purpose, to Set alternately at Trenton in Jersey & at Anapolis in Maryland, & in consequence have agreed on the 10th of Novemr to Adjourn from this place to meet at Anapolis on the 26th of the Same month, & Set at each place not more than one year, nor less than Six months if public business Shall require So long a Session in the year.2"],["p","This plan hath been adopted after mature consideration of a variety of circumstances, too tedious to be fully enumerated."],["p","The appointment of the only place for their residence at or near Trenton did not give Satisfaction and for want of present accomodations it Seemed necessary to remove to Some other place for their Session the ensuing winter, & was thought essential for the public welfare by most of the delegates to avoid the City of Philadelphia, & all other large Trading Cities in future, & in this Sentiment we presume our constituents fully coincide."],["p","After all; time & experience will best determine upon the wisdom & utility of the measure."],["p","I have the Honour, to be with the highest Respect, Your Exys Humble Servt, Sam. Huntington"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v21.0112":{"title":"Hugh Williamson to John Gray Blount","author_label":"Hugh Williamson","kind":"letter","date":"1783-11-01","date_label":"November 1, 1783","date_type":"written","recipient":"John Gray Blount","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 21","source_url":"https://archive.org/details/lettersofdelegat21smit","scan_url":"https://archive.org/details/lettersofdelegat21smit/page/141","text_status":"unreviewed_ocr","editorial_source_note":"RC (Nc-Ar: Blount Papers).","authors":["hugh-williamson"],"paras":[["h","Hugh Williamson to John Gray Blount"],["p","Dear sir Princeton 1st Novr. 1783"],["p","On the 3rd of Septr. the definitive Treaty was signed on which I give you Joy. Mr Thaxter, Mr Jno Adams's Secy, is bringing it over. He took his Passage in the Packet from Port L'Orient which saild on the 20th of that Month. A gentleman who saild after him is arrived.1"],["p","Mr Van Berckell had his public Audience yesterday. On the 12th we are to adjourn for Annapolis to meet there on the 26th. Be so good as desire the Post Master to inclose Letters for Delegates accordingly. I have the Honor to be, Dr Sr, Your obed & hble Servt,"],["p","Hu Williamson 2"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v21.0231":{"title":"John Francis Mercer to Ezra L'Hommedieu","author_label":"John Francis Mercer","kind":"letter","date":"1784-01","date_label":"January 1784","date_type":"written","recipient":"Ezra L'Hommedieu","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 21","source_url":"https://archive.org/details/lettersofdelegat21smit","scan_url":"https://archive.org/details/lettersofdelegat21smit/page/292","text_status":"unreviewed_ocr","editorial_source_note":"RC (Andrew Fiske, Shelter Island, N.Y., 1981 ) .","authors":["john-francis-mercer"],"paras":[["h","John Francis Mercer to Ezra L'Hommedieu"],["p","Dear Sir Annapolis Jany 18. 84."],["p","When I had the pleasure of serving with you in Congress, I parted with to you a number of Certificates, which I have since discovered woud have a value in my hands which they can have with no other person. The circumstances which give them this value are too long & complicated to detail, but are yet extremely cogent & pressing. I woud therefore be very happy to repurchase them of you at the value which such certificates are of, or if more agreable replace them with others that woud be of equal value to you. As this will be obliging me extremely & cannot possibly be injurious to you I have no doubt of you finding pleasure in a compliance with my request. I have engag'd of my friend Colo. Monroe to negociate this business with you.1 With wishes for your happiness, I am Dr Sir, Yr. mo. Ob. Sert."],["p","John F. Mercer"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v21.0425":{"title":"Richard Dobbs Spaight to David Howell","author_label":"Richard Dobbs Spaight","kind":"letter","date":"1784-04-29","date_label":"April 29, 1784","date_type":"written","recipient":"David Howell","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 21","source_url":"https://archive.org/details/lettersofdelegat21smit","scan_url":"https://archive.org/details/lettersofdelegat21smit/page/557","text_status":"unreviewed_ocr","editorial_source_note":"RC (DNA:PCC, item 78).","authors":["richard-dobbs-spaight"],"paras":[["h","Richard Dobbs Spaight to David Howell"],["p","Sir, April 29th. 1784. 7 O'clock."],["p","I reed, yours in answer to mine of this date,1 it convinces of two things, first that you are a Scoundrel, Secondly that you are Coward."],["p","Your address to the Chair this day,2 has just coincided with my Opinion of it. You hoped either to bring on a Quarrel between Mr. Mercer 8c the President, of whose courage you had a better Opinion,"],["p","than of your own, or to find some dirty hole for to creep out of. The latter you have found to be the only — the last hope, and have accordingly embraced it — depending on your size to extricate yourself from the Chastisement which you are pleased to say you will inflict upon an person who afflicts you."],["p","Tho' it has always been my opinion and I am now convinced of it, that you are a Scoundrel, yet as you vilify a Dignified Character, I wish you'd either give me, as the friend of Mercer, or Mercer, the Satisfaction of a Gentleman (as perhaps you may quibble upon the satisfaction of a Gentleman I mean that you should meet one of us with a case of Pistols 8c your friend) as it will prevent that disagreeable breach of the Peace called Assult and Battery."],["p","I am, Sir, Your Obt. Servt. Richd. Dobbs Spaight."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v22.0245":{"title":"Richard Henry Lee to Samuel Adams","author_label":"Richard Henry Lee","kind":"letter","date":"1785-04","date_label":"April 1785","date_type":"written","recipient":"Samuel Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 22","source_url":"https://archive.org/details/lettersofdelegat22smit","scan_url":"https://archive.org/details/lettersofdelegat22smit/page/314","text_status":"unreviewed_ocr","editorial_source_note":"RC (NN: Samuel Adams Papers).","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee to Samuel Adams"],["p","New York April the 7th 1 785 My much valued friends letter of March the 24th1 was this day delivered to me, but not by Mr. Kirkland or Colo. Allan, it came from our Door-keeper who told me that it had been picked up on Long Island. I received it however, with that true content that your letters always bring with them. You have certainly done me justice when you have taken me for an Unchanging Friend. I endeavor not to take up friendships lightly, and therefore I am not capable of lightly laying them down. But in this case, I am much too sensible of the honor done me by your friendship not to wish most sincerely for its continuance. And the true reason for want of punctuality in writing, I assigned to you in my letter of March 14th last. The reasons there assigned will, I hope, secure for me your pardon for having employed an Amanuensis (my Nephew Shippen) upon that letter."],["p","Your recommendation of Messrs. Kirkland & Allan are very sufficient to procure for them my utmost favor.2 Here you observe that I"],["p","have personal knowledge of the deserts recommended. I have, but it was not necessary when I reflected who it was that recommended."],["p","I hope that we have gained your approbation by sending our Patriot friend Mr. J. Adams Minister to London. I hope also for good things from that Mission. Spain seems mal-affected to us, but as she has a commencing dispute with Great Britain about the Musquetto shore, perhaps we may find in her Minister, expected here this month, a more accommodating spirit concerning the Mississippi than has yet appeared. I am, with sincerest sentiments of esteem, My dear Sir your affectionate friend, Richard Henry Lee"],["p","[P.S.] My best wishes attend Mrs. Adams."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v22.0607":{"title":"Rufus King to Caleb Davis","author_label":"Rufus King","kind":"letter","date":"1785-10-10","date_label":"October 10, 1785","date_type":"written","recipient":"Caleb Davis","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 22","source_url":"https://archive.org/details/lettersofdelegat22smit","scan_url":"https://archive.org/details/lettersofdelegat22smit/page/675","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi: Davis Papers).","authors":["rufus-king"],"paras":[["h","Rufus King to Caleb Davis"],["p","Dear Sir' New York 10th. Oct. [17]85"],["p","Mr. Storer, a son of Deacon Storer, arrived here two days since — he came immediately from the family of Mr. Adams in London, and brings Letters from him as late as the 1 1th of Sepr.2 — Not a word of the Algerine War. Mr. Adams mentions one circumstance which is interisting — that Mr. Lamb, whom I mentioned to you in my last had not arrived, and that from the urgency of a Treaty with the several Barbary powers, Mr. Jefferson &: he had concluded to send Mr. Barclay, who is Consul General in France, to the States of Barbary to execute the business of making peace with those Pirates. This Determination was taken early in September. Mr. Barclay had asked leave of Congress to return for a short Time to America, and was indulged. He might have been expected here before this time — his not having arrived, and the information that the Commissioners Mr. Adams & Mr. Jefferson had fixed on him for the Barbary Treaties, induced a hope that this business is in a good way."],["p","With great esteem, Your Obt. servt, Rufus King"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v23.0012":{"title":"William Samuel Johnson to Matthew Griswold","author_label":"William Samuel Johnson","kind":"letter","date":"1785-11-14","date_label":"November 14, 1785","date_type":"written","recipient":"Matthew Griswold","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 23","source_url":"https://archive.org/details/lettersofdelegat23smit","scan_url":"https://archive.org/details/lettersofdelegat23smit/page/17","text_status":"unreviewed_ocr","editorial_source_note":"FC (CtHi: Johnson Papers). In the hand of William Samuel Johnson.","authors":["william-samuel-johnson"],"paras":[["h","William Samuel Johnson to Matthew Griswold"],["p","Sr. Stratford. Novr. 14th. 1785"],["p","While waiting a Conveyance for the I received yr. favour of"],["p","the Nth covering an order on the Treasy for £200.0 & am much"],["p","obliged by yr. Excellys. Attentions to procure me the necessary sup-"],["p","plies to proceed on to Congress. 1 do not know what more could possibly he- done. I hope one or other of the Applications may he successful, 8c as I have said in the former Letter the Moment I am in Cash I shall set out.1 Five States I am informed were in N York on Saturday last as well as one Delegate from two other States all extremely impatient for the arrival of a sufficient Represent'n to open Congress. They shall not certainly be detan'd a single Day by my absence after 1 am able to proceed. The Letters to Coll Abel 8c Coll Fitch will be forwarded to them immediately. The Demand of Mr. Smith is no doubt a Just one 8c ought to be paid as soon as the state of the public Funds will admit, but the Threat of Reprisal is I apprehend an Idle one as this cannot be done without a previous Application by the Sovereign of the Cr. 8c a denial of Justice 8c I hardly imagine that anything of this Nature has yet taken place. I shall be happy to receive the Resolutions of the Assembly relative to our Claim of Western Territory, 8c yr. Excelly may be assured that the most exact attention shall be paid to them. Yr. Excellys. most obedt. humble Servant"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v23.0246":{"title":"William Samuel Johnson to Samuel William Johnson","author_label":"William Samuel Johnson","kind":"letter","date":"1786-05-14","date_label":"May 14, 1786","date_type":"written","recipient":"Samuel William Johnson","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 23","source_url":"https://archive.org/details/lettersofdelegat23smit","scan_url":"https://archive.org/details/lettersofdelegat23smit/page/281","text_status":"unreviewed_ocr","editorial_source_note":"RC (CtHi: Johnson Papers).","authors":["william-samuel-johnson"],"paras":[["h","William Samuel Johnson to Samuel William Johnson"],["p","My dear Son, New York May 14th. 1 786."],["p","I have receiv'd yr. several favours of the 25th of Deer. 1785, Febry 21st, March 4th, & 28th 1786, but not in the Order in which they were written, the First having come to hand last of all. To that of Jany. 24th, which arrived First, I answer'd by the only Opportunity that has offer'd of writing since you left us. I heartily bless God for the restoration 8c continuance of your Health, & for your favourable prospects in business. We too through the favour of Heaven have been bless'd with good health upon the whole, tho' as I mention'd to you, Charles had had a Fever of short continuance, & I have this Spring had several returns of the Gout, but they have happily not been severe; nor con- Fined me for any length of time, & the whole Family seem now to be in perfect health. Mr. Verplank 8c Betsey are on a Visit at Stratford, where I have not been since the beginning of March, but hope soon to make an excursion there. Mr. Verplank go's to Fish Kill before they return here. Our Winter has been moderate, but the Spring is backward, as the phrase is. The severest snow Storm since you left us, was on the First of April. In the Fine Climate of Bermudas, I presume, you experience few inconveniencies from the changes of Weather which give us so much trouble here. Your Introduction into that country has been favourable, 8c I hope your continuance (while you shall chuse to remain there) will be equally fortunate 8c agreeable. It was particularly fortunate, it seems, that you fell so early into Mr. Van Dams hands, from whom I had a very friendly Letter upon the subject & have returned him my hearty thanks for his kindness to you, 8c pray God he may have a happy Meeting with his sister 8c Neices, who go in the Vessel by which I expect to send this. I am also under very great Obligations to the Governor, 8c all those other Gentlemen you mention, who have shewn you so much polite Attention, to whom I wish you, if it be proper, to present my Compliments & assure them of my gratitude. It gives me particular pleasure to see that you have so speedily 8c successfully engaged in Business, & pursue it with so much Ardour. You seem at once to have adopted the true Spirit of business, to engage boldly in everything, & to labour earnestly in all things; It is the sure road to lame 8c fortune, 8c tho' it is not to be expected but that you will meet with difficulties in affairs, yet I hope by perseverance 8c assiduity, you will experience the truth of Seneca's observation \"Non quia difficilia sunt, non Andemus; sed quia non Andemus, difficilia sunt.\"1 The Admiralty Cause was indeed a bold undertaking ai so early a period of your Practice, bul it was happily successful, 8c success justifies the boldest at-"],["p","tempts. Even failure is sometimes honourable in noble 8c generous designs. Est quoddam magnis cecidere Ausis.- I am much obliged to you for your frequent & particular Letters 8c hope you will continue them, that we may be as often as possible acquainted with the situation of your affairs. The last Vessel, said to come from Bermudas, bro't us none; but we trust it was accidental, & console ourselves with those we have receiv'd, 8c the pleasing hope that others are on the way, & may soon arrive. We will certainly sell your Farm, as soon as it can be done to any tolerable advantage. But in truth there is so little Money in our Country, 8c so much Land at Market, that the prospect of obtaining a beneficial price for it, is by no means favourable. I shall however be attentive to it, as far as my situation will admit of. Charles, I imagine is now at Middletown taking what Care he can of it, 8c I have directed him to offer it for sale at every probable opportunity. I shall also endeavour to sell Property of my own whenever I can do it to advantage, 8c it will be indifferent to me out of what funds I advance to you, provided 1 can but obtain what is necessary for you, & yr. Brother 8c Sisters. But in all these matters, you are sensible, my residence here produces unavoidable embarrassments 8c delays, which however I will surmount in the best manner 1 can."],["p","I will certainly procure, if possible, a Copy of our Act of Confiscation for Mrs. Brown3 when I go again into Connecticut. You are sensible that our Laws have been revised since the War, 8c consequently that those temporary Acts are out of Print, but at worst I can have it transcribed from the old Law Book. As far as I now recollect, it do's not specifically comprehend Estates Tail, 8c consequently cannot affect the Estate in Remainder after the Death of the Tenant in Possession who incur'd the Forfeiture, but there is no dependance to be plac'd upon Memory in such Cases, 8c we have so few entail'd Estates that it could hardly have been an object of attention."],["p","Charles has sent some Books, but not all that I wrote for. Whether he could not find them, or what other reason there was for it, I cannot tell, as there is no Letter come with them. I shall buy Burrough's Repts.4 here that you may have a good series of L. Mansfields Decisions, 8c add a French Book or two which I have with me. There are no Books properly upon the Theory 8c Practice of the Admiralty that I know of except Praxis Curia' Admiral it atis, 8c the Practe. of the Eccksiastl. Courts therein Cited.5 An old Edition of the latter is sent, the former is not come, & must be deferr'd till I go to Connecticut, when I will also select some other Books for you. The Practice of the Admiralty, of the Ecclesiastical Courts, 8c in Chancery you are sensible all stand on the same general ground, 8c are derived from the Civil Law, so that the same general Principles apply to them all. The Books of Practice in Chancery are very similar, the Cursus Cancellariae6 now sent you may I hope answer your purpose for the present, but if there is any other"],["p","more in Use with you upon mentioning it I will, if possible, procure, 8c send it to you. The Causes Celebres are French, somewhat in your professional line, 8c tho' odd Volus. it makes no difference, as the Cases are totally unconnected 8c independent of each other. I will send you other volumes of them, if, upon trial, you find this kind of reading agreeable & useful to you."],["p","I am unfortunately disappointed with respect to Burrough's Repts. — there is not a set of them to be had in New York. I have therefore substituted Stranges7 & Wilson's Repts.8 & even of the latter I am obliged to borrow a second hand set under an engagement to replace them with new ones as soon as the Ships arrive from Ireland, when I hope also I shall be able to get Burrough for you. Such other Books as you particularly wish to have you will mention. The Squash Seeds you desired, you will find in the Trunk, 8c by way of Stowage I have added the News Papers since the Middle of March, which tho' not important may afford you some amusement."],["p","Charles is return'd from Middletown, & says in a Letter to me \"Seth Wetmore wishes much to buy the Lott Walker has sown with Wheat. He offers £5.5.0 per Acre for it, 8c I am told it is its full value, 8c the disposal of it will not hurt the sale of the farm.\" Perhaps he has written you more fully in the Letter I forward you from him. And you will say whether it will be agreeable to you to sell this piece of Land detach'd from that residue of the farm, or not. They were all well at Stratford two days ago. I enclose you the key of the Trunk & a List of the articles contain'd in it, & am with the most ardent Prayers for your health 8c felicity, 8c compts. to Mr. Van Dam, Capt. Bascom &c, yr. most affectionate Father 8c Friend. Wm. Saml. Johnson"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v23.0282":{"title":"Rufus King to Elbridge Gerry","author_label":"Rufus King","kind":"letter","date":"1786-06-04","date_label":"June 4, 1786","date_type":"written","recipient":"Elbridge Gerry","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 23","source_url":"https://archive.org/details/lettersofdelegat23smit","scan_url":"https://archive.org/details/lettersofdelegat23smit/page/334","text_status":"unreviewed_ocr","editorial_source_note":"RC (NHi: King Papers).","authors":["rufus-king"],"paras":[["h","Rufus King to Elbridge Gerry"],["p","Dr. Gerry, Sunday Evening 4. June [1786]"],["p","Mr. Hancock has sent his resignation as President, and Tomorrow I suppose Mr. Gorham will be elected his successor.1 You understand the meaning of this Appointment as well as I can explain it; no State is here from New England except Massachusetts."],["p","Your freinds here are all well and make frequent enquiries concerning you. I shall not forget your mention of the situation of your Brother."],["p","I have nothing to add but an apology for a long & incorrect letter written to you this morning upon an interesting subject."],["p","Your's, R King"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v23.0311":{"title":"Rufus King to Elbridge Gerry","author_label":"Rufus King","kind":"letter","date":"1786-06-18","date_label":"June 18, 1786","date_type":"written","recipient":"Elbridge Gerry","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 23","source_url":"https://archive.org/details/lettersofdelegat23smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (NHi: King Papers).","authors":["rufus-king"],"paras":[["h","Rufus King to Elbridge Gerry"],["p","My dear Sir, New York 18 June 1786"],["p","I intended by this post to have sent you a copy of the North Carolina law granting the supplementary Funds, but it is very voluminous, & the copy is not finished. I fear it will come too late, as I presume your Session will be a short one."],["p","Connecticut & New Jersey have finished their Sessions without attending to the situation of the confederacy; the former took into consideration the Requisition of last year, and refused a compliance with it. Fhe latter in their late Session did not even (real the subject with (lie attention it received in Connecticut."],["p","Yon my dear friend, must know out Situation, as fully as I do, who am a daily witness of the humiliating condition of the Union — yon"],["p","364 Jink 18, 1786"],["p","may depend on it, that the Treasury now is literally without a penny. By anticipations, and the collections from Virginia, Maryland 8c this state, the Board of Treasury have made provision for the Dutch interest, which fell due this month — but there is no prospect of their being able to provide for the payments which will be due in January. The posts on the Ohio are not well supplied with military Stores, the Secretary at War applied a few days since for 1000 Dollars for the transportation of the necessary Amunition to these Posts. The Board of Treasury, urgent as the occasion of this application is allowed to be, explicitly declare their utter inability to make this pitiful Advance.1"],["p","What are we to expect?"],["p","I wish I could see you for a few hours; It is impolitic to write any thing as information, which cannot be clearly proved — and yet you and I have been under the fullest Conviction of the views & intentions of men, concerning which such clear proof did not exist. Be assured that your apprehensions of a certain influence in this State are well founded — nay farther, the influence is not confined to this State. Those men who have hazarded every valuable consideration in the cause of their country, and those who are willing to pursue their example, are now held up to the people as their Enemies & not their friends. Every man who wishes to strengthen the federal Government, and confirm the Union, is represented as unfriendly to the liberties of the People."],["p","These expressions of anxiety for the Liberties of the people, come not from those who have lent their aid in the days of Adversity, but from those artful & venal Miscreants, who withdrew themselves from their country's support, and existed her bitterest enemies. They now successfully gratify their hatred of our Independence, by scattering Jealousies among the People."],["p","I am not vain enough to think my country has much interest in my services; but inconsiderable as they truly are, they have been considered as inconvenient to certain views. I have made it a certainty that a character in this City, which you 8c I never did, or shall confide in, has industriously communicated to a number of our Fellow Citizens, that I was in the Interest ofN York, 8c opposed to Massachusetts, & that I intended to leave the latter 8c become an Inhabitant of the former. So far as the effect of this measure is personal, I ought not to be anxious— but concerning the Objects wished for I am, and must be, concerned."],["p","The Election of Delegates will have taken place before this reaches you — it will therefore require no Apology."],["p","Your's affectionately, R King"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v23.0342":{"title":"Rufus King to Elbridge Gerry","author_label":"Rufus King","kind":"letter","date":"1786-07-09","date_label":"July 9, 1786","date_type":"written","recipient":"Elbridge Gerry","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 23","source_url":"https://archive.org/details/lettersofdelegat23smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (NHi: King Papers).","authors":["rufus-king"],"paras":[["h","Rufus King to Elbridge Gerry"],["p","Dear Gerry, New York 9 July 1786"],["p","What effects will flow from the Grant of the supplementary Funds by Massachusetts at present is doubtful — indeed the value of the domestic Debt becomes more and more uncertain. The Advocates for a payment of this Debt upon what they call principles of Justice as applied to the purchasers or Speculators; are not confined to Massachusetts. The Officers of the late Army have most of them sold their Certificates; and are now clamarous against their Redemption except at a depreciated amount.1"],["p","Mr. Osgood is decided in his Opinion, that the best mode of conducting this Business, will be an apjaortionment of the whole Domestic Debt upon the states or in other words for congress to make a requisition for the whole Principal of the Domistic Debt, 8c leave it to the states to arrange the payment with their own Citizens as they may please."],["p","Adieu your's, R King"],["p","[P.S.] I have enquired of Mr. Thomson if he could give any information relative to the failure of Letters &c — he says that a Letter from"],["p","394 JULY9, 1786"],["p","him covering one to Mrs. Gerry from her Brother in the East Indies has miscarried. I cannot account for it unless the failure is in the Post Office — Seymour has always delivered the Letters from you, and I believe has been faithful — the Letters from Mr. Thompson I have always covered, and sent them safe to the P. Office. I shall mention the subject to the Post Master Genl."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v24.0050":{"title":"Rufus King to Benjamin Lincoln","author_label":"Rufus King","kind":"letter","date":"1787-01-21","date_label":"January 21, 1787","date_type":"written","recipient":"Benjamin Lincoln","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 24","source_url":"https://archive.org/details/lettersofdelegat24smit","scan_url":"https://archive.org/details/lettersofdelegat24smit/page/73","text_status":"unreviewed_ocr","editorial_source_note":"RC (CtY: Wetmore Family Collection). Addressed: \"Major General Lincoln, Worcester.\"","authors":["rufus-king"],"paras":[["h","Rufus King to Benjamin Lincoln"],["p","Dr. General New York 21 Jany. 1 787."],["p","This will meet you again in military command. It conveys the devout wishes of a Brother Citizen for your prosperity, and the safety of the Commonwealth. Will you have the Goodness to direct some person about you to give me a concise account of your situation, and of the Events which may take place on this expedition. The anxiety of an absent citizen at this juncture must be my apology in making this request."],["p","Farewel, I am with the Highest Respect & Esteem, Your's &c,"],["p","Rufus King"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v24.0249":{"title":"William Blount to John Gray Blount","author_label":"William Blount","kind":"letter","date":"1787-06-03","date_label":"June 3, 1787","date_type":"written","recipient":"John Gray Blount","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 24","source_url":"https://archive.org/details/lettersofdelegat24smit","scan_url":"https://archive.org/details/lettersofdelegat24smit/page/299","text_status":"unreviewed_ocr","editorial_source_note":"RC (Nc-Ar: Blount Papers). Missing portions of letter reprinted from Blount, Papers (Keith), pp. 304-5.","authors":["william-blount"],"paras":[["h","William Blount to John Gray Blount"],["p","[New York] June 3d. 1787 A few days past arrived at this place a Capt. Horton in a small Sloop from Washington which he says he has sold to you for 300 Pieces of Tar [sic] Timber — He has delivered me 2 Barrells of Tar, 2 ditto pitch, 2 ditto Turpentine which he says you put on board the Sloop with out any Letter or paper addressed either to myself or any body else respecting them. These six Barrells were by you I suppose intended as a Sample to the Marine of France on which a Contract for an annual supply should be founded and I have caused them to be stored with Mr. John Ramsay."],["p","You will recollect that I before informed you that I had requested the Covernor to furnish the Delegation with authenticated Certificates of the Exports of the Produce of North Carolina for the vears 85 &86.1"],["p","In reply to this request the Governor informed me that it should he done but as yel no such Certificates have made their appearance here. And Mr. DeLaforest says this Certificate is indispensible to the insuring [successfully] to the Contract for how[ever] desirous he may be to serve individuals he must speak on the Subject in a National Sense and this he can't do unless he has authentic Documents to show the Court the very large Exports made by North Carolina of Naval Stores and the advantage it would be to France to take it by Contract directly from the State in which it is made and adds that the Marine of France would be more apt to give a Contract to No. Carolina or her Citizens than to any other State because France never has yet done anything for No. Carolina."],["p","Mr. DeLaforest appears much disposed to serve us and I am sure will do every thing in his power to place such a Contract in so advantageous a View to his Nation as to insure it if in his power — For this we are chiefly indebted to Hawkins. Mr. Otto the Charge des Affairs of France spoke to me about this proposed Contract about two days past and said he hoped to see it take place — For my part I feel not any doubt from my certain Knowledge that the French mean and wish to push a Trade with America but [a] Contract may be made for the annual delivery of a few thousand Barrells for as many as three Years at Brest at a good price. When the Samples go to France which is needless until! they are accompani'd by the afore-mentioned Certificate it is Necessary that the Terms of Proposals should at the same Time be sent to the Marine of France in which must be clearly expressed the Time and place of Delivery, the price, when & how paid and that No duties shall be paid in France neither on the Naval Stores nor the Vessels on which they are freighted and the Bottoms in which they shall be shiped say French or American — there must also be sent one of the Certificates of the Governor showing who J. G. & T B.2 are — the one I had I have sent to T B. by Mr. Smith. I shall again write to the Governor respecting the Certificate of Exports."],["p","I am quite recovered of my Indisposition. Twinings Bill has receivd a legal protest by a Notary Public and will soon be forwarded to you by post the cost of Protest have been 18/."],["p","Your's Wm. Blount"],["p","[P.S.] Horton left this today for Petersburg full freighted and with him went passengers Col. Ashe & Robt. Fenner."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v24.0366":{"title":"Richard Henry Lee to John Adams","author_label":"Richard Henry Lee","kind":"letter","date":"1787-09-03","date_label":"September 3, 1787","date_type":"written","recipient":"John Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 24","source_url":"https://archive.org/details/lettersofdelegat24smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi: Adams Family Papers).","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee to John Adams"],["p","Dear Sir, New York September the 3d 1 787"],["p","Since my letter to you of December 1785 from Chantilly in Virginia1"],["p","September3, 1787 423"],["p","in answer to the letters that you were pleased to write me on the 26th of August, 6th 8c 7th of September 1785; I have not been honored with any letter from you. On my arrival here I met with, and read with great pleasure your book on the American governments.2 The judicious collection that you have made, with your just reflections thereon, have reached America at a great Crisis, and will probably have their proper influence in forming the federal government now under consideration. Your labor may therefore have its reward in the thanks of this and future generations. The present federal system, however well calculated it might have been for its designed ends if the States had done their duty, under the almost total neglect of that duty, has been found quite inefficient and ineffectual. The government must be both Legislative and Executive, with the former power paramount to the State Legislatures in certain respects essential to federal purposes. I think there is no doubt but that this Legislature will be recommended to consist of the triple ballance, if I may use the expression, to signify a compound of the three simple forms acting independently, but forming a joint determination. The executive (which will be part of the legislative) to have more duration and power enlarged beyond the present. This seems to be the plan expected, and generally spoken of — I say expected, because the Convention is yet sitting, and will continue so to do until the middle of this month. I was appointed to that Assembly, but being a Member of Congress where the plan of Convention must be approved, there appeard an inconsistency for Members of the former to have Session in the latter and so pass judgement at New York upon their opinion at Philadelphia. I therefore declined going to Convention and came here; where we have lately contracted for the sale of six millions of Acres on the N.W. side of Ohio in the ceded territory, for lessening the domestic debt — And now, another offer is made for two millions more.3 I hope we shall at least be able to extinguish the domestic debt created by the late war, which is by far the greatest part of the debt. So many of our Members have lately gone from hence to the Convention, that we have had but 5 States in Congress for a month past, which has prevented any determination on your application to return. It seems at present to be very doubtful whether there will be any Resident appointed to the Court where you are — some being for a Minister, some for a Charge, and some for neither — But a Consul only. How it will terminate can scarcely be conjectured yet.4 Permit me now Sir to entreat your attention and good offices in the following affair. Mr. Thomas Steptoe, concerning whom I formerly wrote to you, dyed on shipboard as he was returning home from the East Indies either in 1784 or 1785, and we are not certain whether he was on a Danish or a Sweedish ship, but it was one of these. Captain Miller who gave me this intelligence by letter, and who is now up the Baltic, was"],["p","424 Septembers, 1787"],["p","not certain to which of these nations the Ship belonged. But he said ii was supposed that Mr. Steptoe had a considerable property. His heirs in Virginia having heard nothing concerning this property, apprehen'd that it has been secured by the Officers of the Ship wherein he dyed. The want of exact information concerning Mr. Steptoes affairs will render it difficult to procure redress. Perhaps a proper enquiry among those people in London who trade with the East Indies, may furnish some light upon this business. Or an application to the Danish & Swedish Ministers at the Court of London might cause an enquiry to be made in their respective countries, so as that the holders of his property fearing detection, may come forward and honestly deliver up this gentlemans effects — And inform if he left any Will. It is not improbable that he left a will somewhere, which if procured would regulate the descent of his Virginia estate. I shall be singularly obliged to you my dear Sir if you will interest yourself in this business, and let me know the success of your enquiries. :> My complements, if you please to Colo. Smith; and affectionate regards to my Nephew Shippen. With every sentiment of esteem and friendship I am dear Sir, sincerely yours, Richard Henry Lee"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v24.0508":{"title":"James Madison to Tench Coxe","author_label":"James Madison","kind":"letter","date_type":"written","recipient":"Tench Coxe","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 24","source_url":"https://archive.org/details/lettersofdelegat24smit","scan_url":"https://archive.org/details/lettersofdelegat24smit/page/632","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Madison Papers). Madison. Papers (Rutland). 10:444-45.","authors":["james-madison"],"paras":[["h","James Madison to Tench Coxe"],["p","Dear Sir N. York Jany. 30. [ 1 788]"],["p","I have been favored with two letters from you, one containing 2 copies of the freeman, the other a pamphlet & letter for Mr. King.1 The latter will be forwarded this evening, as will also the former which did not arrive in time for the preceding mail. What goes by name of consolidation in Pena. is I suspect at the bottom of the opposition to the New Govt, almost every where; and I am glad to find you engaged in developing the subject. I inclose some papers2 in which it has been taken up here, that if any hints are contained in them, they may be pursued in your enquiry."],["p","There is certainly a favorable change taking place in Virga. on the subject of the Constitution. Several converts of influence have been named to me. I had heard also that Col. R. H. Lee was relaxing in his opposition, if not in his opinions. The authority from which I have it is such as almost to overcome the improbability of the thing.3"],["p","January?, 1788 633"],["p","Our anxiety for the event in Masts, was not relieved by the last mail. No decisive index had appeared of the relative force of parties. Some letters are flattering, others discouraging, and others again totally skeptical. My hopes 8c apprehensions are pretty nearly balanced by the sum of the probabilities on each side, tho' with rather a preponderancy on the favorable side."],["p","With great esteem I am Dr Sir, Yr. Obed hble servt.,"],["p","Js. Madison Jr."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v25.0121":{"title":"Nicholas Gilman to John Langdon","author_label":"Nicholas Gilman","kind":"letter","date":"1788-06-05","date_label":"June 5, 1788","date_type":"written","recipient":"John Langdon","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 25","source_url":"https://archive.org/details/lettersofdelegat25smit","scan_url":"https://archive.org/details/lettersofdelegat25smit/page/141","text_status":"unreviewed_ocr","editorial_source_note":"RC (Capt. J.G.M. Stone, Annapolis, Md., 1973).","authors":["nicholas-gilman"],"paras":[["h","Nicholas Gilman to John Langdon"],["p","Dear Sir. New York June 5th 1 788"],["p","I do myself the honor to forward the enclosed paper, which contains an account of the ratification of the new System by the Convention of South Carolina. No official accounts have yet come to hand; but there seems to be no reason to doubt the authenticity of the one enclosed; it being correspondent to preceeding accounts of the temper of the Convention, written by one of the delegates to a member of Congress, Subsequent to a proposition for an adjournment 8c received by the last Charles Town Packet."],["p","Accounts from Virginia are rather favorable but among the delegates to the Convention of New York, I have no doubt, there is a large majority against the question. Notwithstanding the Convention of Virginia is now in session I hope New Hampshire will have the honor of being the ninth State in accession to the system and I beg leave to suggest that it is considered a matter of great importance that we have an account of the ratification here before the Convention of this State come to a decision as they will be influenced more by our proceedings than by the doings of Virginia."],["p","I am happy to hear that the people in Vermont are federally inclined and much in favor of the new Contitution. With the greatest Respect & Esteem, I have the Honor to be, Dear sir, Your Most Obedient 8c Humble Servant, N. Gilman"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v25.0403":{"title":"James Madison to Edmund Randolph","author_label":"James Madison","kind":"letter","date":"1788-11-02","date_label":"November 2, 1788","date_type":"written","recipient":"Edmund Randolph","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 25","source_url":"https://archive.org/details/lettersofdelegat25smit","scan_url":"https://archive.org/details/lettersofdelegat25smit/page/452","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Madison Papers). Madison, Papers (Rutland), 11:328-30. 'See ibid., pp. 313-14. 2 Madison is referring to his letter of October 17 rather than that of October 28.","authors":["james-madison"],"paras":[["h","James Madison to Edmund Randolph"],["p","My dear friend N York Novr. 2. 1 788"],["p","I reed, yesterday your favor of the 23d Ult.1 The first countenance of the Assembly corresponds with the picture which my imagination had formed of it. The views of the greater part of the opposition to the federal Government, and particularly of its principal leader, have ever since the Convention, been regarded by me as permanently hostile, and likely to produce every effort that might endanger or embarrass it. The defects which drew forth objections from many quarters, were evidently of little consequence in the eye of Mr. H — ry. His own arguments proved it. His enmity was levelled, as he did not scruple to insinuate agst the whole System; and the destruction of the whole System, I take to be still the secret wish of his heart, and the real object of his pursuit. If temperate and rational alterations only were his plan, is it conceivable that his coalition and patronage would be extended to men whose particular ideas on the subject must differ more from his own than those of others who share most liberally in his hatred?"],["p","My last letter2 with Col. Carrington's communications to which it referred, will have sufficiently explained my sentiments with regard to the Legislative service under the new Constitution. My first wish is to see the Government put into quiet and successful operation; and to afford any service, that may be acceptable from me, for that purpose. My second wish, if that were to be consulted, would prefer, for reasons formerly hinted, an opportunity of contributing that service in the House of Reps, rather than in the Senate; provided the opportunity be attainable from the spontaneous suffrage of the Constituents: Should the real friends to the Constitution think this preference inconsistent with my primary object, as Col. Carrington tells me is the case with some who are entided to peculiar respect; and view my renouncing it as of any material consequence, I shall not hesitate to comply. You will not infer from the freedom with which these observations are made, that I am in the least unaware of the probability that whatever my inclinations or those of my friends may be, they are likely to be of little avail in the present case. I take it for certain that a clear majority of the Assembly are enemies to the Govt, and I have no reason to suppose that I can be less obnoxious than others on the opposite side. An election into the Senate therefore can hardly come into question. I know also that a good deal will depend on the arrangements for the election of the other branch; and that much may depend moreover on steps to be taken by the Candidates which will not be taken by me. Here again therefore there must be great uncertainty, if not improbability of my election. With these circumstances in view, it is impossible that I can be the dupe of false calculations, even if I were in other cases disposed to indulge them. I trust it is equally im-"],["p","possible for the result whatever it may be, to rob me of any reflections which enter into the internal fund of comfort & happiness. Popular favor or disfavor, is no criterion of the character maintained with those whose esteem an honorable ambition must court. Much less can it be a criterion of that maintained with ones self. And when the Spirit of party directs the public voice, it must be a little mind indeed that can suffer in its own estimation, or apprehend danger of suffering in that of others."],["p","The Sepr. British Packet arrived yesterday, but I do not find that she makes any addition to the Stock of European intelligence. The change in the French Ministry is the only event of late date of much consequence; and that had arrived through several other channels. I do not know that it is even yet authenticated; but it seems to be doubted by no one, particularly among those who can best decide on its credibility."],["p","With the utmost affection I am my dear Sir, Yrs. Sincerely,"],["p","Js. Madison Jr."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v25.0487":{"title":"Benjamin Franklin to Ebenezer Hazard","author_label":"Benjamin Franklin","kind":"letter","date":"1775-08-03","date_label":"August 3, 1775","date_type":"written","recipient":"Ebenezer Hazard","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 25","source_url":"https://archive.org/details/lettersofdelegat25smit","scan_url":"https://archive.org/details/lettersofdelegat25smit/page/557","text_status":"unreviewed_ocr","editorial_source_note":"Reprinted from Franklin, Papers (Labaree), 22:146-47.","authors":["benjamin-franklin"],"paras":[["h","Benjamin Franklin to Ebenezer Hazard"],["p","Sir, Philada.Aug. 3. 1775"],["p","I received your Application to be appointed Postmaster of New York,l and have seen a Recommendation of you by your Provincial Congress, to which I shall pay due Respect by appointing you accordingly as soon as Commissions and Instructions can be printed, and things got in Readiness to carry the Post through. In the mean time I wish to receive from you an Account of the present State of its Management, as far as is within your Knowledge; and am, Sir, Your most obedient humble Servant, B Franklin"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v25.0560":{"title":"John Hancock to Horatio Gates","author_label":"John Hancock","kind":"letter","date":"1777-08-05","date_label":"August 5, 1777","date_type":"written","recipient":"Horatio Gates","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 25","source_url":"https://archive.org/details/lettersofdelegat25smit","scan_url":"https://archive.org/details/lettersofdelegat25smit/page/630","text_status":"unreviewed_ocr","editorial_source_note":"RC (NNPM: Gilder Lehrman Collection).","authors":["john-hancock"],"paras":[["h","John Hancock to Horatio Gates"],["p","Sir Philada. August 5th. 1777."],["p","I inclose you sundry Resolutions of Congress respecting the Northern Department now under your Command1 to which I Beg leave to Refer your Attention, and am with respect, Sir, Your very huml Servt.,"],["p","John Hancock Presidt"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."}}});
